const ARMOR_MATERIAL_COLORS = {
  leather: "#8B5A2B",
  chainmail: "#8A8A8A",
  iron: "#C8C8C8",
  gold: "#E8C33A",
  diamond: "#3DD6CF",
  titanium: "#7F8FA6",
  pumpkin: "#E07B1A",
  jackOLantern: "#E07B1A",
  creeper: "#4CAF50",
  zombie: "#3E8E7E",
};

const ICON_THEME_COLORS = {
  fire: "#FF5555",
  earth: "#2DBE2D",
  thunder: "#FFFF55",
  water: "#55FFFF",
  air: "#E8E8E8",
  multi: "#FF55FF",
  basicWood: "#9A6A3A",
  basicGold: "#E8C33A",
  basicIron: "#C8C8C8",
  basicPearl: "#F3EEDF",
  basicGem: "#C04BD8",
  basicWedding: "#F5F5F5",
  basicCross: "#C8C8C8",
  basicBroach: "#E8C33A",
  phoenix: "#FF8C1A",
};

// Kolory tooltipa z gry: granatowe tło, ramka w kolorze rzadkości, jasny tekst; czcionka Pixelify Sans (najbliższa
// czcionce tooltipów w grze spośród otwartych).
const TOOLTIP = { text: "#F2EEFF", muted: "#A9AAC9", good: "#55FF55", bad: "#FF5555", ink: "#101228", bg: "#141A3C", bg2: "#0B0E22" };
const CARD_FONT = PIXEL_FONT;

function mixColor(hex, target, amount) {
  const from = [1, 3, 5].map((index) => parseInt(hex.slice(index, index + 2), 16));
  const to = [1, 3, 5].map((index) => parseInt(target.slice(index, index + 2), 16));
  return `#${from.map((value, index) => Math.round(value + (to[index] - value) * amount).toString(16).padStart(2, "0")).join("")}`;
}

function iconBaseColor(item) {
  if (item.category === "tome" || item.category === "aspect") return RARITY_COLORS[item.tier] || "#C8C8C8";
  const theme = item.icon || "";
  if (item.category === "armor") {
    const pale = theme.startsWith("pale_");
    const material = ARMOR_MATERIAL_COLORS[theme.replace(/^pale_/, "")] || ARMOR_MATERIAL_COLORS.iron;
    return pale ? mixColor(material, "#FFFFFF", 0.3) : material;
  }
  if (ICON_THEME_COLORS[theme]) return ICON_THEME_COLORS[theme];
  const element = item.elements[0];
  return element ? ELEMENT_STYLE[element].color : "#C8C8C8";
}

// Ikonka przedmiotu: sprite 16×16 z arkusza Wynnbuildera; zbroja i biżuteria (szare w arkuszu) dostają kolor
// materiału/żywiołu przez filtr mnożący, broń zostaje w oryginalnych kolorach. Typy spoza arkusza - stare ikonki.
function PixelIcon({ item, size = 48 }) {
  const index = ITEM_SHEET_ORDER.indexOf(item.type);
  if (index < 0) return <GridPixelIcon item={item} size={size} />;
  const tint = item.category === "weapon" ? null : iconBaseColor(item);
  const id = tint ? `wbr-tint-${tint.slice(1)}` : null;
  const channel = (offset) => (parseInt(tint.slice(offset, offset + 2), 16) / 255).toFixed(3);
  return (
    <svg viewBox="0 0 16 16" width={size} height={size} aria-hidden="true" style={{ imageRendering: "pixelated" }}>
      {tint && (
        <defs>
          <filter id={id} colorInterpolationFilters="sRGB">
            <feColorMatrix type="matrix" values={`${channel(1)} 0 0 0 0 0 ${channel(3)} 0 0 0 0 0 ${channel(5)} 0 0 0 0 0 1 0`} />
          </filter>
        </defs>
      )}
      <image href={ITEM_SHEET} x={-16 * index} y={0} width={192} height={16} preserveAspectRatio="none" filter={id ? `url(#${id})` : undefined} style={{ imageRendering: "pixelated" }} />
    </svg>
  );
}

function GridPixelIcon({ item, size = 48 }) {
  const grid = PIXEL_ICONS[item.type] || PIXEL_ICONS.ring;
  const base = iconBaseColor(item);
  const palette = {
    o: "#1B1024",
    m: base,
    l: mixColor(base, "#FFFFFF", 0.45),
    d: mixColor(base, "#000000", 0.4),
    g: base,
    G: mixColor(base, "#FFFFFF", 0.55),
    y: "#E8C33A",
    Y: "#B58A1E",
    w: "#9A6A3A",
    W: "#5C3A1A",
    x: "#D8D8D8",
  };
  const pixels = [];
  grid.forEach((row, y) => {
    [...row].forEach((cell, x) => {
      if (cell !== ".") pixels.push(<rect key={`${x}-${y}`} x={x} y={y} width="1" height="1" fill={palette[cell]} />);
    });
  });
  return (
    <svg viewBox="0 0 16 16" width={size} height={size} shapeRendering="crispEdges" aria-hidden="true">
      {pixels}
    </svg>
  );
}

// Ramka ikonki jak w tooltipie z gry: ciemny kwadrat ze skosem, w nim pikselowa ikonka.
function IconBox({ item, size = 48 }) {
  const ts = useTs();
  return (
    <div
      className="flex flex-shrink-0 items-center justify-center"
      style={ts({ width: size + 18, height: size + 18, background: "#2B2A36", border: "2px solid", borderColor: "#5C5A6C #14131A #14131A #5C5A6C", boxShadow: "inset 0 0 0 2px #1A1922" })}
    >
      <PixelIcon item={item} size={size} />
    </div>
  );
}

function TooltipBadge({ color, children }) {
  const ts = useTs();
  return (
    <span className="px-1.5 text-sm uppercase leading-5" style={ts({ background: color, color: TOOLTIP.ink })}>
      {children}
    </span>
  );
}

function TooltipDivider({ color }) {
  const ts = useTs();
  return (
    <div className="flex items-center gap-1" aria-hidden="true">
      <div className="h-px flex-1" style={ts({ background: color, opacity: 0.45 })} />
      <div className="h-1.5 w-1.5 rotate-45 border" style={ts({ borderColor: color })} />
      <div className="h-1.5 w-1.5 rotate-45 border" style={ts({ borderColor: color })} />
      <div className="h-px flex-1" style={ts({ background: color, opacity: 0.45 })} />
    </div>
  );
}

function ElementIcons({ elements, color }) {
  const ts = useTs();
  if (elements.length === 0) return null;
  return (
    <div className="flex w-max gap-1 px-1 py-0.5" style={ts({ background: color })} aria-label={`Elements: ${elements.join(", ")}`}>
      {elements.map((element) => (
        <span
          key={element}
          className="flex h-5 w-5 items-center justify-center text-sm leading-none"
          style={ts({ background: TOOLTIP.ink, color: ELEMENT_STYLE[element].color })}
          title={ELEMENT_STYLE[element].label}
        >
          {ELEMENT_STYLE[element].symbol}
        </span>
      ))}
    </div>
  );
}

// Sloty powderów w prawym górnym rogu tooltipa (jak w grze): ciemne kwadraty, do 3 w rzędzie.
function PowderSlots({ count, recommended = null, applied = null, level = 120 }) {
  const ts = useTs();
  if (!count) return null;
  const element = applied ? applied.element : recommended;
  const style = element ? ELEMENT_STYLE[element] : null;
  const title = applied
    ? `${count} powder slot${count === 1 ? "" : "s"} · ${powderLabel(applied)} powders, counted in the damage and the score`
    : style
      ? `${count} powder slot${count === 1 ? "" : "s"} · recommended: Tier ${ROMAN[powderTierFor(level) - 1]} ${style.label} powders (see the Powders panel)`
      : `${count} powder slot${count === 1 ? "" : "s"}`;
  return (
    <div className="grid flex-shrink-0 gap-1" style={ts({ gridTemplateColumns: `repeat(${Math.min(3, count)}, 16px)` })} aria-label={title} title={title}>
      {Array.from({ length: count }, (_, index) => {
        // Mieszanka powderów: każdy slot w kolorze swojego żywiołu.
        // (Creator: powderów może być mniej niż slotów - reszta slotów zostaje pusta)
        const slotStyle = applied && applied.list ? (applied.list[index] ? ELEMENT_STYLE[applied.list[index].element] : null) : style;
        const on = Boolean(applied && slotStyle);
        return (
          <span
            key={index}
            className="flex h-4 w-4 items-center justify-center text-xs leading-none"
            style={ts({ background: on ? mixColor(slotStyle.color, "#0A0C1E", 0.7) : "#0A0C1E", border: "2px solid", borderColor: on ? `${slotStyle.color} #050612 #050612 ${slotStyle.color}` : "#050612 #2C3160 #2C3160 #050612", color: slotStyle ? slotStyle.color : "transparent", opacity: on ? 1 : 0.8 })}
          >
            {slotStyle ? slotStyle.symbol : ""}
          </span>
        );
      })}
    </div>
  );
}

// Pole wyboru jak w grze: zielony ptaszek (spełnione), czerwony krzyżyk (niespełnione), puste (nie dotyczy).
function CheckBox({ state }) {
  const ts = useTs();
  const color = state === "yes" ? TOOLTIP.good : state === "no" ? TOOLTIP.bad : "#5A5470";
  return (
    <span
      className="inline-flex h-3.5 w-3.5 flex-shrink-0 items-center justify-center align-middle leading-none"
      style={ts({ border: `2px solid ${color}`, background: state === "none" ? "transparent" : "#0A0C1E", color, fontSize: 11 })}
      aria-hidden="true"
    >
      {state === "yes" ? "✓" : state === "no" ? "✗" : ""}
    </span>
  );
}

// ID, której roll faktycznie zmienia wartość (np. +1 tier Attack Speed rolluje 1-1, więc w grze nie ma "[xx%]").
function idVaries(item, key) {
  if (!idRolls(item, key)) return false;
  const [worst, best] = rollRange(key, item.baseIds[key]);
  return worst !== best;
}

// Średni roll przedmiotu (jak "[60.2%]" przy nazwie w grze): średnia procentów wszystkich rollujących ID.
// WAGI PRZEDMIOTÓW Z WYNNPOOL (src/item-weights.json, skrypt scripts/update-item-weights.mjs, dane na licencji MIT).
// Zespół Wynnpool Weight Team ocenia, które identyfikacje naprawdę liczą się na danym przedmiocie. Profil to zestaw
// wag, których wartości bezwzględne sumują się do 1. Wynik profilu = suma(procent rolla × waga) w skali 0-100,
// liczony tak samo jak na wynnpool.com (waga ujemna odwraca procent: im niższy roll, tym lepiej).
const WYNNPOOL_PROFILES = new Map();
((WYNNPOOL_DATA && WYNNPOOL_DATA.weights) || []).forEach((entry) => {
  const list = WYNNPOOL_PROFILES.get(entry.item);
  if (list) list.push(entry);
  else WYNNPOOL_PROFILES.set(entry.item, [entry]);
});
const WYNNPOOL_SITE = (WYNNPOOL_DATA && WYNNPOOL_DATA.site) || "https://www.wynnpool.com";
const WYNNPOOL_CREDIT = (WYNNPOOL_DATA && WYNNPOOL_DATA.credit) || "Wynnpool Weight Team";

function wynnpoolProfiles(item) {
  return (item && WYNNPOOL_PROFILES.get(item.name)) || [];
}

function hasWynnpoolData() {
  return WYNNPOOL_PROFILES.size > 0;
}

// Procent rolla użyty w wyniku; identyfikacje, które nie rollują (stałe, punkty umiejętności), liczą się jako 100%.
function wynnpoolRollPercent(item, key, rolls) {
  if (!item.baseIds || !item.baseIds[key]) return null;
  return idRolls(item, key) ? rollPercent(rolls, key) : 100;
}

function wynnpoolScore(item, profile, rolls) {
  if (!item || !profile) return null;
  const use = rolls === undefined ? item.rolls : rolls;
  let total = 0;
  let covered = 0;
  Object.entries(profile.ids).forEach(([key, weight]) => {
    const percent = wynnpoolRollPercent(item, key, use);
    if (percent === null) return;
    total += weight < 0 ? (100 - percent) * -weight : percent * weight;
    covered += Math.abs(weight);
  });
  return covered > 0 ? total / covered : null;
}

// Profil o najwyższym wyniku przy obecnych rollach - to jego wynik pokazuje odznaka na karcie przedmiotu.
function bestWynnpoolScore(item, rolls) {
  let best = null;
  wynnpoolProfiles(item).forEach((profile) => {
    const score = wynnpoolScore(item, profile, rolls);
    if (score !== null && (!best || score > best.score)) best = { profile, score };
  });
  return best;
}

// Rolle "pod profil": ważone identyfikacje na maksa (przy wadze ujemnej na minimum), reszta zostaje na 50%.
function wynnpoolTargetRolls(item, profile) {
  const rolls = {};
  Object.entries(profile.ids).forEach(([key, weight]) => {
    if (!item.baseIds[key] || !idRolls(item, key)) return;
    rolls[key] = weight < 0 ? 0 : 100;
  });
  return Object.keys(rolls).length > 0 ? rolls : null;
}

// Wagi profilu posortowane od najważniejszej, z etykietami z ID_DISPLAY (te same nazwy co w reszcie aplikacji).
function wynnpoolLines(profile) {
  return Object.entries(profile.ids)
    .sort((a, b) => Math.abs(b[1]) - Math.abs(a[1]))
    .map(([key, weight]) => {
      const display = ID_DISPLAY.find((entry) => entry.key === key);
      return { key, weight, label: display ? display.label : (STAT_META[key] && STAT_META[key].label) || key };
    });
}

function wynnpoolSummary(profile) {
  return wynnpoolLines(profile)
    .slice(0, 4)
    .map((line) => `${line.label} ${Math.round(line.weight * 100)}%`)
    .join(", ");
}

function overallRoll(item) {
  const keys = ID_DISPLAY.filter((display) => item.ids[display.key] && idVaries(item, display.key)).map((display) => display.key);
  if (keys.length === 0) return null;
  return keys.reduce((sum, key) => sum + rollPercent(item.rolls, key), 0) / keys.length;
}

// Wiersz umiejętności jak w grze: wszystkie pięć rombów, wymagane podświetlone kolorem umiejętności, pod spodem
// pole wyboru (spełnione/niespełnione przez Skill Pointy buildu) i wymagana wartość.
// equipOrderOk: zestaw przechodzi sprawdzenie Skill Pointów w kolejności zakładania z gry - wtedy każde wymaganie
// było spełnione w chwili zakładania przedmiotu, nawet jeśli przedmiot z ujemnym bonusem (zakładany na końcu)
// obniża potem sumę poniżej wymagania. Bez tego karta pokazywała czerwone ✗ przy poprawnym buildzie.
function SkillRow({ reqs, totals, equipOrderOk = false }) {
  const ts = useTs();
  return (
    <div className="grid grid-cols-5 gap-1">
      {SKILLS.map((skill) => {
        const req = reqs[skill] || 0;
        const required = req > 0;
        const met = equipOrderOk || (totals[skill] || 0) >= req;
        const skillColor = SKILL_STYLE[skill].color;
        return (
          <div
            key={skill}
            className="flex flex-col items-center gap-2"
            title={
              required
                ? `${SKILL_LABELS[skill]} Min: ${req} (build has ${totals[skill] || 0}${equipOrderOk && (totals[skill] || 0) < req ? "; met when equipped - items with negative skill points go on last" : ""})`
                : `No ${SKILL_LABELS[skill]} requirement`
            }
          >
            <span className="px-1 text-xs leading-5 tracking-wider" style={ts({ background: "#262A50", color: required ? TOOLTIP.text : "#6E6C8C" })}>
              {SKILL_STYLE[skill].short.toUpperCase()}
            </span>
            <div
              className="flex h-8 w-8 items-center justify-center"
              style={ts({
                transform: "rotate(45deg)",
                background: required ? mixColor(skillColor, "#0A0C1E", 0.8) : "#171A33",
                border: `2px solid ${required ? skillColor : "#33375C"}`,
                boxShadow: required ? `0 0 8px ${skillColor}66, inset 0 0 0 2px #0A0C1E` : "inset 0 0 0 2px #0F1128",
              })}
            >
              <span className="text-base leading-none" style={ts({ transform: "rotate(-45deg)", color: required ? skillColor : "#4A4D70" })}>
                {SKILL_STYLE[skill].symbol}
              </span>
            </div>
            <span className="flex items-center gap-1 text-sm tabular-nums" style={ts({ color: required ? (met ? TOOLTIP.good : TOOLTIP.bad) : "#6E6C8C" })}>
              <CheckBox state={required ? (met ? "yes" : "no") : "none"} />
              {req}
            </span>
          </div>
        );
      })}
    </div>
  );
}

// Najważniejsze identyfikacje przedmiotu do zwiniętej karty: największe dodatnie (względem typowej skali statystyki)
// i jedna najgorsza ujemna, żeby od razu było widać, co przedmiot daje i co zabiera.
function keyIdLines(item, limit = 4) {
  const scored = ID_DISPLAY.filter((display) => item.ids[display.key]).map((display) => {
    const value = item.ids[display.key];
    const good = display.invert ? value < 0 : value > 0;
    const meta = STAT_META[display.key];
    const scale = (meta && meta.scale) || (display.unit === "%" ? 10 : 50);
    return { display, value, good, weight: Math.abs(value) / scale };
  });
  const goodLines = scored.filter((entry) => entry.good).sort((a, b) => b.weight - a.weight).slice(0, limit);
  const worst = scored.filter((entry) => !entry.good).sort((a, b) => b.weight - a.weight)[0];
  return worst ? [...goodLines, worst] : goodLines;
}

// Zwinięta karta: wymagania jako małe plakietki (tylko niezerowe) + HP + kluczowe identyfikacje.
function CompactItemSummary({ item, build, classOk, levelOk, playerClass }) {
  const ts = useTs();
  const equipOrderOk = Boolean(build.skillPoints.valid);
  const chip = "inline-flex items-center gap-1 border px-1.5 py-0.5 text-sm tabular-nums leading-none";
  const lines = keyIdLines(item);
  return (
    <div className="flex flex-col gap-2">
      <div className="flex flex-wrap gap-1.5">
        <span className={chip} style={ts({ borderColor: levelOk ? "#2F6B2F" : "#8A2A2A", color: TOOLTIP.text, background: "#0A0C1E" })} title={`Combat Level ${item.level}`}>
          Lv {item.level}
          <span style={ts({ color: levelOk ? TOOLTIP.good : TOOLTIP.bad })}>{levelOk ? "✓" : "✗"}</span>
        </span>
        {item.category === "weapon" && !classOk && (
          <span className={chip} style={ts({ borderColor: "#8A2A2A", color: TOOLTIP.bad, background: "#0A0C1E" })}>
            Wrong class ✗
          </span>
        )}
        {SKILLS.filter((skill) => (item.reqs[skill] || 0) > 0).map((skill) => {
          const req = item.reqs[skill];
          const have = build.skillPoints.totals[skill] || 0;
          const met = equipOrderOk || have >= req;
          const skillColor = SKILL_STYLE[skill].color;
          return (
            <span
              key={skill}
              className={chip}
              style={ts({ borderColor: skillColor, color: skillColor, background: mixColor(skillColor, "#0A0C1E", 0.85) })}
              title={`${SKILL_LABELS[skill]} Min: ${req} (build has ${have}${equipOrderOk && have < req ? "; met when equipped - items with negative skill points go on last" : ""})`}
            >
              {SKILL_STYLE[skill].symbol} {SKILL_STYLE[skill].short.toUpperCase()} {req}
              <span style={ts({ color: met ? TOOLTIP.good : TOOLTIP.bad })}>{met ? "✓" : "✗"}</span>
            </span>
          );
        })}
        {SKILLS.every((skill) => !(item.reqs[skill] > 0)) && (
          <span className={chip} style={ts({ borderColor: "#33375C", color: TOOLTIP.muted, background: "#0A0C1E" })}>
            No skill req.
          </span>
        )}
        {item.base && item.base.hp ? (
          <span className={chip} style={ts({ borderColor: "#8A2A2A", color: "#FF7777", background: "#1E0A10" })} title="Base Health">
            ❤ {formatNumber(item.base.hp)}
          </span>
        ) : null}
      </div>
      {lines.length > 0 && (
        <ul className="flex flex-col gap-0.5 text-sm">
          {lines.map(({ display, value, good }) => (
            <li key={display.key} className="flex items-baseline justify-between gap-3">
              <span className="min-w-0 truncate" style={ts({ color: good ? TOOLTIP.text : TOOLTIP.muted })}>
                {idLabel(display, playerClass)}
              </span>
              <span className="whitespace-nowrap font-bold tabular-nums" style={ts({ color: good ? TOOLTIP.good : TOOLTIP.bad })}>
                {formatIdValue(display, value)}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function formatIdValue(display, value) {
  return `${value > 0 ? "+" : ""}${formatNumber(value)}${display.unit}`;
}

function titleCase(constant) {
  return constant
    .toLowerCase()
    .split("_")
    .map((word) => capitalize(word))
    .join(" ");
}

function weaponFocusShare(item, profile) {
  const damage = item.damage || {};
  const total = Object.values(damage).reduce((sum, value) => sum + value, 0);
  if (total === 0) return 0;
  const chosen = profile.elements.reduce((sum, element) => sum + (damage[element] || 0), 0);
  return chosen / total;
}

// Blok broni jak w grze: duży DPS, szybkość ataku z uderzeniami/s, zakresy obrażeń per żywioł w jednym wierszu.
function WeaponBlock({ item, profile }) {
  const ts = useTs();
  const hitsPerSecond = HITS_PER_SECOND[item.atkSpd];
  const withBonuses = Math.round(weaponMainAttackDps(item));
  return (
    <div className="flex flex-col gap-1">
      <p
        className="leading-none"
        style={ts({ color: TOOLTIP.text })}
        title={
          item.powders
            ? `Damage per second as on the tooltip of the powdered weapon (${powderLabel(item.powders)}): average damage × hits per second. Identifications, skill points and the ability tree are not included.`
            : "Damage per second as on the in-game tooltip: average base damage × hits per second (Normal = 2.05/s). Identifications, skill points, powders and the ability tree are not included."
        }
      >
        <span className="text-3xl">{formatNumber(item.dps || 0)}</span> <span className="text-lg">DPS</span>
      </p>
      <p className="text-sm" style={ts({ color: TOOLTIP.muted })}>
        <span aria-hidden="true">⚔</span> {ATTACK_SPEED_LABELS[item.atkSpd] || item.atkSpd}
        {hitsPerSecond ? ` (${hitsPerSecond} hits/s)` : ""}
      </p>
      <p className="flex flex-wrap gap-x-3 gap-y-0.5 text-base">
        {Object.entries(item.damageRanges || {}).map(([element, range]) => (
          <span key={element} className="whitespace-nowrap" title={`${ELEMENT_STYLE[element].label} damage`}>
            <span style={ts({ color: ELEMENT_STYLE[element].color })}>{ELEMENT_STYLE[element].symbol}</span>{" "}
            <span className="tabular-nums" style={ts({ color: TOOLTIP.text })}>
              {range}
            </span>
          </span>
        ))}
      </p>
      {item.powders && (
        <div className="flex items-baseline justify-between gap-3 text-xs" title="Custom stats › Weapon powders: every slot gets the highest powder tier for the weapon's level. The damage above, the score and the summary include them.">
          <span style={ts({ color: TOOLTIP.muted })}>With {powderLabel(item.powders)} powders</span>
          <span className="tabular-nums" style={ts({ color: TOOLTIP.muted })}>
            base {formatNumber(item.baseWeapon.dps || 0)} DPS
          </span>
        </div>
      )}
      {withBonuses !== Math.round(item.dps || 0) && (
        <div className="flex items-baseline justify-between gap-3 text-xs" title="Main attack DPS with this weapon's own bonuses (raw per hit × hits per second, %), before skill points">
          <span style={ts({ color: TOOLTIP.muted })}>With its own bonuses</span>
          <span className="tabular-nums" style={ts({ color: TOOLTIP.text })}>
            {formatNumber(withBonuses)} DPS
          </span>
        </div>
      )}
      {profile.customElements && (
        <div
          className="flex items-baseline justify-between gap-3 text-xs"
          title="Your damage focus is a preference: damage outside it doesn't get the focused elements' bonuses, so the weapon's DPS counts only partly. A weapon outside your focus wins only when nothing in focus comes close."
        >
          <span style={ts({ color: TOOLTIP.muted })}>Damage in your focus</span>
          <span className="tabular-nums" style={ts({ color: weaponFocusShare(item, profile) > 0 ? TOOLTIP.text : TOOLTIP.bad })}>
            {Math.round(weaponFocusShare(item, profile) * 100)}% · counted {Math.round(weaponElementFactor(item, profile) * 100)}%
          </span>
        </div>
      )}
    </div>
  );
}

function BaseStats({ item }) {
  const ts = useTs();
  const defences = ELEMENTS.map((element) => ({ element, value: item.base[`${element.charAt(0)}Def`] || 0 })).filter((entry) => entry.value);
  if (!item.base.hp && defences.length === 0) return null;
  return (
    <div className="flex flex-col gap-1">
      {item.base.hp ? (
        <p className="leading-none" style={ts({ color: TOOLTIP.text })}>
          <span className="text-3xl">
            {item.base.hp > 0 ? "+" : ""}
            {formatNumber(item.base.hp)}
          </span>{" "}
          <span className="text-lg">Health</span>
        </p>
      ) : null}
      {defences.map(({ element, value }) => (
        <div key={element} className="flex items-baseline justify-between gap-3 text-base">
          <span style={ts({ color: ELEMENT_STYLE[element].color })}>
            {ELEMENT_STYLE[element].symbol} {ELEMENT_STYLE[element].label} Defence
          </span>
          <span className="tabular-nums" style={ts({ color: value > 0 ? TOOLTIP.good : TOOLTIP.bad })}>
            {value > 0 ? "+" : ""}
            {formatNumber(value)}
          </span>
        </div>
      ))}
    </div>
  );
}

// Nazwy czarów klasy zamiast "1st Spell Cost" (jak w grze) i grupy identyfikacji rozdzielone odstępem
// (Skill Pointy, obrażenia, HP/mana/obrony, reszta, koszty czarów).
const CLASS_SPELL_NAMES = {
  Warrior: ["Bash", "Charge", "Uppercut", "War Scream"],
  Mage: ["Heal", "Teleport", "Meteor", "Ice Snake"],
  Archer: ["Arrow Storm", "Escape", "Arrow Bomb", "Arrow Shield"],
  Assassin: ["Spin Attack", "Dash", "Multihit", "Smoke Bomb"],
  Shaman: ["Totem", "Haul", "Aura", "Uproot"],
};
const CLASS_TYPE_NAMES = { Warrior: "Warrior/Knight", Mage: "Mage/Dark Wizard", Archer: "Archer/Hunter", Assassin: "Assassin/Ninja", Shaman: "Shaman/Skyseer" };
const ID_GROUP_ORDER = ["skills", "damage", "sustain", "misc", "costs"];
function idGroup(key) {
  if (SKILLS.includes(key)) return "skills";
  if (/^sp(Raw|Pct)[1-4]$/.test(key)) return "costs";
  if (/Dam(Pct|Raw)$|^(sd|md)(Pct|Raw)$|(Sd|Md)(Pct|Raw)$|^(critDamPct|atkTier|poison|expd|mainAttackRange|kb|slowEnemy|weakenEnemy)$/.test(key)) return "damage";
  if (/^(hpBonus|hprRaw|hprPct|ls|ms|mr|maxMana|healPct|thorns|ref)$|DefPct$/.test(key)) return "sustain";
  return "misc";
}

function idLabel(display, playerClass) {
  const spell = display.key.match(/^sp(?:Raw|Pct)([1-4])$/);
  if (spell && CLASS_SPELL_NAMES[playerClass]) return `${CLASS_SPELL_NAMES[playerClass][Number(spell[1]) - 1]} Cost`;
  return display.label;
}

function IdentificationList({ item, relevant, playerClass }) {
  const ts = useTs();
  const lines = ID_DISPLAY.filter((display) => item.ids[display.key]);
  if (lines.length === 0) return <p className="text-sm" style={ts({ color: TOOLTIP.muted })}>No identifications</p>;
  const groups = ID_GROUP_ORDER.map((group) => lines.filter((display) => idGroup(display.key) === group)).filter((group) => group.length > 0);
  return (
    <div className="flex flex-col gap-3">
      {groups.map((group, index) => (
        <ul key={index} className="flex flex-col gap-0.5 text-base">
          {group.map((display) => {
            const value = item.ids[display.key];
            const good = display.invert ? value < 0 : value > 0;
            const counts = relevant.has(display.key);
            const rolls = idVaries(item, display.key);
            const percent = rolls ? rollPercent(item.rolls, display.key) : null;
            const [worst, best] = rolls ? rollRange(display.key, item.baseIds[display.key]) : [value, value];
            return (
              <li key={display.key} className="flex items-baseline justify-between gap-3">
                <span style={ts({ color: counts ? TOOLTIP.text : TOOLTIP.muted })} title={counts ? "Counts toward this build's score" : "Doesn't add to the score with your settings"}>
                  {idLabel(display, playerClass)}
                </span>
                <span
                  className="whitespace-nowrap tabular-nums"
                  style={ts({ color: good ? TOOLTIP.good : TOOLTIP.bad })}
                  title={rolls ? `Roll ${percent}% of ${formatIdValue(display, worst)} to ${formatIdValue(display, best)} (base ${formatIdValue(display, item.baseIds[display.key])})` : "Doesn't roll"}
                >
                  {formatIdValue(display, value)}
                  {rolls && (
                    <span className="ml-1 text-sm" style={ts({ color: rollColor(percent) })}>
                      [{percent.toFixed(1)}%]
                    </span>
                  )}
                </span>
              </li>
            );
          })}
        </ul>
      ))}
      {item.fixed && (
        <p className="text-xs" style={ts({ color: TOOLTIP.muted })}>
          Fixed IDs, no rolls.
        </p>
      )}
      {item.set && ITEM_SETS[item.set] && (
        <p className="text-xs" style={ts({ color: TOOLTIP.good })}>
          {item.set} set item.
        </p>
      )}
    </div>
  );
}

// Etykieta i wzór pozycji rozpiski wyniku (identyfikacja albo pozycja specjalna: DPS broni, okno poziomu,
// udział w dokładnym DPS main attacku zestawu, kara za deficyt HP).
function contributionLabel(entry, profile = null) {
  const meta = STAT_META[entry.key];
  const weight = profile ? profile.weights[entry.key] : null;
  switch (entry.key) {
    case "dps":
      return { label: `Weapon DPS ${formatNumber(entry.value)}`, math: profile ? `÷ 100 × ${profile.weaponWeight.toFixed(1)}` : "" };
    case "levelGap":
      return { label: `Level ${entry.value} item, far below yours`, math: `−${Math.round((profile ? profile.tuning.levelGapPenalty : LEVEL_GAP_PENALTY) * 100)}% per level below` };
    case "mainAttack":
      return {
        label: `${entry.value >= 0 ? "+" : ""}${formatNumber(Math.round(entry.value))} real main attack DPS in this build`,
        math: "replaces its linear main attack points",
      };
    case "hpDeficit":
      return { label: "Build health below the class base", math: "health deficit penalty" };
    case "setBonus":
      return { label: `${entry.value} set bonus in this build`, math: "set bonus identifications × weights" };
    case "offSkill":
      return { label: `Requires ${entry.value} (skills the archetype doesn't use)`, math: `−${formatNumber(Math.round((profile ? profile.tuning.offSkillPenalty : OFF_SKILL_REQ_PENALTY) * SCORE_SCALE * 10) / 10)} per 25 points` };
    case "skillPoints":
      return {
        label: entry.value > 0 ? `Needs ${entry.value} more skill points in this build` : `Frees ${-entry.value} skill points in this build`,
        math: `${entry.value > 0 ? "−" : "+"}${formatNumber(Math.round((profile ? profile.tuning.leftoverSp : LEFTOVER_SP_VALUE) * SCORE_SCALE * 10) / 10)} per point`,
      };
    default:
      return { label: meta ? `${formatStatValue(entry.key, entry.value)} ${meta.label}` : entry.key, math: meta && weight ? `÷ ${meta.scale} × ${Math.abs(weight).toFixed(1)}` : "" };
  }
}

// Tooltip na "score": z czego składa się wynik przedmiotu (wartość ÷ jednostka × waga × 10).
function scoreBreakdownTitle(slot) {
  const lines = (slot.contributions || [])
    .filter((entry) => Math.abs(entry.contribution) >= 0.05)
    .sort((a, b) => Math.abs(b.contribution) - Math.abs(a.contribution))
    .slice(0, 6)
    .map((entry) => `${contributionLabel(entry).label}: ${entry.contribution >= 0 ? "+" : ""}${formatScore(entry.contribution)}`);
  return ["How much this item adds to the build score (×10):", ...lines, "Open 'How is the score calculated?' above the cards for the rules."].join("\n");
}

// Strony karty (kropki na dole jak w grze): przedmiot, jak zdobyć, z czego składa się wynik.
const CARD_PAGES = [
  { id: "item", label: "Item" },
  { id: "obtain", label: "How to get it" },
  { id: "score", label: "Score breakdown" },
];

function CardPager({ page, onChange }) {
  const ts = useTs();
  return (
    <div className="flex items-center justify-center gap-2" role="tablist" aria-label="Card pages">
      {CARD_PAGES.map((entry, index) => (
        <button
          key={entry.id}
          type="button"
          role="tab"
          aria-selected={page === index}
          aria-label={entry.label}
          title={entry.label}
          onClick={() => onChange(index)}
          className="flex h-5 w-5 items-center justify-center focus:outline-none focus:ring-2 focus:ring-amber-500"
        >
          <span className="block h-2.5 w-2.5" style={ts({ background: page === index ? "#FFAA00" : "#3B3F6A", boxShadow: page === index ? "0 0 6px #FFAA0088" : "none" })} />
        </button>
      ))}
      <span className="ml-1 text-xs" style={ts({ color: TOOLTIP.muted })}>
        {CARD_PAGES[page].label}
      </span>
    </div>
  );
}

function ScorePage({ slot, build }) {
  const ts = useTs();
  const entries = [...(slot.contributions || [])]
    .filter((entry) => Math.abs(entry.contribution) >= 0.05)
    .sort((a, b) => Math.abs(b.contribution) - Math.abs(a.contribution))
    .slice(0, 12);
  return (
    <div className="flex flex-col gap-2">
      <p className="text-sm" style={ts({ color: TOOLTIP.muted })}>
        What this item adds to the build score (×10) with your settings. Values ÷ unit × {build.archetype} weight; see "How is the score
        calculated?" above the cards.
      </p>
      {entries.length === 0 ? (
        <p className="text-sm" style={ts({ color: TOOLTIP.muted })}>Nothing on this item counts with the current weights.</p>
      ) : (
        <ul className="flex flex-col gap-0.5 text-base">
          {entries.map((entry) => {
            const { label } = contributionLabel(entry, build.profile);
            return (
              <li key={entry.key} className="flex items-baseline justify-between gap-3">
                <span style={ts({ color: TOOLTIP.text })}>{label}</span>
                <span className="whitespace-nowrap tabular-nums" style={ts({ color: entry.contribution >= 0 ? TOOLTIP.good : TOOLTIP.bad })}>
                  {entry.contribution >= 0 ? "+" : ""}
                  {formatScore(entry.contribution)}
                </span>
              </li>
            );
          })}
        </ul>
      )}
      {build && build.mode === "damage" && (
        <p style={ts({ color: TOOLTIP.muted })}>Damage first: the build is chosen by the number below, with effective HP and mana as filters.</p>
      )}
      <div className="flex items-baseline justify-between gap-3 border-t pt-1 text-base" style={ts({ borderColor: "#2A2F58" })}>
        <span style={ts({ color: TOOLTIP.text })}>{build && build.mode === "damage" ? `${build.goalName || "Damage"} lost without it` : "Score in this build"}</span>
        <span className="tabular-nums" style={ts({ color: "#FFAA00" })}>
          {buildScoreText(build, slot.score)}
        </span>
      </div>
    </div>
  );
}

// Karta przedmiotu. Zwinięta (open = false): tylko nazwa, wymagania (Skill Pointy, klasa, poziom) i akcje;
// strzałka ▼/▲ rozwija resztę (statystyki, identyfikacje, cena, strony karty).
function ItemCard(props) {
  return (
    <GameCardContext.Provider value={true}>
      <ItemCardInner {...props} />
    </GameCardContext.Provider>
  );
}

function ItemCardInner({ slot, build, actions, powder = null, open = true, onToggle = null }) {
  const ts = useTs();
  const wide = "";
  const { attackSpeeds } = build.options;
  const [page, setPage] = useState(0);
  if (!slot.item && (slot.crafted || slot.missing)) {
    return (
      <article
        className={`wbr-card flex flex-col items-start gap-2 border-2 border-dashed border-zinc-600 p-4 text-sm ${wide}`}
        style={ts({ fontFamily: CARD_FONT, background: TOOLTIP.bg2 })}
      >
        <span className="text-xs uppercase tracking-widest text-zinc-500">{slot.label}</span>
        <div className="flex items-center gap-3">
          <PixelIcon item={{ type: slot.type === "weapon" ? build.profile && CLASSES[build.playerClass].weapon : slot.type, category: slot.type === "weapon" ? "weapon" : ["ring", "bracelet", "necklace"].includes(slot.type) ? "accessory" : "armor", icon: "iron", elements: [] }} size={40} />
          <div className="flex flex-col">
            <span className="text-base" style={ts({ color: "#55FFFF" })}>{slot.crafted ? `Crafted ${slot.crafted}` : slot.missing}</span>
            <span className="text-xs text-zinc-500">
              {slot.crafted ? "Crafted items aren't in the item database. Open the build in Wynnbuilder to see it." : "Not found in this item database version."}
            </span>
          </div>
        </div>
      </article>
    );
  }
  if (!slot.item && actions && actions.onChoose) {
    // Creator / Optimizer: pusty slot gracza - wybór przedmiotu (i w Optimizerze informacja, że Optimize go uzupełni)
    return (
      <article
        className={`wbr-card flex flex-col items-start justify-center gap-2 border-2 border-dashed border-zinc-600 p-4 text-sm ${wide}`}
        style={ts({ fontFamily: CARD_FONT, background: TOOLTIP.bg2 })}
      >
        <span className="text-xs uppercase tracking-widest text-zinc-500">{slot.label}</span>
        <p className="text-zinc-300">Empty slot</p>
        {actions.emptyHint && <p className="wbr-fill-hint text-xs">{actions.emptyHint}</p>}
        <button type="button" onClick={() => actions.onChoose(slot.id)} className="mc-btn mc-btn-sm mc-btn-primary">
          Choose {slot.type === "weapon" ? "weapon" : slot.type === "ring" ? "ring" : slot.label.toLowerCase()}
        </button>
      </article>
    );
  }
  if (!slot.item) {
    const speedFiltered = slot.id === "weapon" && attackSpeeds.length > 0;
    return (
      <article
        className={`wbr-card flex flex-col justify-center gap-1 border-2 border-dashed border-zinc-700 p-4 text-sm ${wide}`}
        style={ts({ fontFamily: CARD_FONT, background: TOOLTIP.bg2 })}
      >
        <span className="text-xs uppercase tracking-widest text-zinc-500">{slot.label}</span>
        <p className="text-zinc-300">Slot left empty</p>
        <p className="text-xs text-zinc-500">
          {speedFiltered
            ? `No weapon with a checked attack speed (${attackSpeeds.map((speed) => ATTACK_SPEED_LABELS[speed]).join(", ")}) up to level ${build.level} fits this build.`
            : `No ${slot.type === "weapon" ? "weapon" : slot.type} up to level ${build.level} adds value without breaking the skill point budget.`}
        </p>
      </article>
    );
  }
  const { item } = slot;
  const color = RARITY_COLORS[item.tier] || RARITY_COLORS.Normal;
  const relevant = new Set(
    slot.contributions.filter((entry) => entry.contribution > 0).flatMap((entry) => (entry.key === "hp" ? ["hpBonus"] : [entry.key]))
  );
  const pinned = Boolean(actions && actions.lockedSlots.has(slot.id));
  const guideCount = (GUIDE_ITEM_COUNTS[build.archetype] || {})[item.name];
  const wynnpool = bestWynnpoolScore(item);
  const overall = overallRoll(item);
  const levelOk = item.level <= build.level;
  const classOk = item.category !== "weapon" || WEAPON_CLASS[item.type] === build.playerClass;
  const collapsed = Boolean(onToggle) && !open;
  const requirements = (
    <>
      <SkillRow reqs={item.reqs} totals={build.skillPoints.totals} equipOrderOk={Boolean(build.skillPoints.valid)} />
      <div className="flex flex-col gap-0.5 text-base">
        {item.category === "weapon" && (
          <div className="flex items-baseline justify-between gap-3">
            <span className="flex items-center gap-1.5" style={ts({ color: TOOLTIP.text })}>
              <CheckBox state={classOk ? "yes" : "no"} /> Class Type
            </span>
            <span style={ts({ color: TOOLTIP.muted })}>{CLASS_TYPE_NAMES[WEAPON_CLASS[item.type]] || WEAPON_CLASS[item.type]}</span>
          </div>
        )}
        <div className="flex items-baseline justify-between gap-3">
          <span className="flex items-center gap-1.5" style={ts({ color: TOOLTIP.text })}>
            <CheckBox state={levelOk ? "yes" : "no"} /> Combat Level
          </span>
          <span className="tabular-nums" style={ts({ color: TOOLTIP.muted })}>
            {item.level}
          </span>
        </div>
      </div>
    </>
  );
  return (
    <article
      className={`wbr-card relative flex flex-col border-[3px] ${wide}`}
      style={{
        ...ts({ background: `linear-gradient(180deg, ${TOOLTIP.bg} 0%, ${TOOLTIP.bg2} 100%)`, fontFamily: CARD_FONT }),
        // ramka w kolorze rzadkości zawsze w oryginalnym (jasnym) kolorze; w jasnym motywie obwiedziona ciemną linią
        // z obu stron, żeby była wyraźna na jasnym tle
        borderColor: color,
        boxShadow: THEME === "light" ? "0 0 0 2px #1B1822, inset 0 0 0 2px #1B1822, 0 3px 0 rgba(27,24,34,.18)" : `inset 0 0 0 2px #070919, 0 0 12px ${color}22`,
      }}
    >
      <div className="flex items-center justify-between gap-2 px-3 py-1 text-xs uppercase tracking-widest" style={ts({ background: "#070919", color: TOOLTIP.muted })}>
        <span>
          {slot.label}
          {pinned && <span style={ts({ color: "#FFAA00" })}> · pinned</span>}
          {slot.proposed && (
            <span style={ts({ color: "#55FF55" })} title={slot.previous ? `Proposed by Optimize instead of ${slot.previous}` : "Proposed by Optimize for an empty slot"}>
              {" "}
              · proposed
            </span>
          )}
        </span>
        <MarketDot item={item} />
        {build && build.mode === "manual" ? null : (
        <button
          type="button"
          className="tabular-nums normal-case tracking-normal hover:text-white focus:outline-none focus:ring-2 focus:ring-amber-500"
          title={build && build.mode === "damage" ? `How much ${build.goalName || "damage"} the build loses without this item (every other slot stays).` : scoreBreakdownTitle(slot)}
          onClick={() => {
            if (collapsed) {
              onToggle();
              setPage(2);
            } else setPage(page === 2 ? 0 : 2);
          }}
          style={ts({ color: page === 2 && !collapsed ? "#FFAA00" : TOOLTIP.muted })}
        >
          {build && build.mode === "damage" ? "dmg" : "score"} {buildScoreText(build, slot.score)}
        </button>
        )}
      </div>
      <div className="flex flex-1 flex-col gap-2.5 p-3">
        <div className="flex items-start gap-3">
          <IconBox item={item} size={40} />
          <div className="flex min-w-0 flex-1 flex-col gap-1">
            <h3 className="text-lg leading-tight" style={ts({ color })}>
              <span style={ts({ overflowWrap: "anywhere" })}>{item.name}</span>
              {overall !== null && (
                <span className="ml-1 whitespace-nowrap text-base" style={ts({ color: rollColor(overall) })} title={item.rolls ? "Average of your identification rolls" : "All identifications at their max roll (100%), like Wynnbuilder"}>
                  [{overall.toFixed(1)}%]
                </span>
              )}
              {wynnpool && (
                <span
                  className="ml-1 whitespace-nowrap text-base"
                  style={ts({ color: "#55FFFF" })}
                  title={`Wynnpool "${wynnpool.profile.name}" score of these rolls: ${wynnpool.score.toFixed(1)}/100 (${wynnpoolSummary(wynnpool.profile)}). Open Rolls for every profile.`}
                >
                  WP {wynnpool.score.toFixed(0)}
                </span>
              )}
            </h3>
            {!collapsed && (
              <>
                <div className="flex flex-wrap gap-1">
                  <TooltipBadge color={color}>{item.tier}</TooltipBadge>
                  <TooltipBadge color={color}>{item.type}</TooltipBadge>
                  {guideCount ? (
                    <span title="Used in guide builds for this archetype">
                      <TooltipBadge color="#FFAA00">Guide ×{guideCount}</TooltipBadge>
                    </span>
                  ) : null}
                  {eventOf(item) ? (
                    <span title={`Limited-time: only from the ${eventOf(item)}`}>
                      <TooltipBadge color="#FF55FF">Event</TooltipBadge>
                    </span>
                  ) : null}
                </div>
                <ElementIcons elements={item.elements} color={color} />
              </>
            )}
          </div>
          {!collapsed && <PowderSlots count={item.slots} recommended={powder} applied={item.powders || null} level={item.level} />}
        </div>

        {collapsed ? (
          <CompactItemSummary item={item} build={build} classOk={classOk} levelOk={levelOk} playerClass={build.playerClass} />
        ) : page === 1 ? (
          <ObtainInfo item={item} color={color} />
        ) : page === 2 ? (
          <ScorePage slot={slot} build={build} />
        ) : (
          <>
            {item.category === "weapon" ? <WeaponBlock item={item} profile={build.profile} /> : <BaseStats item={item} />}

            <TooltipDivider color={color} />
            {requirements}
            <TooltipDivider color={color} />

            <IdentificationList item={item} relevant={relevant} playerClass={build.playerClass} />

            {item.majorIds.length > 0 && (
              <div className="flex flex-col gap-0.5 text-base" style={ts({ color: "#55FFFF" })}>
                {item.majorIds.map((major) => (
                  <span key={major}>+ Major ID: {titleCase(major)}</span>
                ))}
              </div>
            )}
          </>
        )}

        <div className="mt-auto flex flex-col gap-2 pt-1">
          {!collapsed && item && hasPriceData() && (
            <p className="text-xs" style={ts({ color: TOOLTIP.muted })} title="Trade Market price (WynnVentory, average of the middle 80% of listings)">
              {priceLabel(item)}
            </p>
          )}
          {!collapsed && item && hasLiveData() && !isUntradable(item) && (
            <p className="text-xs" style={ts({ color: marketStatus(item).state === "listed" ? "#55FF55" : TOOLTIP.muted })} title={marketTitle()}>
              {marketText(item)}
            </p>
          )}
          {!collapsed && <CardPager page={page} onChange={setPage} />}
          {onToggle && (
            <button
              type="button"
              onClick={onToggle}
              aria-expanded={open}
              aria-label={open ? `Hide ${item.name} details` : `Show ${item.name} details`}
              className="flex w-full items-center justify-center gap-2 py-0.5 text-xs hover:text-white focus:outline-none focus-visible:ring-2 focus-visible:ring-amber-500"
              style={ts({ color: TOOLTIP.muted })}
            >
              <span aria-hidden="true" style={ts({ color })}>
                {open ? "▲" : "▼"}
              </span>
              {open ? "Hide details" : "Details"}
            </button>
          )}
          {actions && (
            <div className="flex flex-wrap gap-2 border-t pt-3" style={ts({ borderColor: "#1C2044" })}>
              {actions.onChoose && (
                <button
                  type="button"
                  onClick={() => actions.onChoose(slot.id)}
                  className="border px-2 py-1 text-xs hover:text-white focus:outline-none focus:ring-2 focus:ring-amber-500"
                  style={ts({ borderColor: color, color: TOOLTIP.text })}
                >
                  Change
                </button>
              )}
              {actions.onPowders && item.slots > 0 && (slot.id === "weapon" || ["helmet", "chestplate", "leggings", "boots"].includes(slot.id)) && (
                <button
                  type="button"
                  onClick={() => actions.onPowders(slot.id)}
                  title="Put powders in this item's slots (any order and mix)"
                  className="border px-2 py-1 text-xs hover:text-white focus:outline-none focus:ring-2 focus:ring-amber-500"
                  style={ts({ borderColor: "#3B3F6A", color: item.powders ? "#FFAA00" : TOOLTIP.muted })}
                >
                  Powders{item.powders ? ` ${item.powders.list.length}/${item.slots}` : ""}
                </button>
              )}
              {actions.onAlternatives && (
                <button
                  type="button"
                  onClick={() => actions.onAlternatives(slot.id)}
                  className="border px-2 py-1 text-xs hover:text-white focus:outline-none focus:ring-2 focus:ring-amber-500"
                  style={ts({ borderColor: color, color: TOOLTIP.text })}
                >
                  Other picks
                </button>
              )}
              {actions.onRolls && ID_DISPLAY.some((display) => idVaries(item, display.key)) && (
                <button
                  type="button"
                  onClick={() => actions.onRolls(slot.id)}
                  title="Set the roll of each identification (0-100%), like the [xx%] shown in game"
                  className="border px-2 py-1 text-xs hover:text-white focus:outline-none focus:ring-2 focus:ring-amber-500"
                  style={ts({ borderColor: "#3B3F6A", color: item.rolls ? "#FFAA00" : TOOLTIP.muted })}
                >
                  Rolls{item.rolls ? " ✎" : ""}
                </button>
              )}
              {actions.onRemove && (
                <button
                  type="button"
                  onClick={() => actions.onRemove(slot.id)}
                  title="Empty this slot"
                  className="border px-2 py-1 text-xs hover:text-white focus:outline-none focus:ring-2 focus:ring-amber-500"
                  style={ts({ borderColor: "#3B3F6A", color: TOOLTIP.muted })}
                >
                  Remove
                </button>
              )}
              {!actions.onExclude ? null : pinned ? (
                <button
                  type="button"
                  onClick={() => actions.onUnpin(slot.id)}
                  className="border px-2 py-1 text-xs hover:text-white focus:outline-none focus:ring-2 focus:ring-amber-500"
                  style={ts({ borderColor: "#3B3F6A", color: "#FFAA00" })}
                >
                  Unpin
                </button>
              ) : (
                <button
                  type="button"
                  onClick={() => actions.onExclude(item.name)}
                  title="Don't suggest this item again"
                  className="border px-2 py-1 text-xs hover:text-white focus:outline-none focus:ring-2 focus:ring-amber-500"
                  style={ts({ borderColor: "#3B3F6A", color: TOOLTIP.muted })}
                >
                  Exclude
                </button>
              )}
            </div>
          )}
        </div>
      </div>
    </article>
  );
}

// INFO O ZDOBYCIU PRZEDMIOTU
const SOURCE_LABELS = {
  merchant: "Sold by a merchant",
  dungeonMerchant: "Dungeon merchant",
  challenge: "Challenge reward",
  miniboss: "Miniboss drop",
  quest: "Quest reward",
  altar: "Boss altar reward",
  dungeon: "Dungeon reward",
  lootrun: "Lootrun reward",
  raid: "Raid reward",
};

function obtainLines(item) {
  const { drop, quest, sources } = item.source;
  const lines = [];
  sources.forEach((source) => {
    const label = source.types.includes("event")
      ? `Event merchant${source.event ? ` (${capitalize(source.event)} event)` : ""}`
      : SOURCE_LABELS[source.types[0]] || capitalize(String(source.types[0]));
    lines.push({ label, detail: source.name, coords: source.coords });
  });
  if (quest && !lines.some((line) => line.detail === quest)) lines.unshift({ label: "Quest reward", detail: quest });
  if (lines.length === 0) {
    if (drop === "normal") lines.push({ label: "Random drop", detail: `Mobs and loot chests around level ${item.level}` });
    else if (drop === "lootchest") lines.push({ label: "Loot chests only", detail: `Chests around level ${item.level}` });
    else if (drop === "dungeon") lines.push({ label: "Dungeon drop", detail: null });
    else lines.push({ label: "Special source", detail: "Not a random drop, and the item data doesn't say where it comes from. Check the wiki." });
  }
  return lines;
}

function wikiLink(name) {
  // Wyszukiwarka wiki z "go" otwiera stronę przedmiotu, jeśli istnieje, a w przeciwnym razie wyniki wyszukiwania.
  return `https://wynncraft.wiki.gg/index.php?search=${encodeURIComponent(name)}&title=Special%3ASearch&go=Go`;
}

// Strona "How to get it" karty: źródła z danych Wynnbuildera, Trade Market, link do wiki.
function ObtainInfo({ item, color }) {
  const ts = useTs();
  const tradeable = !item.source.restrict;
  const restriction = item.source.restrict === "quest_item" ? "Quest item: can't be traded" : "Untradable: can't be sold or traded";
  return (
    <div className="flex flex-col gap-3">
      <ul className="flex flex-col gap-2 text-base">
        {obtainLines(item).map((line, index) => (
          <li key={index} className="flex flex-col">
            <span style={ts({ color: TOOLTIP.text })}>{line.label}</span>
            {line.detail && <span style={ts({ color: "#55FFFF" })}>{line.detail}</span>}
            {line.coords && (
              <span className="text-sm tabular-nums" style={ts({ color: TOOLTIP.muted })}>
                at {line.coords.join(", ")}
              </span>
            )}
          </li>
        ))}
      </ul>
      <TooltipDivider color={color} />
      <div className="flex items-center justify-between gap-2 text-base">
        <span className="flex items-center gap-1.5" style={ts({ color: TOOLTIP.text })}>
          <CheckBox state={tradeable ? "yes" : "no"} /> Trade Market
        </span>
        <span style={ts({ color: tradeable ? TOOLTIP.good : TOOLTIP.bad })}>{tradeable ? "Yes" : "No"}</span>
      </div>
      <span className="text-sm" style={ts({ color: TOOLTIP.muted })}>
        {tradeable ? "Can be bought and sold on the Trade Market." : restriction}
      </span>
      <a href={wikiLink(item.name)} target="_blank" rel="noreferrer" className="text-base underline hover:text-white" style={ts({ color: "#FFAA00" })}>
        Open on the Wynncraft wiki ↗
      </a>
    </div>
  );
}

// ALTERNATYWY DLA SLOTU: kolejne przedmioty wg wyniku archetypu, z informacją, czy mieszczą się w Skill Pointach
// razem z resztą obecnego buildu.
// Build z jednym slotem podmienionym (do porównania w "Other picks"): Skill Pointy i sumy liczone od nowa.
function buildWithItem(build, slotId, item) {
  const slots = build.slots.map((slot) => (slot.id === slotId ? { ...slot, item, crafted: null, missing: null } : slot));
  const items = slots.filter((slot) => slot.item).map((slot) => slot.item);
  const sp = computeSkillPoints(items, true);
  const totals = itemStatTotals(items);
  return {
    ...build,
    slots,
    totals,
    skillPoints: { ...build.skillPoints, assigned: sp.assigned, totals: sp.totals, required: sp.total, remaining: build.skillPoints.available - sp.total, valid: sp.total <= build.skillPoints.available && sp.capOverflow === 0 },
  };
}

const DELTA_METRICS = [
  ["dps", "Main attack DPS", (stats) => (stats.mainAttack ? stats.mainAttack.dps : 0), "#FFAA00"],
  ["spell", "Spell hit", (stats) => stats.spellHit || 0, "#55FFFF"],
  ["ehp", "EHP", (stats) => stats.ehp, "#55FF55"],
  ["hp", "Health", (stats) => stats.hp, "#FF5555"],
  ["mr", "Mana Regen", (stats) => stats.manaRegen, "#55FFFF"],
  ["ms", "Mana Steal", (stats) => stats.manaSteal, "#55FFFF"],
  ["hpr", "Health Regen", (stats) => stats.hpr, "#FF5555"],
  ["ls", "Life Steal", (stats) => stats.lifeSteal, "#FF5555"],
  ["spd", "Walk Speed", (stats) => stats.walkSpeed, "#FFFFFF"],
];

// Różnice w podsumowaniu (bez drzewka) po podmianie przedmiotu w slocie.
function summaryDeltas(build, slotId, item, currentStats) {
  const next = computeBuildStats(buildWithItem(build, slotId, item));
  return DELTA_METRICS.map(([id, label, pick, color]) => ({ id, label, color, delta: Math.round(pick(next) - pick(currentStats)) })).filter((entry) => entry.delta !== 0);
}

// Ranking kandydatów na slot "w tym buildzie" (inBuildScore) - dla listy "Other picks" i przeglądarki przedmiotów.
// `candidates` = własna lista (po filtrach); bez niej: wszystkie przedmioty pasujące do slotu i ustawień buildu.
// Liczba pod "score" na kartach i w listach: w trybie "New" to wprost obrażenia celu, w starym - punkty wyniku.
function buildScoreText(build, value) {
  return build && build.mode === "damage" ? formatNumber(Math.round(value || 0)) : formatScore(value);
}

// Ranking kandydatów w trybie "New": liczymy prawdziwe obrażenia celu z tym przedmiotem oraz to, czy build
// dalej przechodzi filtry EHP i many.
function damageAlternatives(build, slotId, limit, pool) {
  const ctx = damageGoalContext(build.playerClass, build.level, build.treeSettings);
  const cycle = build.metrics.cycle;
  const minEhp = build.metrics.minEhp || 0;
  const maxEhp = Number(build.metrics.maxEhp) > 0 ? build.metrics.maxEhp : null;
  const current = build.slots.find((entry) => entry.id === slotId).item;
  const others = build.slots.filter((entry) => entry.item && entry.id !== slotId).map((entry) => entry.item);
  const weapon = slotId === "weapon" ? null : (build.slots.find((entry) => entry.id === "weapon") || {}).item;
  const picks = Object.fromEntries(build.slots.map((entry) => [entry.id, entry.item ? { item: entry.item } : null]));
  // build z "Realistic rolls": kandydaci przy tym samym rollu co reszta zestawu
  const rollPercentOfBuild = build.metrics.rollPercent || 100;
  const atBuildRoll = (item) => (item && rollPercentOfBuild < 100 && !item.rolls && ITEM_BY_NAME.get(item.name) === item ? withRolls(item, { all: rollPercentOfBuild }) : item);
  const measure = (raw) => {
    const item = atBuildRoll(raw);
    const weaponNow = slotId === "weapon" ? item : weapon;
    const items = item ? [...others, item] : others;
    const sp = computeSkillPoints(items);
    const metrics = evaluateGoal(ctx, items, weaponNow, sp.totals, build.goal, cycle);
    const spOver = Math.max(0, sp.total - build.skillPoints.available) + sp.capOverflow;
    // przedmiot z setu, którego nie da się nosić razem z innym przedmiotem buildu
    const illegal = activeSets(items).find((set) => set.illegal);
    return { metrics, spOver, sp, illegalSet: illegal ? illegal.name : null };
  };
  const base = measure(current);
  const list = pool
    .filter((item) => !(current && item.name === current.name) && !ringsClash(picks, slotId, item))
    .map((item) => (slotId === "weapon" ? powderForProfile(item, build.profile) : item))
    .map((item) => {
      const { metrics, spOver, illegalSet } = measure(item);
      const passes =
        spOver === 0 &&
        !illegalSet &&
        (minEhp <= 0 || metrics.ehp >= minEhp) &&
        (maxEhp === null || metrics.ehp <= maxEhp + 1e-9) &&
        manaOk(metrics, cycle) &&
        sustainPasses({ ...metrics, requireSustain: build.metrics.requireSustain, minSustain: build.metrics.minSustain, lifeRange: build.metrics.lifeRange }) &&
        speedPasses({ walkSpeed: metrics.walkSpeed, spdRange: build.metrics.spdRange });
      return {
        item,
        score: metrics.damage,
        contributions: [],
        overflow: spOver,
        illegalSet,
        passes,
        deltas: [
          { id: "goal", label: build.goalName || "Damage", color: "#FFAA00", delta: Math.round(metrics.damage - base.metrics.damage) },
          { id: "ehp", label: "EHP", color: "#55FF55", delta: Math.round(metrics.ehp - base.metrics.ehp) },
          ...(cycle.ids.length > 0 ? [{ id: "mana", label: "Mana/s", color: "#55FFFF", delta: Math.round((metrics.manaNet - base.metrics.manaNet) * 10) / 10 }] : []),
        ].filter((entry) => entry.delta !== 0),
      };
    })
    .sort((a, b) => (a.passes === b.passes ? b.score - a.score : a.passes ? -1 : 1))
    .slice(0, limit);
  return { list, currentScore: base.metrics.damage, total: pool.length };
}

function slotAlternatives(build, slotId, limit = 20, candidates = null) {
  const slot = SLOTS.find((entry) => entry.id === slotId);
  const classConfig = CLASSES[build.playerClass];
  const { attackSpeeds, excluded } = build.options;
  const current = build.slots.find((entry) => entry.id === slotId).item;
  const currentStats = computeBuildStats(build);
  const levelWindow = LEVEL_WINDOWS.find((entry) => entry.id === build.options.levelWindow) || LEVEL_WINDOWS[0];
  const minLevel = levelWindow.strict ? build.level - levelWindow.window : -Infinity;
  const available = build.skillPoints.available;
  const baseHp = 5 * build.level + 5;
  const picks = Object.fromEntries(build.slots.map((entry) => [entry.id, entry.item ? { item: entry.item, ...scoreItem(entry.item, build.profile) } : null]));
  const rank = (item) => inBuildScore(picks, slotId, { item, ...scoreItem(item, build.profile) }, available, baseHp, build.profile);
  const excludedTiers = build.options.excludedTiers || [];
  const pool =
    candidates ||
    ITEM_DB.filter((item) => {
      if (item.level > build.level || item.level < minLevel || excluded.includes(item.name)) return false;
      if (excludedTiers.includes(item.tier)) return false;
      if (build.options.onlyListed && hasLiveData() && marketStatus(item).state !== "listed") return false;
      if (slot.type !== "weapon") return item.type === slot.type;
      return item.type === classConfig.weapon && (attackSpeeds.length === 0 || attackSpeeds.includes(item.atkSpd));
    });
  if (build.mode === "damage") return damageAlternatives(build, slotId, limit, pool);
  const list = pool
    .filter((item) => !(current && item.name === current.name) && !ringsClash(picks, slotId, item))
    .map((item) => (slot.type === "weapon" ? powderForProfile(item, build.profile) : item))
    .map((item) => ({ item, ...rank(item) }))
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map((entry) => ({ ...entry, deltas: summaryDeltas(build, slotId, entry.item, currentStats) }));
  return { list, currentScore: current ? rank(current).score : 0, total: pool.length };
}

// FILTR IDENTYFIKACJI (Other picks / Browse items): każda identyfikacja występująca w danych gry, bazowe HP i obrony
// pancerza oraz major ID. Przedmiot pasuje, gdy identyfikacja mu pomaga (koszt czaru: obniżka) - przy najlepszym rollu,
// bo to "czy da się to wylosować"; opcjonalne minimum per identyfikacja, tryb "wszystkie" albo "którakolwiek".
const AFFIX_GROUPS = [
  ["Skill points", (key) => SKILLS.includes(key)],
  ["Spell costs", (key) => /^sp(Raw|Pct)\d$/.test(key)],
  ["Health & sustain", (key) => ["hpBonus", "hprRaw", "hprPct", "ls", "healPct"].includes(key)],
  ["Mana", (key) => ["mr", "ms", "maxMana"].includes(key)],
  ["Spell damage", (key) => /(^sd|Sd)(Raw|Pct)$/.test(key)],
  ["Main attack", (key) => /(^md|Md)(Raw|Pct)$/.test(key) || key === "atkTier" || key === "mainAttackRange"],
  ["Damage", (key) => /(^dam|Dam)(Raw|Pct)$/.test(key)],
  ["Defence %", (key) => /DefPct$/.test(key)],
  ["Movement", (key) => ["spd", "sprint", "sprintReg", "jh"].includes(key)],
  ["Other", () => true],
];
const AFFIXES = (() => {
  const counts = {};
  const best = {};
  const majors = new Map();
  ITEM_DB.forEach((item) => {
    Object.entries(item.baseIds).forEach(([key, base]) => {
      counts[key] = (counts[key] || 0) + 1;
      const top = Math.abs(idRolls(item, key) ? rollRange(key, base)[1] : base);
      best[key] = Math.max(best[key] || 0, top);
    });
    item.majorIds.forEach((major) => majors.set(major, (majors.get(major) || 0) + 1));
  });
  const labelCount = {};
  ID_DISPLAY.forEach((display) => (labelCount[display.label] = (labelCount[display.label] || 0) + 1));
  const ids = ID_DISPLAY.filter((display) => counts[display.key]).map((display) => {
    const twin = labelCount[display.label] > 1;
    const suffix = display.unit === "%" ? " %" : twin ? " (raw)" : display.unit ? ` ${display.unit.trim()}` : "";
    return {
      id: display.key,
      kind: "id",
      key: display.key,
      display,
      label: `${display.label}${suffix}`,
      group: AFFIX_GROUPS.find(([, test]) => test(display.key))[0],
      count: counts[display.key],
      max: best[display.key] || 1,
    };
  });
  const baseCount = (key) => ITEM_DB.filter((item) => (item.base[key] || 0) > 0).length;
  const base = [
    { id: "base:hp", kind: "base", key: "hp", label: "Health (base + bonus)", group: "Base stats", count: ITEM_DB.filter((item) => (item.base.hp || 0) + (item.baseIds.hpBonus || 0) > 0).length },
    ...ELEMENTS.map((element) => ({ id: `base:${element.charAt(0)}Def`, kind: "base", key: `${element.charAt(0)}Def`, label: `${capitalize(element)} Defence (base)`, group: "Base stats", count: baseCount(`${element.charAt(0)}Def`) })),
  ];
  base.forEach((entry) => (entry.max = Math.max(1, ...ITEM_DB.map((item) => affixValue(item, entry)))));
  const majorList = [...majors.entries()]
    .sort((a, b) => a[0].localeCompare(b[0]))
    .map(([major, count]) => ({ id: `major:${major}`, kind: "major", key: major, label: `Major ID: ${titleCase(major)}`, group: "Major IDs", count, max: 1 }));
  return [...ids, ...base, ...majorList];
})();
const AFFIX_BY_ID = new Map(AFFIXES.map((affix) => [affix.id, affix]));
const AFFIX_GROUP_ORDER = [...AFFIX_GROUPS.map(([name]) => name), "Base stats", "Major IDs"];

// Najlepsza wartość identyfikacji w kierunku, który pomaga (koszty czarów: obniżka jako wartość dodatnia).
function affixValue(item, affix) {
  if (affix.kind === "major") return item.majorIds.includes(affix.key) ? 1 : 0;
  if (affix.kind === "base") {
    if (affix.key === "hp") {
      const bonus = item.baseIds.hpBonus || 0;
      return (item.base.hp || 0) + (idRolls(item, "hpBonus") ? rollRange("hpBonus", bonus)[1] : bonus);
    }
    return item.base[affix.key] || 0;
  }
  const base = item.baseIds[affix.key] || 0;
  if (!base) return 0;
  const top = idRolls(item, affix.key) ? rollRange(affix.key, base)[1] : base;
  return affix.display.invert ? -top : top;
}

function affixMatches(item, filters, mode) {
  if (filters.length === 0) return true;
  const test = (filter) => {
    const affix = AFFIX_BY_ID.get(filter.id);
    if (!affix) return true;
    const value = affixValue(item, affix);
    const min = filter.min === "" || filter.min === undefined ? null : Number(filter.min);
    return value > 0 && (min === null || !Number.isFinite(min) || value >= min);
  };
  return mode === "any" ? filters.some(test) : filters.every(test);
}

// Suma wybranych identyfikacji względem najlepszej wartości w grze (sortowanie "Selected identifications").
function affixSortValue(item, filters) {
  return filters.reduce((sum, filter) => {
    const affix = AFFIX_BY_ID.get(filter.id);
    return affix ? sum + Math.max(0, affixValue(item, affix)) / affix.max : sum;
  }, 0);
}

function affixText(item, affix) {
  if (affix.kind === "major") return titleCase(affix.key);
  if (affix.kind === "base") return `${formatNumber(affixValue(item, affix))} ${affix.label}`;
  const current = item.ids[affix.key] || item.baseIds[affix.key] || 0;
  const top = idRolls(item, affix.key) ? rollRange(affix.key, item.baseIds[affix.key])[1] : null;
  return `${formatIdValue(affix.display, current)}${top !== null && top !== current ? ` (max ${formatIdValue(affix.display, top)})` : ""} ${affix.display.label}`;
}

// Lista identyfikacji do wyboru: wyszukiwarka + grupy, wielokrotny wybór; wybrane jako chipy z polem minimum.
function AffixPicker({ selected, onChange, mode, onModeChange }) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const needle = query.trim().toLowerCase();
  const chosen = new Set(selected.map((filter) => filter.id));
  const visible = AFFIXES.filter((affix) => !needle || affix.label.toLowerCase().includes(needle) || affix.group.toLowerCase().includes(needle) || affix.key.toLowerCase() === needle);
  const toggle = (affix) => onChange(chosen.has(affix.id) ? selected.filter((filter) => filter.id !== affix.id) : [...selected, { id: affix.id, min: "" }]);
  return (
    <div className="flex flex-col gap-2">
      <div className="flex flex-wrap items-center gap-2">
        <span className="text-xs text-zinc-500">Identifications</span>
        <button type="button" onClick={() => setOpen(!open)} className="mc-btn mc-btn-sm" aria-expanded={open}>
          {open ? "Close list" : `+ Add identification${selected.length > 0 ? ` (${selected.length})` : ""}`}
        </button>
        {selected.length > 1 && (
          <span className="flex items-center gap-1 text-xs text-zinc-300">
            Match
            <ToggleChip pressed={mode === "all"} onClick={() => onModeChange("all")}>
              all
            </ToggleChip>
            <ToggleChip pressed={mode === "any"} onClick={() => onModeChange("any")}>
              any
            </ToggleChip>
          </span>
        )}
        {selected.length > 0 && (
          <button type="button" onClick={() => onChange([])} className="mc-link text-xs">
            Clear
          </button>
        )}
      </div>
      {selected.length > 0 && (
        <div className="flex flex-wrap gap-2">
          {selected.map((filter) => {
            const affix = AFFIX_BY_ID.get(filter.id);
            if (!affix) return null;
            return (
              <span key={filter.id} className="mc-slot flex items-center gap-1 px-2 py-0.5 text-xs" style={ts({ color: "#FFAA00" })}>
                {affix.label}
                {affix.kind !== "major" && (
                  <>
                    <span className="text-zinc-500">≥</span>
                    <input
                      value={filter.min}
                      onChange={(event) => onChange(selected.map((entry) => (entry.id === filter.id ? { ...entry, min: event.target.value } : entry)))}
                      placeholder="any"
                      inputMode="decimal"
                      className="mc-input w-14 py-0 text-right text-xs"
                      aria-label={`Minimum ${affix.label}`}
                    />
                  </>
                )}
                <button type="button" onClick={() => toggle(affix)} className="mc-link px-1" aria-label={`Remove ${affix.label}`}>
                  ×
                </button>
              </span>
            );
          })}
        </div>
      )}
      {open && (
        <div className="mc-well flex flex-col gap-2 p-2">
          <input
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder={`Search ${AFFIXES.length} identifications, e.g. mana, thunder, cost, major`}
            className="mc-input w-full"
            aria-label="Search identifications"
            autoFocus
            autoComplete="off"
            spellCheck={false}
          />
          <div className="flex max-h-64 flex-col gap-2 overflow-y-auto pr-1" role="listbox" aria-multiselectable="true" aria-label="Identifications">
            {AFFIX_GROUP_ORDER.map((group) => {
              const entries = visible.filter((affix) => affix.group === group);
              if (entries.length === 0) return null;
              return (
                <div key={group} className="flex flex-col gap-1">
                  <span className="text-xs uppercase text-zinc-500">{group}</span>
                  <div className="flex flex-wrap gap-1">
                    {entries.map((affix) => (
                      <button
                        key={affix.id}
                        type="button"
                        role="option"
                        aria-selected={chosen.has(affix.id)}
                        onClick={() => toggle(affix)}
                        className="mc-slot flex items-center gap-1 px-2 py-0.5 text-left text-xs"
                        style={ts({ color: chosen.has(affix.id) ? "#FFAA00" : "#e0e0e0", borderColor: chosen.has(affix.id) ? "#FFAA00" : undefined })}
                        title={`${affix.count} item${affix.count === 1 ? "" : "s"} in the game have it`}
                      >
                        {chosen.has(affix.id) ? "✓ " : ""}
                        {affix.label}
                        <span className="tabular-nums text-zinc-500">{affix.count}</span>
                      </button>
                    ))}
                  </div>
                </div>
              );
            })}
            {visible.length === 0 && <p className="text-xs text-zinc-500">No identification matches "{query}".</p>}
          </div>
          <p className="text-xs text-zinc-500">
            Click to add or remove (several at once). An item matches when the identification helps at its best roll (spell costs: a reduction); the number after ≥ is a minimum at the best roll.
          </p>
        </div>
      )}
    </div>
  );
}

// PRZEGLĄDARKA PRZEDMIOTÓW z filtrami (nazwa, typ, żywioły, rzadkość, poziom, szybkość ataku, DPS, sortowanie).
// Bez filtrów i z buildem: propozycje na slot wg wyniku "w tym buildzie" (jak Other picks). Z filtrami: pasujące
// przedmioty (broń tylko klasy), nadal z wynikiem i różnicą w podsumowaniu, gdy jest build. Bez buildu: sortowanie
// po DPS/poziomie/nazwie. Wybór przypina przedmiot do slotu (pierścień: wolny palec).
const BROWSE_TYPES = [
  { id: "weapon", label: "Weapon" },
  { id: "helmet", label: "Helmet" },
  { id: "chestplate", label: "Chestplate" },
  { id: "leggings", label: "Leggings" },
  { id: "boots", label: "Boots" },
  { id: "ring", label: "Ring" },
  { id: "bracelet", label: "Bracelet" },
  { id: "necklace", label: "Necklace" },
];
const BROWSE_SORTS = [
  { id: "score", label: "Score in this build" },
  { id: "affix", label: "Selected identifications" },
  { id: "dps", label: "Weapon DPS" },
  { id: "level", label: "Level" },
  { id: "hp", label: "Health" },
  { id: "price", label: "Price (cheapest)" },
  { id: "wynnpool", label: "Wynnpool score" },
  { id: "name", label: "Name" },
];
const BROWSE_LIMIT = 40;
const BROWSE_SCORE_CAP = 400; // tyle kandydatów (po liniowym wyniku) dostaje dokładny wynik "w tym buildzie"

function itemHasElement(item, element) {
  if (item.category === "weapon") return (item.damage || {})[element] > 0;
  return (item.elements || []).includes(element);
}

function slotForItem(item, locked = {}) {
  if (item.category === "weapon") return "weapon";
  if (item.type === "ring") return !locked.ring1 || locked.ring1 === item.name ? "ring1" : "ring2";
  return item.type;
}

// Filtr "Fits my skill points" (Other picks / Browse items z buildem): zostają przedmioty, które da się włożyć zamiast
// obecnego bez zmiany innych slotów - bez braku skill pointów, bez niedozwolonego setu i bez przekroczenia budżetu
// (to samo, co zielony napis "✓ fits your skill points"). Stan pamiętany na czas sesji (do przeładowania strony).
let FITS_ONLY_SESSION = false;
const fitsSkillPoints = (entry) => entry.score !== null && entry.overflow === 0 && !entry.illegalSet && !entry.overBudget;

// manual (Creator / Optimizer): bez ocen i propozycji; bez klasy widać bronie wszystkich klas (klasa wynika z broni),
// a maksymalny poziom można podnieść ponad poziom postaci (taki przedmiot dostaje ostrzeżenie, nie blokadę).
// onExclude (Browse items z lewego panelu): przycisk Exclude obok Pin w każdym wierszu.
function ItemBrowserDialog({ build, slotId = null, playerClass, level, options, onPick, onClose, pickLabel = "Use", manual = false, currentName = null, onExclude = null }) {
  const slot = slotId ? SLOTS.find((entry) => entry.id === slotId) : null;
  const weaponType = playerClass ? CLASSES[playerClass].weapon : null;
  const normalized = normalizeOptions(options);
  const [query, setQuery] = useState("");
  const [types, setTypes] = useState(slot ? [slot.type] : []);
  const [elements, setElements] = useState([]);
  const [tiers, setTiers] = useState([]);
  const [onlyListed, setOnlyListed] = useState(normalized.onlyListed && hasLiveData());
  const [onlyRated, setOnlyRated] = useState(false);
  const [speeds, setSpeeds] = useState([]);
  const [levelMin, setLevelMin] = useState("");
  const [levelMax, setLevelMax] = useState("");
  const [minDps, setMinDps] = useState("");
  const [sort, setSort] = useState(build ? "score" : slot && slot.type === "weapon" ? "dps" : "level");
  const [showAll, setShowAll] = useState(false);
  const [affixFilters, setAffixFilters] = useState([]); // [{ id, min }]
  const [affixMode, setAffixMode] = useState("all");
  // Wymagania: tylko przedmioty wymagające wyłącznie zaznaczonych umiejętności i / lub najwyżej N w każdej
  const [reqSkills, setReqSkills] = useState([]);
  const [reqMax, setReqMax] = useState("");
  const [fitsOnlyState, setFitsOnlyState] = useState(FITS_ONLY_SESSION);
  const fitsOnly = Boolean(build) && !manual && fitsOnlyState;
  const toggleFits = () => {
    FITS_ONLY_SESSION = !fitsOnlyState;
    setFitsOnlyState(!fitsOnlyState);
  };
  const changeAffixes = (next) => {
    if (next.length > 0 && affixFilters.length === 0 && !build) setSort("affix");
    if (next.length === 0 && sort === "affix") setSort(build ? "score" : slot && slot.type === "weapon" ? "dps" : "level");
    setAffixFilters(next);
  };
  const needle = query.trim().toLowerCase();
  const filtering = (Boolean(build) && sort !== "score") || needle.length > 0 || elements.length > 0 || tiers.length > 0 || speeds.length > 0 || levelMin !== "" || levelMax !== "" || minDps !== "" || affixFilters.length > 0 || onlyListed || onlyRated || reqSkills.length > 0 || reqMax !== "" || (!slot && types.length > 0);
  const weaponsOnly = slot ? slot.type === "weapon" : types.length > 0 && types.every((type) => type === "weapon");

  const results = useMemo(() => {
    const min = levelMin === "" ? 1 : clampLevel(levelMin);
    const max = levelMax === "" ? level : manual ? clampLevel(levelMax) : Math.min(level, clampLevel(levelMax));
    const dpsFloor = minDps === "" ? 0 : Number(minDps) || 0;
    const reqCap = reqMax === "" ? null : Math.max(0, Number(reqMax) || 0);
    const wantedTypes = slot ? [slot.type] : types;
    const matches = ITEM_DB.filter((item) => {
      if (item.level > max || item.level < min) return false;
      if (item.category === "weapon" && weaponType && item.type !== weaponType) return false;
      if (item.category === "weapon" && !weaponType && !manual) return false;
      if (reqSkills.length > 0 && SKILLS.some((skill) => (item.reqs[skill] || 0) > 0 && !reqSkills.includes(skill))) return false;
      if (reqCap !== null && SKILLS.some((skill) => (item.reqs[skill] || 0) > reqCap)) return false;
      const typeKey = item.category === "weapon" ? "weapon" : item.type;
      if (wantedTypes.length > 0 && !wantedTypes.includes(typeKey)) return false;
      if (needle && !item.name.toLowerCase().includes(needle)) return false;
      if (tiers.length > 0 && !tiers.includes(item.tier)) return false;
      if (onlyListed && marketStatus(item).state !== "listed") return false;
      if (onlyRated && wynnpoolProfiles(item).length === 0) return false;
      if (elements.length > 0 && !elements.some((element) => itemHasElement(item, element))) return false;
      if (speeds.length > 0 && (item.category !== "weapon" || !speeds.includes(item.atkSpd))) return false;
      if (dpsFloor > 0 && (item.category !== "weapon" || (item.dps || 0) < dpsFloor)) return false;
      if (normalized.excluded.includes(item.name)) return false;
      if (!affixMatches(item, affixFilters, affixMode)) return false;
      return true;
    });
    // Propozycje bez filtrów: ranking na slot jak w "Other picks". Z filtrem "Fits my skill points" liczymy wszystkich
    // kandydatów slotu i dopiero przefiltrowaną listę obcinamy do BROWSE_LIMIT (inaczej pasujące mogły nie trafić na ekran).
    if (build && slot && !filtering) {
      const ranked = slotAlternatives(build, slotId, fitsOnly ? Infinity : BROWSE_LIMIT);
      if (!fitsOnly) return { rows: ranked.list, total: ranked.total, currentScore: ranked.currentScore, suggested: true };
      const fitting = ranked.list.filter(fitsSkillPoints);
      return { rows: fitting.slice(0, BROWSE_LIMIT), total: ranked.total, fits: fitting.length, checked: ranked.list.length, currentScore: ranked.currentScore, suggested: true };
    }
    if (build && sort === "score") {
      // Wynik "w tym buildzie": slot z typu przedmiotu; kandydaci ograniczeni do BROWSE_SCORE_CAP po liniowym wyniku.
      // Z filtrem "Fits" limit rośnie (x2), aż znajdzie BROWSE_LIMIT pasujących albo skończą się kandydaci.
      const bySlot = {};
      matches.forEach((item) => {
        const target = slot ? slotId : slotForItem(item, normalized.locked);
        (bySlot[target] || (bySlot[target] = [])).push(item);
      });
      let rows = [];
      let checked = 0;
      Object.entries(bySlot).forEach(([target, items]) => {
        const ordered = items.length > BROWSE_SCORE_CAP ? items.map((item) => ({ item, linear: scoreItem(item, build.profile).score })).sort((a, b) => b.linear - a.linear).map((entry) => entry.item) : items;
        let cap = BROWSE_SCORE_CAP;
        let list = slotAlternatives(build, target, fitsOnly ? Infinity : BROWSE_LIMIT, ordered.slice(0, cap)).list;
        while (fitsOnly && list.filter(fitsSkillPoints).length < BROWSE_LIMIT && cap < ordered.length) {
          cap *= 2;
          list = slotAlternatives(build, target, Infinity, ordered.slice(0, cap)).list;
        }
        checked += Math.min(cap, ordered.length);
        rows = rows.concat((fitsOnly ? list.filter(fitsSkillPoints) : list).map((entry) => ({ ...entry, slotId: target })));
      });
      rows.sort((a, b) => b.score - a.score);
      return { rows: rows.slice(0, BROWSE_LIMIT), total: matches.length, fits: fitsOnly ? rows.length : null, checked, currentScore: null, suggested: false };
    }
    const key = {
      dps: (item) => item.dps || 0,
      level: (item) => item.level,
      hp: (item) => (item.stats && item.stats.hp) || 0,
      name: (item) => item.name,
      affix: (item) => affixSortValue(item, affixFilters),
      // najlepszy profil Wynnpool przy rollach 50% - przedmioty bez wag idą na koniec
      wynnpool: (item) => {
        const best = bestWynnpoolScore(item, null);
        return best ? best.score : -Infinity;
      },
      // najtańsze pierwsze: odwrócony znak, przedmioty bez ceny na końcu
      price: (item) => {
        const { price } = itemPrice(item);
        return price === null ? -Infinity : -price;
      },
    }[sort === "score" || (sort === "affix" && affixFilters.length === 0) ? "level" : sort];
    const sorted = [...matches].sort((a, b) => (sort === "name" ? key(a).localeCompare(key(b)) : key(b) - key(a) || b.level - a.level));
    if (build && fitsOnly) {
      // wszystkie pasujące do filtrów ocenione w buildzie, zostają te, które się mieszczą - w kolejności sortowania
      const bySlotAll = {};
      sorted.forEach((item) => {
        const target = slot ? slotId : slotForItem(item, normalized.locked);
        (bySlotAll[target] || (bySlotAll[target] = [])).push(item);
      });
      const scoredAll = new Map();
      Object.entries(bySlotAll).forEach(([target, items]) => {
        slotAlternatives(build, target, Infinity, items).list.forEach((entry) => scoredAll.set(entry.item.name, { ...entry, slotId: target }));
      });
      const fitting = sorted.map((item) => scoredAll.get(item.name)).filter((entry) => entry && fitsSkillPoints(entry));
      return { rows: fitting.slice(0, showAll ? 200 : BROWSE_LIMIT), total: matches.length, fits: fitting.length, checked: matches.length, currentScore: null, suggested: false };
    }
    const shown = sorted.slice(0, showAll ? 200 : BROWSE_LIMIT);
    if (!build) return { rows: shown.map((item) => ({ item, score: null, contributions: [], deltas: [], overflow: 0 })), total: matches.length, currentScore: null, suggested: false };
    // Z buildem: te same wiersze w tej kolejności, ale z wynikiem "w tym buildzie" i zmianą w podsumowaniu.
    const bySlot = {};
    shown.forEach((item) => {
      const target = slot ? slotId : slotForItem(item, normalized.locked);
      (bySlot[target] || (bySlot[target] = [])).push(item);
    });
    const scored = new Map();
    Object.entries(bySlot).forEach(([target, items]) => {
      slotAlternatives(build, target, items.length, items).list.forEach((entry) => scored.set(entry.item.name, { ...entry, slotId: target }));
    });
    const rows = shown.map((item) => scored.get(item.name) || { item, score: null, contributions: [], deltas: [], overflow: 0, current: true });
    return { rows, total: matches.length, currentScore: null, suggested: false };
  }, [build, slotId, slot, types, elements, tiers, speeds, levelMin, levelMax, minDps, needle, sort, level, weaponType, filtering, showAll, normalized.excluded, normalized.locked, affixFilters, affixMode, onlyListed, onlyRated, manual, reqSkills, reqMax, fitsOnly]);

  const current = slot && build ? build.slots.find((entry) => entry.id === slotId).item : currentName ? ITEM_BY_NAME.get(currentName) || null : null;
  const chip = (pressed, color, onClick, label, key) => (
    <ToggleChip key={key} pressed={pressed} color={color} onClick={onClick}>
      {label}
    </ToggleChip>
  );
  return (
    <div
      className="wbr-backdrop fixed inset-0 z-50 flex items-start justify-center overflow-y-auto px-4 py-6"
      role="dialog"
      aria-modal="true"
      aria-label={slot ? (manual ? `Choose ${slot.label}` : `Other picks for ${slot.label}`) : "Browse items"}
      onKeyDown={(event) => event.key === "Escape" && onClose()}
    >
      <div className="wbr-pop mc-panel flex w-full max-w-4xl flex-col gap-3 p-4">
        <div className="flex items-start justify-between gap-3">
          <div>
            <h2 className="mc-title text-lg">{slot ? (manual ? `Choose ${slot.label}` : `Other picks for ${slot.label}`) : "Browse items"}</h2>
            <p className="text-sm text-zinc-400">
              {current ? (
                <>
                  Current: <span style={ts({ color: RARITY_COLORS[current.tier] })}>{current.name}</span>
                  {results.currentScore !== null ? ` (${build && build.mode === "damage" ? `${formatNumber(Math.round(results.currentScore))} ${build.goalName || "damage"}` : `score ${formatScore(results.currentScore)}`})` : ""}.{" "}
                </>
              ) : null}
              {manual
                ? `Every ${slot && slot.type === "weapon" ? (weaponType || "weapon of any class - the weapon sets your class") : slot ? slot.label.toLowerCase() : "item"} up to level ${level}. Type a higher max level to see items above yours (the build then shows a warning). Nothing is picked for you.`
                : build && slot
                ? `With nothing typed the list is the ${build.archetype} ranking for the slot; type or filter to search every ${weaponType ? `${weaponType}, ` : ""}armour piece and accessory up to level ${level} - still scored in this build. Using one pins it here and re-fits the other slots around it.`
                : build
                  ? `Every ${weaponType ? `${weaponType}, ` : ""}armour piece and accessory up to level ${level}, scored in the current ${build.archetype} build (the arrow shows the slot it would take). Picking one pins it to its slot and re-fits the rest.`
                  : `Every ${weaponType ? `${weaponType}, ` : ""}armour piece and accessory up to level ${level}${weaponType ? "" : " (weapons appear once you choose a class)"}. Picking one pins it; generate a build to see scores.`}
            </p>
          </div>
          <button type="button" autoFocus onClick={onClose} className="mc-btn mc-btn-sm">
            Close
          </button>
        </div>

        <div className="mc-slot flex flex-col gap-2 p-3 text-sm">
          <div className="flex flex-wrap items-center gap-2">
            <input
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder="Search by name"
              className="mc-input min-w-[12rem] flex-1"
              aria-label="Search items by name"
              autoComplete="off"
              spellCheck={false}
            />
            <label className="flex items-center gap-2 text-xs text-zinc-300">
              Sort
              <select value={sort} onChange={(event) => setSort(event.target.value)} className="mc-input" aria-label="Sort items">
                {BROWSE_SORTS.filter((entry) => (entry.id !== "score" || build) && (entry.id !== "affix" || affixFilters.length > 0) && (entry.id !== "price" || hasPriceData()) && (entry.id !== "wynnpool" || hasWynnpoolData())).map((entry) => (
                  <option key={entry.id} value={entry.id}>
                    {entry.label}
                  </option>
                ))}
              </select>
            </label>
            <label className="flex items-center gap-1 text-xs text-zinc-300">
              Lv.
              <input value={levelMin} onChange={(event) => setLevelMin(event.target.value)} placeholder="1" inputMode="numeric" className="mc-input w-16 text-right" aria-label="Minimum level" />
              –
              <input value={levelMax} onChange={(event) => setLevelMax(event.target.value)} placeholder={String(level)} inputMode="numeric" className="mc-input w-16 text-right" aria-label="Maximum level" />
            </label>
          </div>
          {!slot && (
            <div className="flex flex-wrap gap-2">
              {BROWSE_TYPES.map((type) => chip(types.includes(type.id), null, () => setTypes(toggleValue(types, type.id)), type.label, type.id))}
            </div>
          )}
          <div className="flex flex-wrap items-center gap-2">
            <span className="text-xs text-zinc-500">Element</span>
            {DAMAGE_FOCUS_OPTIONS.map((element) =>
              chip(elements.includes(element), ELEMENT_STYLE[element].color, () => setElements(toggleValue(elements, element)), `${ELEMENT_STYLE[element].symbol} ${ELEMENT_STYLE[element].label}`, element)
            )}
            <span className="ml-2 text-xs text-zinc-500">Rarity</span>
            {ITEM_TIERS.map((tier) => chip(tiers.includes(tier), RARITY_COLORS[tier], () => setTiers(toggleValue(tiers, tier)), tier, tier))}
            {hasLiveData() && (
              <>
                <span className="ml-2 text-xs text-zinc-500">Market</span>
                {chip(onlyListed, "#55FF55", () => setOnlyListed(!onlyListed), "● Listed today", "listed")}
              </>
            )}
            {hasWynnpoolData() && (
              <>
                <span className="ml-2 text-xs text-zinc-500">Wynnpool</span>
                {chip(onlyRated, "#55FFFF", () => setOnlyRated(!onlyRated), "Rated items", "wynnpool")}
              </>
            )}
            {build && !manual && (
              <>
                <span className="ml-2 text-xs text-zinc-500">Build</span>
                {chip(fitsOnly, "#55FF55", toggleFits, "✓ Fits my skill points", "fits")}
              </>
            )}
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <span className="text-xs text-zinc-500" title="Show only items whose skill point requirements are all among the checked skills (none checked = any), and at most this many points in each.">
              Requirements
            </span>
            {SKILLS.map((skill) => chip(reqSkills.includes(skill), SKILL_STYLE[skill].color, () => setReqSkills(toggleValue(reqSkills, skill)), `${SKILL_STYLE[skill].symbol} ${SKILL_STYLE[skill].short}`, `req-${skill}`))}
            <label className="ml-2 flex items-center gap-1 text-xs text-zinc-300">
              max
              <input value={reqMax} onChange={(event) => setReqMax(event.target.value.replace(/[^0-9]/g, ""))} placeholder="any" inputMode="numeric" className="mc-input w-16 text-right" aria-label="Maximum requirement per skill" />
            </label>
          </div>
          <AffixPicker selected={affixFilters} onChange={changeAffixes} mode={affixMode} onModeChange={setAffixMode} />
          {(weaponsOnly || (!slot && types.length === 0)) && (weaponType || manual) && (
            <div className="flex flex-wrap items-center gap-2">
              <span className="text-xs text-zinc-500">Attack speed</span>
              {ATTACK_SPEEDS.map((speed) => chip(speeds.includes(speed), null, () => setSpeeds(toggleValue(speeds, speed)), ATTACK_SPEED_LABELS[speed], speed))}
              <label className="ml-2 flex items-center gap-1 text-xs text-zinc-300">
                Min DPS
                <input value={minDps} onChange={(event) => setMinDps(event.target.value)} placeholder="0" inputMode="numeric" className="mc-input w-20 text-right" aria-label="Minimum weapon DPS" />
              </label>
            </div>
          )}
          {fitsOnly && results.fits !== undefined && results.fits !== null && (
            <p className="text-xs" style={ts({ color: "#55FF55" })}>
              {results.fits} of {results.checked ?? results.total} fit your skill points{results.fits > results.rows.length ? ` · showing ${results.rows.length}` : ""} - each can replace the current item without changing the other slots.
            </p>
          )}
          <p className="text-xs text-zinc-500">
            {results.suggested
              ? `Top ${results.rows.length} of ${results.total} items for this slot by score. Element = the weapon deals that damage / the item is that element.`
              : `${results.total} match${results.total === 1 ? "" : "es"}${results.total > results.rows.length ? `, showing ${results.rows.length}` : ""}.`}
            {!results.suggested && results.total > results.rows.length && sort !== "score" && !showAll && (
              <button type="button" onClick={() => setShowAll(true)} className="mc-link ml-2">
                Show up to 200
              </button>
            )}
          </p>
        </div>

        {results.rows.length === 0 ? (
          <p className="text-sm text-zinc-500">
            Nothing matches these filters up to level {level}.{!weaponType && (slot ? slot.type === "weapon" : types.includes("weapon")) ? " Weapons show once you choose a class." : ""}
          </p>
        ) : (
          <ul className="mc-divide flex flex-col">
            {results.rows.map((entry) => {
              const { item } = entry;
              const delta = results.currentScore !== null && entry.score !== null ? entry.score - results.currentScore : null;
              const stats = (entry.contributions || []).filter((c) => c.key !== "dps" && c.contribution > 0 && STAT_META[c.key]).slice(0, 3);
              const fallbackStats = stats.length === 0 ? ID_DISPLAY.filter((display) => item.ids[display.key]).slice(0, 3).map((display) => ({ key: display.key, value: item.ids[display.key] })) : [];
              const levelGap = (entry.contributions || []).find((c) => c.key === "levelGap");
              const rated = bestWynnpoolScore(item, item.rolls || null);
              return (
                <li key={`${entry.slotId || slotId || item.type}-${item.name}`} className="flex flex-wrap items-center gap-3 py-2">
                  <div className="flex-shrink-0">
                    <PixelIcon item={item} size={32} />
                  </div>
                  <div className="flex min-w-0 flex-1 flex-col" style={ts({ fontFamily: PIXEL_FONT })}>
                    <span className="text-base" style={ts({ color: RARITY_COLORS[item.tier] || RARITY_COLORS.Normal })}>
                      {item.name}
                      {rated ? (
                        <span className="ml-2 text-xs" style={ts({ color: "#55FFFF" })} title={`Wynnpool "${rated.profile.name}" weights: ${wynnpoolSummary(rated.profile)}. The score is for max rolls; set your own in Rolls.`}>
                          WP {rated.score.toFixed(0)}
                        </span>
                      ) : null}
                    </span>
                    <span className="text-xs" style={ts({ color: TOOLTIP.muted })}>
                      {item.tier} {item.type} · Lv. {item.level}
                      {item.category === "weapon" ? ` · ${ATTACK_SPEED_LABELS[item.atkSpd] || item.atkSpd} · ${formatNumber(item.dps || 0)} DPS` : ""}
                      {item.powders ? ` (${powderLabel(item.powders)} powders; base ${formatNumber(item.baseWeapon.dps || 0)})` : ""}
                      {item.category === "weapon" && Math.round(weaponMainAttackDps(item)) !== Math.round(item.dps || 0)
                        ? ` → ${formatNumber(Math.round(weaponMainAttackDps(item)))} main attack DPS`
                        : ""}
                      {item.elements && item.elements.length > 0 ? ` · ${item.elements.map((element) => ELEMENT_STYLE[element].symbol).join(" ")}` : ""}
                      {entry.slotId && !slot ? ` · → ${SLOTS.find((s) => s.id === entry.slotId).label}` : ""}
                      {eventOf(item) ? <span style={ts({ color: "#FF55FF" })} title={`Only from the ${eventOf(item)}`}> · event</span> : null}
                      {hasPriceData() ? ` · ${priceLabel(item)}` : ""}
                      {hasLiveData() && !isUntradable(item) ? (
                        <span style={ts({ color: marketStatus(item).state === "listed" ? "#55FF55" : undefined })} title={marketTitle()}>
                          {" · "}
                          {marketStatus(item).state === "listed" ? "● " : "○ "}
                          {marketText(item, true)}
                        </span>
                      ) : null}
                    </span>
                    <span className="text-xs" style={ts({ color: TOOLTIP.text })}>
                      {stats.map((c) => `${formatStatValue(c.key, c.value)} ${STAT_META[c.key].label}`).join(" · ")}
                      {fallbackStats.map((c) => `${formatStatValue(c.key, c.value)} ${STAT_META[c.key] ? STAT_META[c.key].label : c.key}`).join(" · ")}
                      {levelGap ? <span style={ts({ color: "#FFAA00" })}>{stats.length > 0 ? " · " : ""}far below your level ({formatScore(levelGap.contribution)})</span> : null}
                    </span>
                    {affixFilters.length > 0 && (
                      <span className="text-xs" style={ts({ color: "#FFAA00" })}>
                        {affixFilters
                          .map((filter) => AFFIX_BY_ID.get(filter.id))
                          .filter((affix) => affix && affixValue(item, affix) > 0)
                          .map((affix) => affixText(item, affix))
                          .join(" · ")}
                      </span>
                    )}
                    {entry.score !== null && (
                      <span className="flex flex-wrap gap-x-3 text-xs" title="Change in the build summary if you use this item (without the ability tree)">
                        {!entry.deltas || entry.deltas.length === 0 ? (
                          <span style={ts({ color: TOOLTIP.muted })}>No change in the summary</span>
                        ) : (
                          entry.deltas.slice(0, 6).map((d) => (
                            <span key={d.id} style={ts({ color: d.delta > 0 ? "#55FF55" : "#FF5555" })}>
                              {d.label} {d.delta > 0 ? "+" : ""}
                              {formatNumber(d.delta)}
                            </span>
                          ))
                        )}
                      </span>
                    )}
                  </div>
                  <div className="flex flex-col items-end text-xs">
                    {entry.score !== null && (
                      <span className="tabular-nums text-zinc-200">
                        {build && build.mode === "damage" ? "dmg" : "score"} {buildScoreText(build, entry.score)}
                        {delta !== null ? (
                          <span style={ts({ color: delta >= 0 ? "#55FF55" : "#FF5555" })}>
                            {" "}
                            ({delta >= 0 ? "+" : ""}
                            {buildScoreText(build, delta)})
                          </span>
                        ) : null}
                      </span>
                    )}
                    {entry.score !== null && (
                      <span style={ts({ color: entry.illegalSet || entry.overBudget ? "#FF5555" : entry.overflow === 0 ? "#55FF55" : "#FFAA00" })}>
                        {entry.illegalSet
                          ? `✗ can't be worn with your other ${entry.illegalSet} item`
                          : entry.overBudget
                            ? "✗ over your budget"
                            : entry.overflow === 0
                            ? "✓ fits your skill points"
                            : `✗ ${entry.overflow} SP short, other slots get re-fitted`}
                      </span>
                    )}
                  </div>
                  {build && build.slots.some((buildSlot) => buildSlot.item && buildSlot.item.name === item.name && (!slot || buildSlot.id === slotId)) ? (
                    <span className="mc-slot px-2 py-1 text-xs text-zinc-400">In build</span>
                  ) : (
                    <span className="flex gap-1">
                      <button type="button" onClick={() => onPick(item, entry.slotId || slotId || slotForItem(item, normalized.locked))} className="mc-btn mc-btn-sm mc-btn-primary">
                        {pickLabel}
                      </button>
                      {onExclude && (
                        <button type="button" onClick={() => onExclude(item)} className="mc-btn mc-btn-sm" aria-label={`Exclude ${item.name}`} title="Never use this item (applies on Generate Build)">
                          Exclude
                        </button>
                      )}
                    </span>
                  )}
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </div>
  );
}

// Okno "Rolls": suwak całego przedmiotu (0-100%) albo osobny suwak dla każdej rollującej identyfikacji.
// Panel Wynnpool w oknie rolli: jeden wiersz na profil - żywy wynik 0-100 dla ustawionych rolli, pasek, wagi i
// przycisk ustawiający rolle pod ten profil.
function WynnpoolPanel({ item, rolls, onChange }) {
  const profiles = wynnpoolProfiles(item);
  if (profiles.length === 0) return null;
  return (
    <div className="mc-slot flex flex-col gap-3 p-3">
      <div className="flex items-baseline justify-between gap-2">
        <span className="mc-gold text-sm">Wynnpool weights</span>
        <a href={`${WYNNPOOL_SITE}/item/${encodeURIComponent(item.name)}`} target="_blank" rel="noreferrer" className="text-xs underline" style={ts({ color: "#55FFFF" })}>
          wynnpool.com
        </a>
      </div>
      <p className="text-xs text-zinc-500">
        {WYNNPOOL_CREDIT} rates which identifications actually matter on this item. The score is the same 0-100 number
        Wynnpool shows: every roll counted with its weight (a negative weight wants a low roll).
      </p>
      <ul className="flex flex-col gap-3">
        {profiles.map((profile) => {
          const score = wynnpoolScore(item, profile, rolls);
          const target = wynnpoolTargetRolls(item, profile);
          return (
            <li key={profile.name} className="flex flex-col gap-1">
              <div className="flex items-baseline justify-between gap-2 text-sm">
                <span className="text-zinc-200">
                  {profile.name}
                  <span className="ml-2 text-xs text-zinc-500">{wynnpoolSummary(profile)}</span>
                </span>
                <span className="flex items-center gap-2">
                  <span className="tabular-nums" style={ts({ color: rollColor(score === null ? 0 : score) })}>
                    {score === null ? "-" : score.toFixed(1)}
                  </span>
                  {target && (
                    <button type="button" onClick={() => onChange(target)} className="mc-btn mc-btn-sm" title="Set every weighted identification to its best roll">
                      Best roll
                    </button>
                  )}
                </span>
              </div>
              <div className="h-1.5 w-full" style={ts({ background: "#2b2b2b" })}>
                <div className="h-full" style={ts({ width: `${Math.max(0, Math.min(100, score || 0))}%`, background: rollColor(score === null ? 0 : score) })} />
              </div>
              {profile.note && <p className="text-xs text-zinc-500">{profile.note}</p>}
            </li>
          );
        })}
      </ul>
    </div>
  );
}

function RollsDialog({ item, rolls, onChange, onClose }) {
  const current = rolls || {};
  const lines = ID_DISPLAY.filter((display) => idVaries(item, display.key));
  const wholeValue = current.all !== undefined ? current.all : DEFAULT_ROLL;
  // Największa (co do modułu) waga Wynnpool dla danej identyfikacji na tym przedmiocie; null = żaden profil jej nie liczy.
  const profiles = wynnpoolProfiles(item);
  const weightOf = (key) => {
    let best = null;
    profiles.forEach((profile) => {
      const weight = profile.ids[key];
      if (weight !== undefined && (best === null || Math.abs(weight) > Math.abs(best))) best = weight;
    });
    return best;
  };
  const preview = withRolls(item, current);
  const setWhole = (value) => onChange({ all: value });
  const setOne = (key, value) => onChange({ ...current, [key]: value });
  return (
    <div
      className="wbr-backdrop fixed inset-0 z-50 flex items-start justify-center overflow-y-auto px-4 py-8"
      role="dialog"
      aria-modal="true"
      aria-label={`Rolls of ${item.name}`}
      onKeyDown={(event) => event.key === "Escape" && onClose()}
    >
      <div className="wbr-pop mc-panel flex w-full max-w-2xl flex-col gap-4 p-4">
        <div className="flex items-start justify-between gap-3">
          <div>
            <h2 className="mc-title text-lg">
              Rolls: <span style={ts({ color: RARITY_COLORS[item.tier] || RARITY_COLORS.Normal })}>{item.name}</span>
            </h2>
            <p className="text-sm text-zinc-400">
              In game each identification rolls 30-130% of its base (negative ones 70-130%); the [xx%] tag is where the roll landed.
              Everything starts at 50%. Set your own rolls to match the item you actually have.
            </p>
          </div>
          <div className="flex gap-2">
            {rolls && (
              <button type="button" onClick={() => onChange(null)} className="mc-btn mc-btn-sm">
                Reset 50%
              </button>
            )}
            <button type="button" autoFocus onClick={onClose} className="mc-btn mc-btn-sm">
              Close
            </button>
          </div>
        </div>
        <div className="mc-slot flex flex-col gap-1 p-3">
          <div className="flex items-baseline justify-between text-sm">
            <label htmlFor="roll-all" className="mc-gold">
              Whole item
            </label>
            <span className="tabular-nums" style={ts({ color: rollColor(wholeValue) })}>
              {wholeValue}%
            </span>
          </div>
          <McRange id="roll-all" min={0} max={100} step={1} value={wholeValue} onChange={(event) => setWhole(Number(event.target.value))} className="w-full" accent={rollColor(wholeValue)} />
          <p className="text-xs text-zinc-500">Sets every identification below; move a single one to override it.</p>
        </div>
        <WynnpoolPanel item={item} rolls={current} onChange={onChange} />
        <ul className="flex flex-col gap-3">
          {lines.map((display) => {
            const percent = rollPercent(current, display.key);
            const value = preview.ids[display.key] || 0;
            const [worst, best] = rollRange(display.key, item.baseIds[display.key]);
            const good = display.invert ? value < 0 : value > 0;
            const id = `roll-${display.key}`;
            return (
              <li key={display.key} className="flex flex-col gap-1">
                <div className="flex items-baseline justify-between gap-2 text-sm">
                  <label htmlFor={id} className="text-zinc-200">
                    {display.label}
                    <span className="ml-2 text-xs text-zinc-500">
                      {formatIdValue(display, worst)} … {formatIdValue(display, best)}
                    </span>
                    {weightOf(display.key) !== null && (
                      <span className="ml-2 text-xs" style={ts({ color: "#55FFFF" })} title={`Wynnpool weight on this item: ${Math.round(weightOf(display.key) * 100)}%`}>
                        WP {Math.round(weightOf(display.key) * 100)}%
                      </span>
                    )}
                  </label>
                  <span className="tabular-nums" style={ts({ color: good ? "#55FF55" : "#FF5555" })}>
                    {formatIdValue(display, value)} <span style={ts({ color: rollColor(percent) })}>[{percent.toFixed(1)}%]</span>
                  </span>
                </div>
                <McRange id={id} min={0} max={100} step={1} value={percent} onChange={(event) => setOne(display.key, Number(event.target.value))} className="w-full" accent={rollColor(percent)} />
              </li>
            );
          })}
        </ul>
      </div>
    </div>
  );
}

// Rolle gracza: { klucz: { all?: %, [id]: % } }. Klucz to nazwa przedmiotu, a w slotach pierścieni slot + nazwa
// ("ring2|Warsong"): dwa takie same pierścienie mają osobne rolle (feedback 0.37: zmiana rolli jednego zmieniała oba).
// Odczyt: klucz slotu, potem sama nazwa (zapis sprzed 0.37, wspólny dla obu pierścieni).
const RING_SLOT_IDS = new Set(["ring1", "ring2"]);
function rollKey(slotId, name) {
  return RING_SLOT_IDS.has(slotId) ? `${slotId}|${name}` : name;
}
function rollsOf(rolls, slotId, name) {
  if (!rolls || !name) return null;
  return rolls[rollKey(slotId, name)] || rolls[name] || null;
}
// Nowe rolle przedmiotu w slocie (next = null: usuń). Stary wspólny wpis pierścienia rozdzielamy najpierw na oba sloty,
// żeby drugi pierścień zachował swoje rolle. slotNames: { slotId: nazwa } przedmiotów buildu.
function withSlotRolls(rolls, slotId, name, next, slotNames = {}) {
  const updated = { ...(rolls || {}) };
  const key = rollKey(slotId, name);
  if (key !== name && updated[name]) {
    RING_SLOT_IDS.forEach((ringId) => {
      if (slotNames[ringId] === name && !updated[rollKey(ringId, name)]) updated[rollKey(ringId, name)] = updated[name];
    });
    delete updated[name];
  }
  if (next) updated[key] = next;
  else delete updated[key];
  return updated;
}
// Buildy z rollami gracza: przedmioty o zmienionych rollach zastępują wersje 50% (wynik z wyszukiwania zostaje).
function applyBuildRolls(build, rolls) {
  if (!rolls || Object.keys(rolls).length === 0) return build;
  let changed = false;
  const slots = build.slots.map((slot) => {
    const spec = slot.item && rollsOf(rolls, slot.id, slot.item.name);
    if (!spec) return slot;
    changed = true;
    return { ...slot, item: withRolls(slot.item, spec) };
  });
  if (!changed) return build;
  const totals = itemStatTotals(slots.filter((slot) => slot.item).map((slot) => slot.item));
  return { ...build, slots, totals };
}

// "How is the score calculated?": zasady + przykład z tego buildu.
function ScoreGuide({ build }) {
  const [open, setOpen] = useState(false);
  const profile = build.profile;
  const topWeights = Object.entries(profile.weights)
    .filter(([key, weight]) => weight !== 0 && STAT_META[key] && !profile.derivedKeys.has(key))
    .sort((a, b) => Math.abs(b[1]) - Math.abs(a[1]))
    .slice(0, 8);
  const example = build.slots.filter((slot) => slot.item && slot.contributions.length > 0).sort((a, b) => b.score - a.score)[0];
  return (
    <div className="flex flex-col gap-2">
      <button type="button" onClick={() => setOpen(!open)} className="mc-link self-start text-sm" aria-expanded={open}>
        {open ? "▾" : "▸"} How is the score calculated?
      </button>
      {open && (
        <div className="wbr-drop mc-slot flex flex-col gap-3 p-3 text-sm text-zinc-200">
          <p>
            Every identification becomes points: <span className="mc-gold">value ÷ unit × weight × 10</span>. The unit makes stats comparable
            (1,000 Health, 10% damage or defence, 100 raw spell damage, 150 raw main attack damage, 5 Mana Regen, 5 skill points…) and the
            weight says how much {build.archetype} cares about it. Weights come from {ARCHETYPES[build.archetype].guideBuilds} guide build
            {ARCHETYPES[build.archetype].guideBuilds === 1 ? "" : "s"}, your focus sliders, damage/defence focus and extra priorities.
          </p>
          <ul className="flex flex-wrap gap-2">
            {topWeights.map(([key, weight]) => (
              <li key={key} className="mc-slot px-2 py-0.5 text-xs">
                {STAT_META[key].scale}
                {STAT_META[key].unit || ""} {STAT_META[key].label} = {weight < 0 ? "−" : ""}
                {formatNumber(Math.round(Math.abs(weight) * SCORE_SCALE * 10) / 10)} pts
              </li>
            ))}
          </ul>
          <ul className="flex list-disc flex-col gap-1 pl-5">
            <li>
              Weapon: base DPS ÷ 100 × {profile.weaponWeight.toFixed(1)} × 10, counted less when its damage is outside your damage focus.
              {build.mainAttack ? ` With the Main attack DPS slider above meta, the build's real main attack DPS (${formatNumber(Math.round(build.mainAttack.dps))}) replaces the linear main attack points.` : ""}
            </li>
            <li>Item level window ({(LEVEL_WINDOWS.find((entry) => entry.id === build.options.levelWindow) || LEVEL_WINDOWS[0]).label.toLowerCase()}): items far below your level lose {Math.round(profile.tuning.levelGapPenalty * 100)}% of their score per level outside the window (never more than {Math.round((1 - profile.tuning.levelGapFloor) * 100)}%).</li>
            <li>Penalties: skill point requirements outside the archetype's skills (−{formatNumber(Math.round(profile.tuning.offSkillPenalty * SCORE_SCALE * 10) / 10)} per 25 points), items that take the build's health below the class base, and builds that need more skill points than the level gives.</li>
            <li>Bonuses: items from guide builds +{Math.round(profile.tuning.guideBonus * 50)}–{Math.round(profile.tuning.guideBonus * 100)}% (if enabled); every free skill point +{formatNumber(Math.round(profile.tuning.leftoverSp * SCORE_SCALE * 10) / 10)}.</li>
            <li>
              The score on a card is the item's value in this build: its identification points{build.mainAttack ? " and its share of the real main attack DPS" : ""}, minus {formatNumber(Math.round(profile.tuning.leftoverSp * SCORE_SCALE * 10) / 10)} for
              every skill point the build has to spend because of it. "Other picks" ranks items the same way, so the list matches what the
              optimizer prefers. Identifications count at their max roll (100%, like Wynnbuilder) unless you set rolls.
            </li>
            <li>Every weight and constant above can be changed in the "Score calculation" tab{profile.overriddenKeys && profile.overriddenKeys.size > 0 ? ` (${profile.overriddenKeys.size} stat weights are overridden right now)` : ""}.</li>
          </ul>
          {example && (
            <div className="flex flex-col gap-1">
              <span className="mc-gold">Example: {example.item.name} ({formatScore(example.score)} pts)</span>
              <ul className="flex flex-col gap-0.5 text-xs">
                {[...example.contributions].sort((a, b) => Math.abs(b.contribution) - Math.abs(a.contribution)).slice(0, 5).map((entry) => {
                  const { label, math } = contributionLabel(entry, profile);
                  return (
                    <li key={entry.key} className="flex justify-between gap-3">
                      <span className="text-zinc-300">
                        {label} {math && <span className="text-zinc-500">{math}{math.includes("÷") ? " × 10" : ""}</span>}
                      </span>
                      <span className="tabular-nums" style={ts({ color: entry.contribution >= 0 ? "#55FF55" : "#FF5555" })}>
                        {entry.contribution >= 0 ? "+" : ""}
                        {formatScore(entry.contribution)}
                      </span>
                    </li>
                  );
                })}
              </ul>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function SkillPointPanel({ skillPoints }) {
  const usedPct = skillPoints.available > 0 ? Math.min(100, (skillPoints.required / skillPoints.available) * 100) : 0;
  return (
    <section className="mc-panel flex flex-col gap-3 p-4">
      <div className="flex items-center justify-between gap-2">
        <h3 className="mc-title text-sm uppercase">Skill points</h3>
        <span className="mc-slot px-2 py-0.5 text-xs" style={ts({ color: skillPoints.valid ? "#55FF55" : "#FF5555" })}>
          {skillPoints.valid ? "Equippable" : "Over budget"}
        </span>
      </div>
      <div>
        <div className="flex items-baseline justify-between text-sm">
          <span className="text-zinc-400" title={skillPoints.free ? "Points for the items' requirements (+ free points spent where they add most)" : undefined}>{skillPoints.free ? "Assigned" : "Assigned to meet requirements"}</span>
          <span className="tabular-nums text-zinc-100">
            {skillPoints.free && SKILLS.some((skill) => skillPoints.free[skill] > 0) ? (
              <>
                {skillPoints.minimum} <span style={ts({ color: "#55FF55" })}>(+{skillPoints.required - skillPoints.minimum})</span> / {skillPoints.available}
              </>
            ) : (
              `${skillPoints.required} / ${skillPoints.available}`
            )}
          </span>
        </div>
        <div className="mc-bar mt-1">
          <div className="mc-bar-fill" style={ts({ width: `${usedPct}%`, background: skillPoints.valid ? "#7FE828" : "#FF5555" })} />
        </div>
        {skillPoints.free && SKILLS.some((skill) => skillPoints.free[skill] > 0) ? (
          <p className="mt-1 text-xs" style={ts({ color: "#55FF55" })} title={`The set itself needs ${skillPoints.minimum}; the rest went where it raises the goal most (or first where it gets the build over the EHP / mana / sustain filters).`}>
            Free points spent: {SKILLS.filter((skill) => skillPoints.free[skill] > 0).map((skill) => `(+${skillPoints.free[skill]}) ${SKILL_STYLE[skill].short}`).join(", ")}
            {skillPoints.remaining > 0 ? ` · ${skillPoints.remaining} left (no gain)` : ""}
          </p>
        ) : (
          <p className="mt-1 text-xs text-zinc-500" title="Free points you can put into your archetype's skills.">
            {skillPoints.remaining} free points.
          </p>
        )}
      </div>
      <ul className="flex flex-col gap-2">
        {SKILLS.map((skill) => {
          const assigned = skillPoints.assigned[skill];
          const free = (skillPoints.free && skillPoints.free[skill]) || 0;
          return (
            <li key={skill} className="grid grid-cols-12 items-center gap-2 text-xs">
              <span className="col-span-4 truncate" style={ts({ color: SKILL_STYLE[skill].color })}>
                {SKILL_STYLE[skill].symbol} {SKILL_LABELS[skill]}
              </span>
              <div className="mc-bar col-span-3">
                <div className="mc-bar-fill" style={ts({ width: `${Math.min(100, assigned)}%`, background: SKILL_STYLE[skill].color })} />
              </div>
              <span className="col-span-3 whitespace-nowrap text-right tabular-nums text-zinc-200" title={free ? `${assigned - free} for the items' requirements + ${free} free points spent here` : "Points you assign"}>
                {assigned - free}
                {free > 0 && <span style={ts({ color: "#55FF55" })}> (+{free})</span>}
              </span>
              <span className="col-span-2 text-right tabular-nums text-zinc-500" title="Total with item bonuses">
                {skillPoints.totals[skill]}
              </span>
            </li>
          );
        })}
      </ul>
      <p className="text-xs text-zinc-500" title="Columns: assigned points · total with item bonuses. Max 100 assigned per skill.">
        Assigned · total with items.
      </p>
    </section>
  );
}

// Obrona żywiołu = suma bazowych obron + procentowy bonus (żywiołu i "Elemental Defence").
// Przy ujemnej bazie dodatni % przesuwa wartość w stronę zera (jak opisuje Stats and Identifications Guide).
function elementalDefences(build) {
  const items = build.slots.filter((slot) => slot.item).map((slot) => slot.item);
  return ELEMENTS.map((element) => {
    const prefix = element.charAt(0);
    const raw = items.reduce((sum, item) => sum + (item.base[`${prefix}Def`] || 0), 0);
    const pct = items.reduce((sum, item) => sum + (item.ids[`${prefix}DefPct`] || 0) + (item.ids.rDefPct || 0), 0);
    return { element, raw, pct, effective: Math.round(raw + (Math.abs(raw) * pct) / 100) };
  });
}


// KALKULACJA DPS I EFFECTIVE HP (wzory z kodu Wynnbuildera: build_utils.js, damage_calc.js, builder_graph.js)
// - Bonus ze Skill Pointów: (r/(1-r))·(1 - r^SP)/100, r = 0.9908, max 150 SP. Str/Dex/Int ×1, Def ×0.867, Agi ×0.951.
// - Obrażenia żywiołu: baza × (1 + bonus SP żywiołu + Md/Sd% + Damage% + żywioł% + Elemental%), potem raw.
//   Strength mnoży całość (1 + bonus Str), crit: szansa = bonus z Dex, trafienie krytyczne × (Str + 1 + Crit Damage%).
// - Main attack: obrażenia na uderzenie × uderzenia/s (z Attack Speed tier). Czar: baza broni × mnożnik szybkości ataku.
// - HP = 5 × poziom + 5 + HP z przedmiotów. EHP = HP / (0.1·Agi% + (1 - Agi%)·(1 - Def%)) / mnożnik klasy
//   (relik 1.4, bow 1.3, wand 1.2, dagger/spear 1.0) / redukcje z drzewka. Nie wliczamy powderów ani tomów.
const CLASS_DEFENSE = { relik: 0.6, bow: 0.7, wand: 0.8, dagger: 1.0, spear: 1.0 };
const SKILL_DAMAGE_MULT = { str: 1, dex: 1, int: 1, def: 0.867, agi: 0.951 };
const AGILITY_DAMAGE_TAKEN = 0.1; // agiDef = 90 w Wynnbuilderze
const DAMAGE_PARTS = [
  ["n", "neutral", null],
  ["e", "earth", "str"],
  ["t", "thunder", "dex"],
  ["w", "water", "int"],
  ["f", "fire", "def"],
  ["a", "air", "agi"],
];

function skillPercent(points) {
  if (!points || points <= 0) return 0;
  const r = 0.9908;
  return ((r / (1 - r)) * (1 - Math.pow(r, Math.min(points, 150)))) / 100;
}

function collectIds(items) {
  const totals = {};
  items.forEach((item) => {
    Object.entries(item.ids).forEach(([key, value]) => {
      totals[key] = (totals[key] || 0) + value;
    });
  });
  Object.entries(setBonusIds(items)).forEach(([key, value]) => {
    totals[key] = (totals[key] || 0) + value;
  });
  return totals;
}

// Średnie obrażenia jednego trafienia (kind "Md" = main attack, "Sd" = czar 100%) z uwzględnieniem critów.
function expectedHit(baseByElement, ids, skills, kind) {
  const lower = kind === "Md" ? "md" : "sd";
  const staticBoost = ((ids[`${lower}Pct`] || 0) + (ids.damPct || 0)) / 100;
  const totalBase = DAMAGE_PARTS.reduce((sum, [, element]) => sum + (baseByElement[element] || 0), 0);
  const elementalBase = totalBase - (baseByElement.neutral || 0);
  const propRaw = (ids[`${lower}Raw`] || 0) + (ids.damRaw || 0);
  const rainbowRaw = (ids[`r${kind}Raw`] || 0) + (ids.rDamRaw || 0);
  let total = 0;
  DAMAGE_PARTS.forEach(([prefix, element, skill]) => {
    const base = baseByElement[element] || 0;
    if (base <= 0) return;
    const skillBoost = skill ? skillPercent(skills[skill]) * SKILL_DAMAGE_MULT[skill] : 0;
    let boost = 1 + skillBoost + staticBoost + ((ids[`${prefix}${kind}Pct`] || 0) + (ids[`${prefix}DamPct`] || 0)) / 100;
    if (prefix !== "n") boost += ((ids[`r${kind}Pct`] || 0) + (ids.rDamPct || 0)) / 100;
    let damage = base * boost;
    damage += (ids[`${prefix}${kind}Raw`] || 0) + (ids[`${prefix}DamRaw`] || 0);
    if (totalBase > 0) damage += (base / totalBase) * propRaw;
    if (prefix !== "n" && elementalBase > 0) damage += (base / elementalBase) * rainbowRaw;
    total += Math.max(0, damage);
  });
  const strBoost = 1 + skillPercent(skills.str) * SKILL_DAMAGE_MULT.str;
  const critChance = Math.min(1, skillPercent(skills.dex));
  const critMult = 1 + (ids.critDamPct || 0) / 100;
  return { hit: total * ((1 - critChance) * strBoost + critChance * (strBoost + critMult)), critChance, critMult, strBoost };
}

function attackSpeedAfterTier(weapon, tier) {
  const index = Math.min(ATTACK_SPEEDS.length - 1, Math.max(0, ATTACK_SPEEDS.indexOf(weapon.atkSpd) + (tier || 0)));
  return ATTACK_SPEEDS[index];
}

// DPS main attacku samej broni (jej własne bonusy, bez Skill Pointów i drzewka) - do porównywania broni.
// Liczone tym samym silnikiem co podsumowanie buildu (relik: 3 promienie po 33%).
function weaponMainAttackDps(weapon) {
  if (!weapon || weapon.category !== "weapon") return 0;
  const stats = { ...weapon.ids };
  SKILLS.forEach((skill) => {
    stats[skill] = 0; // bez Skill Pointów, także tych z samej broni
  });
  MULTIPLIER_MAPS.forEach((name) => {
    stats[name] = {};
  });
  const melee = evaluateSpell(cloneJson(DEFAULT_MELEE_SPELLS[weapon.type]), stats, weapon, 0);
  const speed = attackSpeedAfterTier(weapon, weapon.ids.atkTier);
  return (melee.main ? melee.main.amount : 0) * HITS_PER_SECOND[speed];
}

// DRZEWKO UMIEJĘTNOŚCI W OBLICZENIACH (własna implementacja semantyki danych atree.json Wynnbuildera)
// 1. Scalanie: domyślne zdolności klasy (melee id 999, Elemental Mastery id 998) + aktywne węzły. Węzeł z `base`
//    dokleja swoje efekty do zdolności bazowej i sumuje jej właściwości (props); pozostałe tworzą własną zdolność.
// 2. raw_stat bez przełącznika: stałe bonusy (np. Earth Mastery: +% i +obrażenia do żywiołu). Z przełącznikiem:
//    tylko gdy gracz go włączy. stat_scaling: suwaki (np. Corrupted, Focus) albo przeliczniki ze statystyk/props.
//    Najpierw liczone są wszystkie zmiany props, potem statystyki, więc "Ability.prop" widzi końcowe wartości.
// 3. Mnożniki damMult / defMult / healMult / manaMult są mnożone, nie dodawane; Potion, Vulnerability i Mask
//    nie kumulują się (liczy się najwyższy). Klucz "X;e" działa tylko na żywioł, "X;m" tylko na main attack,
//    "X:3.Nazwa części" tylko na tę część czaru.
// 4. Czary: replace_spell tworzy albo nadpisuje czar, add_spell_prop dokłada mnożniki, trafienia, koszt, części.
//    Część obrażeń: konwersja broni (neutral skaluje broń, żywioły dostają % całości), × mnożnik szybkości ataku
//    (poza melee), + DamAdd z masteries, bonusy %, raw × suma konwersji, × Strength, crit (Dexterity) i mnożniki.
//    Część "hits" sumuje inne części × liczba trafień. Koszt: koszt × (1 - Int% × 0.5 / Int%(150)) + raw, × %.
const MELEE_ABILITY_ID = 999;
const MELEE_RANGE = { Mage: 12, Warrior: 4, Archer: 9, Assassin: 3, Shaman: 32.25 }; // zasięg main attacku (bloki)
const SPELL_CLICKS_PER_SECOND = 9; // czar = 3 kliknięcia, więc spam to 3 rzuty na sekundę
const BASE_MANA_REGEN = 25; // /5s, dla każdej klasy

// SPELL DPS: "spam" = obrażenia czaru × 3 rzuty/s; "sustained" = tyle rzutów/s, na ile starcza many
// ((Mana Regen + 25)/5 na sekundę plus zwrot many z samego czaru), nie więcej niż spam.
function spellDpsOf(spell, manaRegen, clicksPerSecond = SPELL_CLICKS_PER_SECOND) {
  if (!spell || !spell.main || spell.main.type !== "damage" || spell.cost === null) return null;
  const spamCasts = clicksPerSecond / 3;
  const income = (manaRegen + BASE_MANA_REGEN) / 5;
  const net = spell.cost - (spell.manaGained || 0);
  const sustainedCasts = net > 0 ? Math.min(spamCasts, income / net) : spamCasts;
  return { spam: spell.main.amount * spamCasts, sustained: spell.main.amount * sustainedCasts, castsPerSecond: sustainedCasts, spamCasts };
}
// POISON (ID "poison" = obrażenia łącznie na 3 s, wiki: Identifications): 1 tick na sekundę po floor(poison / 3).
// Bez Strength, crita i bonusów % - tak liczy Wynnbuilder 2.x (displayPoisonDamage); wzór z papieru wynnfo z 2021
// (× (1 + Strength%) × (1 + powder boost)) jest nieaktualny.
function poisonDpsOf(poison) {
  return Math.max(0, Math.floor((poison || 0) / 3));
}
const MASTERY_ABILITY_ID = 998;
const DAMAGE_PREFIXES = ["n", "e", "t", "w", "f", "a"];
const DAMAGE_PREFIX_SKILL = [null, "str", "dex", "int", "def", "agi"];
const MULTIPLIER_MAPS = ["damMult", "defMult", "healMult", "manaMult"];
const NONSTACKING_MULTIPLIERS = ["Potion", "Vulnerability", "Mask"];
const INT_COST_SCALE = 0.5; // 150 Intelligence obniża koszt czarów o 50%
const meleeSpell = (name, display, parts) => ({ type: "replace_spell", name, base_spell: 0, scaling: "melee", use_atkspd: false, display, parts });
const DEFAULT_MELEE_SPELLS = {
  wand: meleeSpell("Wand Melee", "Melee", [{ name: "Melee", multipliers: [100, 0, 0, 0, 0, 0] }]),
  spear: meleeSpell("Melee", "Melee", [{ name: "Melee", multipliers: [100, 0, 0, 0, 0, 0] }]),
  bow: meleeSpell("Bow Shot", "Single Shot", [{ name: "Single Shot", multipliers: [100, 0, 0, 0, 0, 0] }]),
  dagger: meleeSpell("Melee", "Melee", [{ name: "Melee", multipliers: [100, 0, 0, 0, 0, 0] }]),
  relik: meleeSpell("Relik Melee", "Total", [
    { name: "Single Beam", multipliers: [33, 0, 0, 0, 0, 0] },
    { name: "Total", hits: { "Single Beam": 3 } },
  ]),
};

function cloneJson(value) {
  return value === undefined ? value : JSON.parse(JSON.stringify(value));
}

function statValue(stats, key) {
  const value = stats[key];
  return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

// Dodaje statystykę; mnożniki trafiają do map (damMult.X), gdzie Potion/Vulnerability/Mask biorą najwyższą wartość.
function mergeStat(stats, name, value) {
  if (typeof value !== "number" || !Number.isFinite(value)) return;
  const dot = name.indexOf(".");
  const start = dot === -1 ? name : name.slice(0, dot);
  if (dot !== -1 && MULTIPLIER_MAPS.includes(start)) {
    const key = name.slice(dot + 1);
    const map = stats[start] || (stats[start] = {});
    if (NONSTACKING_MULTIPLIERS.includes(key) && key in map) map[key] = Math.max(map[key], value);
    else map[key] = (map[key] || 0) + value;
    return;
  }
  stats[name] = (stats[name] || 0) + value;
}

function copyStats(stats) {
  const copy = { ...stats };
  MULTIPLIER_MAPS.forEach((name) => {
    copy[name] = { ...(stats[name] || {}) };
  });
  return copy;
}

// Aktywne węzły drzewka (po walidacji) scalone w zdolności, w kolejności wierszy drzewka.
// aspects: [[aspekt z tomes-aspects.json, tier 1..n]] - efekty tieru doklejane jak w Wynnbuilderze (atree.js,
// "Apply aspects"): tylko do zdolności, które są w drzewku, i tylko gdy wszystkie ich "deps" są aktywne.
function mergeTreeAbilities(playerClass, activeIds, aspects = []) {
  const merged = new Map();
  merged.set(MELEE_ABILITY_ID, {
    id: MELEE_ABILITY_ID,
    name: `${playerClass} Melee`,
    props: { range: MELEE_RANGE[playerClass] || 0 },
    effects: [cloneJson(DEFAULT_MELEE_SPELLS[CLASSES[playerClass].weapon])],
    nodes: [],
  });
  merged.set(MASTERY_ABILITY_ID, { id: MASTERY_ABILITY_ID, name: "Elemental Mastery", props: {}, effects: [], nodes: [] });
  const nodes = (TREE_DATA.classes[playerClass] || [])
    .filter((node) => activeIds.has(node.id))
    .sort((a, b) => a.row - b.row || a.col - b.col);
  // Najpierw zdolności samodzielne, potem ulepszenia doklejane do nich (base), żeby żadne nie przepadło.
  [...nodes.filter((node) => node.base === undefined), ...nodes.filter((node) => node.base !== undefined)].forEach((node) => {
    if (node.base === undefined) {
      merged.set(node.id, { id: node.id, name: node.name, props: cloneJson(node.props || {}), effects: cloneJson(node.effects || []), nodes: [node.name] });
      return;
    }
    const base = merged.get(node.base);
    if (!base) return;
    base.effects.push(...cloneJson(node.effects || []));
    base.nodes.push(node.name);
    Object.entries(node.props || {}).forEach(([key, value]) => {
      base.props[key] = key in base.props ? base.props[key] + value : value;
    });
  });
  aspects.forEach(([aspect, tier]) => {
    const level = aspect && aspect.tiers[Math.min(aspect.tiers.length, Math.max(1, tier)) - 1];
    ((level && level.abilities) || []).forEach((ability) => {
      if ((ability.deps || []).some((id) => !activeIds.has(id))) return;
      const base = merged.get(ability.base);
      if (!base) return;
      base.effects.push(...cloneJson(ability.effects || []));
      base.nodes.push(aspect.name);
      Object.entries(ability.props || {}).forEach(([key, value]) => {
        base.props[key] = key in base.props ? base.props[key] + value : value;
      });
    });
  });
  return merged;
}

// Suwaki (stat_scaling ze slider) i przełączniki (raw_stat z toggle) aktywnych zdolności.
function treeInteractives(merged) {
  const sliders = new Map();
  const toggles = new Map();
  let pending = [];
  merged.forEach((ability) => {
    ability.effects.forEach((effect) => {
      if (effect.type === "stat_scaling" && effect.slider === true && effect.slider_name) pending.push([effect, ability]);
      if (effect.type === "raw_stat" && effect.toggle && !toggles.has(effect.toggle)) {
        toggles.set(effect.toggle, { name: effect.toggle, ability: ability.name });
      }
    });
  });
  for (let pass = 0; pass < 10 && pending.length > 0; pass += 1) {
    const deferred = [];
    pending.forEach(([effect, ability]) => {
      const { slider_name: name, behavior = "merge", slider_max: max = 0, slider_default: defaultValue = 0 } = effect;
      const info = sliders.get(name);
      if (info) {
        if (behavior === "overwrite") {
          if ("slider_max" in effect) info.max = max;
          if ("slider_default" in effect) info.defaultValue = defaultValue;
          if ("scaling" in effect && effect.output && !Array.isArray(effect.output)) {
            info.owner.effects.forEach((other) => {
              if (other !== effect && "scaling" in other && other.output && !Array.isArray(other.output) && other.output.name === effect.output.name) {
                other.scaling = [0];
              }
            });
          }
          info.overwritten = true;
        } else if (!info.overwritten) {
          info.max += max;
          if ("slider_max_mult" in effect) info.maxMult *= effect.slider_max_mult;
          info.defaultValue += defaultValue;
        }
      } else if (behavior === "merge") {
        sliders.set(name, { name, ability: ability.name, max, defaultValue, step: effect.slider_step || 1, owner: ability, maxMult: 1, overwritten: false });
      } else {
        deferred.push([effect, ability]);
      }
    });
    if (deferred.length === pending.length) break;
    pending = deferred;
  }
  sliders.forEach((info) => {
    if (info.maxMult !== 1) info.max = Math.round(info.max * info.maxMult);
    info.max = Math.max(0, info.max);
    info.defaultValue = Math.min(info.max, Math.max(0, info.defaultValue));
  });
  return { sliders, toggles };
}

function sliderValue(info, settings) {
  const chosen = settings && settings.sliders ? settings.sliders[info.name] : undefined;
  const value = typeof chosen === "number" && Number.isFinite(chosen) ? chosen : info.defaultValue;
  return Math.min(info.max, Math.max(0, value));
}

function roundNear(value) {
  const rounded = Math.round(value);
  return Math.abs(value - rounded) < 1e-7 ? rounded : value;
}

// Stałe bonusy bez przełącznika (typ "stat") z niezmienionych zdolności.
function treeRawStats(merged, stats) {
  merged.forEach((ability) => {
    ability.effects.forEach((effect) => {
      if (effect.type !== "raw_stat" || effect.toggle) return;
      (effect.bonuses || []).forEach((bonus) => {
        if (bonus.type === "stat" && typeof bonus.value === "number") mergeStat(stats, bonus.name, bonus.value);
      });
    });
  });
}

// Przełączniki, suwaki i przeliczniki. Zwraca zdolności ze zmienionymi props i statystyki do dodania.
function applyTreeScaling(merged, preStats, interactives, settings) {
  const edited = new Map([...merged].map(([id, ability]) => [id, { ...ability, props: { ...ability.props } }]));
  const added = {};
  const translate = (value) => {
    if (typeof value === "string") {
      const [id, prop] = value.split(".");
      const ability = edited.get(Number(id));
      const resolved = ability ? ability.props[prop] : undefined;
      return typeof resolved === "number" && Number.isFinite(resolved) ? resolved : 0;
    }
    return typeof value === "number" && Number.isFinite(value) ? value : 0;
  };
  const toggledOn = (name) => Boolean(settings && settings.toggles && settings.toggles[name]);
  const applyBonus = (bonus, value, onlyType) => {
    if (!bonus || bonus.type !== onlyType) return;
    if (bonus.type === "stat") {
      mergeStat(added, bonus.name, translate(value));
    } else if (bonus.type === "prop") {
      const ability = edited.get(bonus.abil);
      if (!ability) return;
      const current = typeof ability.props[bonus.name] === "number" ? ability.props[bonus.name] : 0;
      ability.props[bonus.name] = bonus.mult ? current * translate(value) : current + translate(value);
    }
  };
  const scalingTotal = (effect) => {
    const { slider = false, scaling = [0], requirement = 0, base = 0 } = effect;
    let { positive = true } = effect;
    let total = 0;
    if (slider) {
      // Suwak "modify" bez suwaka bazowego nic nie robi; brak suwaka = efekt pominięty.
      const info = interactives.sliders.get(effect.slider_name);
      if (!info) return null;
      const value = sliderValue(info, settings);
      if (requirement > value) return null;
      const input = Math.trunc(value - requirement);
      total = effect.multiplicative ? (((100 + translate(scaling[0])) / 100) ** input - 1) * 100 : input * translate(scaling[0]);
      positive = false;
    } else {
      (effect.inputs || []).forEach((input, index) => {
        const factor = translate(scaling[index]);
        if (input.type === "stat") total += statValue(preStats, input.name) * factor;
        else if (input.type === "prop") {
          const ability = edited.get(input.abil);
          if (ability && typeof ability.props[input.name] === "number") total += ability.props[input.name] * factor;
        }
      });
    }
    total += translate(base);
    return [total, positive];
  };
  const processEffects = (onlyType) => {
    merged.forEach((ability) => {
      ability.effects.forEach((effect) => {
        if (effect.type === "raw_stat") {
          (effect.bonuses || []).forEach((bonus) => {
            if (effect.toggle) {
              if (toggledOn(effect.toggle)) applyBonus(bonus, bonus.value, onlyType);
            } else if (bonus.type !== "stat") {
              applyBonus(bonus, bonus.value, onlyType);
            }
          });
        } else if (effect.type === "stat_scaling" && effect.output) {
          const result = scalingTotal(effect);
          if (!result) return;
          let [total, positive] = result;
          const round = effect.round ?? !effect.slider;
          if (round) total = Math.floor(roundNear(total));
          if (positive && total < 0) total = 0;
          if ("max" in effect) {
            const cap = translate(effect.max);
            if (cap > 0 && total > cap) total = cap;
            if (cap < 0 && total < cap) total = cap;
          }
          (Array.isArray(effect.output) ? effect.output : [effect.output]).forEach((output) => applyBonus(output, total, onlyType));
        }
      });
    });
  };
  processEffects("prop");
  processEffects("stat");
  return { edited, added, translate };
}

// Czary z replace_spell / add_spell_prop (liczone na zdolnościach po zmianach props).
function collectTreeSpells(edited, translate) {
  const spells = new Map();
  edited.forEach((ability) => {
    ability.effects.forEach((effect) => {
      if (effect.type !== "replace_spell") return;
      let spell = spells.get(effect.base_spell);
      if (spell) {
        Object.keys(effect).forEach((key) => {
          spell[key] = cloneJson(effect[key]);
        });
      } else {
        spell = cloneJson(effect);
        spells.set(effect.base_spell, spell);
      }
      (spell.parts || []).forEach((part) => {
        if (part.hits) Object.keys(part.hits).forEach((key) => (part.hits[key] = translate(part.hits[key])));
      });
    });
  });
  edited.forEach((ability) => {
    ability.effects.forEach((effect) => {
      if (effect.type !== "add_spell_prop" || !spells.has(effect.base_spell)) return;
      const spell = spells.get(effect.base_spell);
      const { target_part: target = null, cost = 0, mana_gained: manaGained = 0, behavior = "merge" } = effect;
      if ("cost" in spell) spell.cost += cost;
      if (manaGained) spell.mana_gained = (spell.mana_gained || 0) + translate(manaGained);
      if ("display" in effect) spell.display = effect.display;
      if (target === null) return;
      spell.parts = spell.parts || [];
      const part = spell.parts.find((entry) => entry.name === target);
      if (part) {
        if ("multipliers" in effect) {
          part.multipliers = part.multipliers || [0, 0, 0, 0, 0, 0];
          effect.multipliers.forEach((value, index) => {
            part.multipliers[index] = behavior === "overwrite" ? value : (part.multipliers[index] || 0) + value;
          });
        } else if ("power" in effect) {
          part.power = behavior === "overwrite" ? effect.power : (part.power || 0) + effect.power;
        } else if ("hits" in effect) {
          part.hits = part.hits || {};
          Object.entries(effect.hits).forEach(([key, raw]) => {
            const value = translate(raw);
            part.hits[key] = behavior === "overwrite" || !(key in part.hits) ? value : part.hits[key] + value;
          });
        }
        if ("hide" in effect) part.display = false;
        if ("ignored_mults" in effect) part.ignored_mults = [...(part.ignored_mults || []), ...effect.ignored_mults];
      } else if (behavior === "merge") {
        const added = cloneJson(effect);
        added.name = target;
        if (added.hits) Object.keys(added.hits).forEach((key) => (added.hits[key] = translate(added.hits[key])));
        if ("hide" in effect) added.display = false;
        spell.parts.push(added);
      }
    });
  });
  return spells;
}

function weaponDamageRanges(weapon) {
  if (weapon.powderedRanges) return weapon.powderedRanges.map((range) => range.slice());
  const ranges = weapon.damageRanges || {};
  return ["neutral", "earth", "thunder", "water", "fire", "air"].map((element) => {
    if (ranges[element]) {
      const [min, max] = String(ranges[element]).split("-").map(Number);
      return [min || 0, Number.isFinite(max) ? max : min || 0];
    }
    const average = (weapon.damage || {})[element] || 0;
    return [average, average];
  });
}

// Jedna część czaru albo main attacku: średnie obrażenia bez crita, z critem i po żywiołach.
function spellPartDamage(stats, weapon, baseConversions, { useSpell, ignoreSpeed, partId, ignoreStr = false, ignoredMults = [] }) {
  const conversions = DAMAGE_PREFIXES.map(
    (prefix, index) => (baseConversions[index] || 0) + statValue(stats, `${prefix}ConvBase:${partId}`) + statValue(stats, `${prefix}ConvBase`)
  );
  const ranges = weaponDamageRanges(weapon);
  let present = ranges.map(([, max]) => max > 0);
  const neutralConvert = conversions[0] / 100;
  if (neutralConvert === 0) present = present.map(() => false);
  let weaponMin = 0;
  let weaponMax = 0;
  const damages = ranges.map(([min, max]) => {
    weaponMin += min;
    weaponMax += max;
    return [min * neutralConvert, max * neutralConvert];
  });
  let totalConvert = neutralConvert;
  for (let index = 1; index < 6; index += 1) {
    if (conversions[index] > 0) {
      const fraction = conversions[index] / 100;
      damages[index][0] += fraction * weaponMin;
      damages[index][1] += fraction * weaponMax;
      present[index] = true;
      totalConvert += fraction;
    }
  }
  if (!ignoreSpeed) {
    const speedMult = SPELL_SPEED_MULT[weapon.atkSpd] || SPELL_SPEED_MULT.NORMAL;
    damages.forEach((damage) => {
      damage[0] *= speedMult;
      damage[1] *= speedMult;
    });
  }
  DAMAGE_PREFIXES.forEach((prefix, index) => {
    if (!present[index]) return;
    damages[index][0] += statValue(stats, `${prefix}DamAddMin`);
    damages[index][1] += statValue(stats, `${prefix}DamAddMax`);
  });
  const kind = useSpell ? "Sd" : "Md";
  const lower = kind.toLowerCase();
  const skillBoost = DAMAGE_PREFIX_SKILL.map((skill) => (skill ? skillPercent(statValue(stats, skill)) * SKILL_DAMAGE_MULT[skill] : 0));
  const staticBoost = (statValue(stats, `${lower}Pct`) + statValue(stats, "damPct")) / 100;
  let totalMin = 0;
  let totalMax = 0;
  const saved = [];
  DAMAGE_PREFIXES.forEach((prefix, index) => {
    saved.push(damages[index].slice());
    totalMin += damages[index][0];
    totalMax += damages[index][1];
    let boost = 1 + skillBoost[index] + staticBoost + (statValue(stats, `${prefix}${kind}Pct`) + statValue(stats, `${prefix}DamPct`)) / 100;
    if (index > 0) boost += (statValue(stats, `r${kind}Pct`) + statValue(stats, "rDamPct")) / 100;
    damages[index][0] *= boost;
    damages[index][1] *= boost;
  });
  const elementalMin = totalMin - saved[0][0];
  const elementalMax = totalMax - saved[0][1];
  const propRaw = statValue(stats, `${lower}Raw`) + statValue(stats, "damRaw");
  const rainbowRaw = statValue(stats, `r${kind}Raw`) + statValue(stats, "rDamRaw");
  DAMAGE_PREFIXES.forEach((prefix, index) => {
    const own = present[index] ? statValue(stats, `${prefix}${kind}Raw`) + statValue(stats, `${prefix}DamRaw`) : 0;
    let minBoost = own;
    let maxBoost = own;
    if (totalMax > 0) {
      minBoost += (totalMin === 0 ? saved[index][1] / totalMax : saved[index][0] / totalMin) * propRaw;
      maxBoost += (saved[index][1] / totalMax) * propRaw;
    }
    if (index > 0 && elementalMax > 0) {
      minBoost += (elementalMin === 0 ? saved[index][1] / elementalMax : saved[index][0] / elementalMin) * rainbowRaw;
      maxBoost += (saved[index][1] / elementalMax) * rainbowRaw;
    }
    damages[index][0] += minBoost * totalConvert;
    damages[index][1] += maxBoost * totalConvert;
  });
  const strBoost = ignoreStr ? 1 : 1 + skillBoost[1];
  let damageMult = 1;
  const elementMult = [1, 1, 1, 1, 1, 1];
  Object.entries(stats.damMult || {}).forEach(([key, value]) => {
    if (key.includes(":") && key.split(":")[1] !== partId) return;
    if (ignoredMults.includes(key)) return;
    if (key.includes(";")) {
      const element = key.split(";")[1];
      if (element === "m") {
        if (!useSpell) damageMult *= 1 + value / 100;
      } else if (DAMAGE_PREFIXES.includes(element)) {
        elementMult[DAMAGE_PREFIXES.indexOf(element)] *= 1 + value / 100;
      }
    } else {
      damageMult *= 1 + value / 100;
    }
  });
  const critMult = ignoreStr ? 0 : 1 + statValue(stats, "critDamPct") / 100;
  const normalMin = [];
  const normalMax = [];
  const critMin = [];
  const critMax = [];
  damages.forEach((damage, index) => {
    const min = Math.max(0, damage[0] * elementMult[index]);
    const max = Math.max(0, damage[1] * elementMult[index]);
    normalMin.push(min * strBoost * damageMult);
    normalMax.push(max * strBoost * damageMult);
    critMin.push(min * (strBoost + critMult) * damageMult);
    critMax.push(max * (strBoost + critMult) * damageMult);
  });
  const sum = (list) => list.reduce((total, value) => total + value, 0);
  return {
    normal: (sum(normalMin) + sum(normalMax)) / 2,
    crit: (sum(critMin) + sum(critMax)) / 2,
    perElement: normalMin.map((value, index) => (value + normalMax[index]) / 2),
    normalMin,
    normalMax,
    critMin,
    critMax,
    // Mnożniki części po mnożnikach z drzewka (jak "✤ 25% ❋ 5% (30%)" w Wynnbuilderze).
    multipliers: conversions.map((value, index) => value * elementMult[index] * damageMult),
  };
}

function spellCost(stats, spell) {
  if (!("cost" in spell) || !(spell.base_spell >= 1 && spell.base_spell <= 4)) return null;
  const id = spell.base_spell;
  let cost = spell.cost * (1 - (skillPercent(statValue(stats, "int")) * INT_COST_SCALE) / skillPercent(150));
  cost += statValue(stats, `spRaw${id}`);
  cost *= 1 + statValue(stats, `spPct${id}`) / 100;
  return Math.max(1, cost) * (1 + statValue(stats, `spPct${id}Final`) / 100);
}

// Wszystkie części czaru; średnia z critem, leczenie jako % HP × mnożniki leczenia.
function evaluateSpell(spell, stats, weapon, totalHp) {
  const critChance = Math.min(1, skillPercent(statValue(stats, "dex")));
  const defaultSpell = "scaling" in spell ? spell.scaling === "spell" : true;
  const defaultSpeed = "use_atkspd" in spell ? spell.use_atkspd : true;
  const parts = new Map((spell.parts || []).map((part) => [part.name, part]));
  const results = new Map();
  const visiting = new Set();
  const evalPart = (name) => {
    if (results.has(name)) return results.get(name);
    const part = parts.get(name);
    if (!part || visiting.has(name)) return null;
    visiting.add(name);
    const partId = `${spell.base_spell}.${part.name}`;
    let result = null;
    if (Array.isArray(part.multipliers)) {
      const useSpell = "scaling" in part ? part.scaling === "spell" : defaultSpell;
      const useSpeed = "use_atkspd" in part ? part.use_atkspd : defaultSpeed;
      const damage = spellPartDamage(stats, weapon, part.multipliers, {
        useSpell,
        ignoreSpeed: !useSpeed,
        partId,
        ignoreStr: part.use_str === false,
        ignoredMults: part.ignored_mults || [],
      });
      result = {
        type: "damage",
        amount: (1 - critChance) * damage.normal + critChance * damage.crit,
        normal: damage.normal,
        crit: damage.crit,
        perElement: damage.perElement,
        normalMin: damage.normalMin,
        normalMax: damage.normalMax,
        critMin: damage.critMin,
        critMax: damage.critMax,
        multipliers: damage.multipliers,
        useSpell,
      };
    } else if (typeof part.power === "number") {
      let healMult = 1;
      Object.entries(stats.healMult || {}).forEach(([key, value]) => {
        if (key.includes(":") && key.split(":")[1] !== partId) return;
        healMult *= 1 + value / 100;
      });
      healMult *= 1 + statValue(stats, "healPct") / 100;
      result = { type: "heal", amount: part.power * totalHp * healMult };
    } else if (part.hits) {
      const zero = () => [0, 0, 0, 0, 0, 0];
      result = { type: null, amount: 0, normal: 0, crit: 0, perElement: zero(), normalMin: zero(), normalMax: zero(), critMin: zero(), critMax: zero(), multipliers: zero() };
      const addVector = (key, sub, effective) => {
        if (sub[key]) result[key] = result[key].map((value, index) => value + sub[key][index] * effective);
      };
      Object.entries(part.hits).forEach(([subName, hits]) => {
        const sub = evalPart(subName);
        if (!sub || !Number.isFinite(hits)) return;
        if (result.type && sub.type !== result.type) return;
        result.type = sub.type;
        const effective = part.tick_rounding ? (hits > 0 ? 1 / (Math.floor((1 / hits) * 20) * 0.05) : 0) : hits;
        if (!Number.isFinite(effective)) return;
        result.amount += sub.amount * effective;
        result.normal += (sub.normal || 0) * effective;
        result.crit += (sub.crit || 0) * effective;
        ["perElement", "normalMin", "normalMax", "critMin", "critMax", "multipliers"].forEach((key) => addVector(key, sub, effective));
        if (sub.useSpell !== undefined) result.useSpell = sub.useSpell;
      });
      // Brak części z obrażeniami/leczeniem (np. Teleport): czar użytkowy, bez liczby.
      if (!result.type) result = null;
    }
    visiting.delete(name);
    if (result) {
      result.name = part.name;
      result.display = part.display !== false;
      results.set(name, result);
    }
    return result;
  };
  (spell.parts || []).forEach((part) => evalPart(part.name));
  const all = (spell.parts || []).map((part) => results.get(part.name)).filter(Boolean);
  const main = results.get(spell.display) || all[all.length - 1] || null;
  return { name: spell.name, id: spell.base_spell, cost: spellCost(stats, spell), manaGained: spell.mana_gained || 0, main, parts: all, critChance, display: spell.display };
}

// Stan drzewka dla klasy: aktywne węzły (walidowane jak w zakładce), scalone zdolności, suwaki i przełączniki.
function treeStateFor(playerClass, selectedIds = [], aspects = []) {
  const tree = TREE_INDEX[playerClass];
  const resolved = tree ? resolveTree(tree, selectedIds) : { reachable: new Set(), points: 0 };
  const merged = mergeTreeAbilities(playerClass, resolved.reachable, aspects);
  return { active: resolved.reachable, points: resolved.points, merged, interactives: treeInteractives(merged) };
}

// Mapa statystyk buildu w nazwach Wynnbuildera: identyfikacje przedmiotów, Skill Pointy, HP, obrony.
function buildStatMap(build, items, weapon) {
  const stats = collectIds(items);
  SKILLS.forEach((skill) => {
    stats[skill] = build.skillPoints.totals[skill] || 0;
  });
  stats.hp = 5 * build.level + 5 + items.reduce((sum, item) => sum + (item.base.hp || 0), 0);
  ELEMENTS.forEach((element) => {
    const key = `${element.charAt(0)}Def`;
    stats[key] = items.reduce((sum, item) => sum + (item.base[key] || 0), 0);
  });
  MULTIPLIER_MAPS.forEach((name) => {
    stats[name] = {};
  });
  stats.classDef = weapon ? CLASS_DEFENSE[weapon.type] ?? 1 : 1;
  return stats;
}

// POWDER SPECIAL BRONI (wiki.gg/wiki/Powders, wartości jak w Wynnbuilderze js/powders.js): dwa powdery tier IV+
// tego samego żywiołu odblokowują special; decyduje żywioł pierwszego powdera, poziom (4, 4.5 ... 7) = średni tier
// powderów tego żywiołu. Ładuje się main attackami (ok. 5 s ciągłego bicia), odpala Shift-klikiem. Na razie tylko
// pokazujemy obrażenia/efekt w panelu Damage - generator go nie liczy (nie wiadomo, jak często się odpala).
const POWDER_SPECIALS = {
  earth: { name: "Quake", damage: [240, 280, 320, 360, 400, 440, 480], extra: ["radius", [4.5, 5, 5.5, 6, 6.5, 7, 7.5], " blocks"], effect: "stuns enemies around you" },
  thunder: { name: "Chain Lightning", damage: [200, 225, 250, 275, 300, 325, 350], extra: ["chains", [5, 6, 7, 8, 9, 10, 11], " times"], effect: "jumps between enemies" },
  water: { name: "Curse", boost: [10, 12.5, 15, 17.5, 20, 22.5, 25], duration: 4, effect: "enemies take more damage" },
  fire: { name: "Courage", damage: [110, 125, 140, 155, 170, 185, 200], boost: [10, 12.5, 15, 17.5, 20, 22.5, 25], duration: 4, effect: "damage boost for you and allies" },
  air: { name: "Wind Prison", nextHit: [100, 125, 150, 175, 200, 225, 250], duration: 5, effect: "holds enemies; the next hit deals more" },
};
function weaponPowderSpecial(weapon, stats, critChance) {
  if (!weapon || !weapon.powders || !Array.isArray(weapon.powders.list) || weapon.powders.list.length < 2) return null;
  const element = weapon.powders.list[0].element;
  const strong = weapon.powders.list.filter((powder) => powder.element === element && powder.tier >= 4);
  if (strong.length < 2 || !POWDER_SPECIALS[element]) return null;
  const average = strong.reduce((sum, powder) => sum + powder.tier, 0) / strong.length;
  const index = Math.max(0, Math.min(6, Math.round((average - 4) * 2)));
  const spec = POWDER_SPECIALS[element];
  const out = { element, name: spec.name, level: 4 + index / 2, index, effect: spec.effect, duration: spec.duration || null };
  if (spec.damage) {
    const conversions = [0, 0, 0, 0, 0, 0];
    conversions[1 + ELEMENTS.indexOf(element)] = spec.damage[index];
    const damage = spellPartDamage(stats, weapon, conversions, { useSpell: false, ignoreSpeed: true, partId: "0.Powder Special" });
    out.percent = spec.damage[index];
    out.damage = (1 - critChance) * damage.normal + critChance * damage.crit;
  }
  if (spec.extra) out.extra = { name: spec.extra[0], value: spec.extra[1][index], unit: spec.extra[2] };
  if (spec.boost) out.boost = spec.boost[index];
  if (spec.nextHit) out.nextHit = spec.nextHit[index];
  return out;
}

function computeBuildStats(build, treeSettings = null) {
  // tomy gracza (Creator / Optimizer: build.tomes) liczą się jak przedmioty z samymi identyfikacjami
  const items = [...build.slots.filter((slot) => slot.item).map((slot) => slot.item), ...(build.tomes || [])];
  const weapon = (build.slots.find((slot) => slot.id === "weapon") || {}).item;
  const ids = collectIds(items);
  const skills = build.skillPoints.totals;
  const stats = buildStatMap(build, items, weapon);
  // aspekty (treeSettings.aspects: pary [aspekt, tier]) doklejają się do zdolności drzewka jak w generatorze
  const tree = treeStateFor(build.playerClass, (treeSettings && treeSettings.selected) || [], (treeSettings && treeSettings.aspects) || []);
  treeRawStats(tree.merged, stats);
  const preStats = copyStats(stats);
  const scaled = applyTreeScaling(tree.merged, preStats, tree.interactives, treeSettings);
  Object.entries(scaled.added).forEach(([key, value]) => {
    if (MULTIPLIER_MAPS.includes(key)) Object.entries(value).forEach(([inner, amount]) => mergeStat(stats, `${key}.${inner}`, amount));
    else mergeStat(stats, key, value);
  });
  const hp = Math.max(5, statValue(stats, "hp") + statValue(stats, "hpBonus"));
  const result = { weapon, ids, skills, stats, hp, tree: { ...tree, activeCount: tree.active.size }, spells: [] };
  if (weapon) {
    const spells = collectTreeSpells(scaled.edited, scaled.translate);
    const melee = spells.has(0) ? evaluateSpell(spells.get(0), stats, weapon, hp) : null;
    const speed = attackSpeedAfterTier(weapon, statValue(stats, "atkTier"));
    const hps = HITS_PER_SECOND[speed];
    const hit = melee && melee.main ? melee.main.amount : 0;
    result.mainAttack = { speed, hps, hit, dps: hit * hps, name: melee ? melee.name : "Melee" };
    result.poison = { total: statValue(stats, "poison"), dps: poisonDpsOf(statValue(stats, "poison")) };
    result.melee = melee;
    result.spells = [...spells.keys()]
      .filter((id) => id !== 0)
      .sort((a, b) => a - b)
      .map((id) => evaluateSpell(spells.get(id), stats, weapon, hp));
    const reference = spellPartDamage(stats, weapon, [100, 0, 0, 0, 0, 0], { useSpell: true, ignoreSpeed: false, partId: "reference" });
    const meleeReference = spellPartDamage(stats, weapon, [100, 0, 0, 0, 0, 0], { useSpell: false, ignoreSpeed: true, partId: "reference-melee" });
    result.critChance = Math.min(1, skillPercent(statValue(stats, "dex")));
    result.spellHit = (1 - result.critChance) * reference.normal + result.critChance * reference.crit;
    // Jak "Combat Information" w grze: [100%] obrażenia per żywioł (bez crita) i łączny bonus z ekwipunku.
    const weaponBase = Object.values(weapon.damage || {}).reduce((sum, value) => sum + value, 0);
    result.hundred = {
      spell: { ranges: reference.normalMin.map((min, index) => [min, reference.normalMax[index]]), buff: weaponBase > 0 ? reference.normal / (weaponBase * SPELL_SPEED_MULT[weapon.atkSpd]) - 1 : 0 },
      melee: { ranges: meleeReference.normalMin.map((min, index) => [min, meleeReference.normalMax[index]]), buff: weaponBase > 0 ? meleeReference.normal / weaponBase - 1 : 0 },
    };
    result.critMult = 1 + statValue(stats, "critDamPct") / 100;
    result.strBoost = 1 + skillPercent(statValue(stats, "str")) * SKILL_DAMAGE_MULT.str;
    result.powderSpecial = weaponPowderSpecial(weapon, stats, result.critChance);
  }
  result.spells.forEach((spell) => {
    spell.dps = spellDpsOf(spell, statValue(stats, "mr"));
  });
  const bestSpell = result.spells.filter((spell) => spell.dps).sort((a, b) => b.dps.sustained - a.dps.sustained)[0] || null;
  result.spellDps = bestSpell ? { name: bestSpell.name, sustained: bestSpell.dps.sustained, spam: bestSpell.dps.spam, castsPerSecond: bestSpell.dps.castsPerSecond } : null;
  const defPct = skillPercent(statValue(stats, "def")) * SKILL_DAMAGE_MULT.def;
  const agiPct = skillPercent(statValue(stats, "agi")) * SKILL_DAMAGE_MULT.agi;
  const treeDefence = Object.values(stats.defMult || {}).reduce((product, value) => product * (1 - value / 100), 1);
  const classMultiplier = 2 - (weapon ? CLASS_DEFENSE[weapon.type] ?? 1 : CLASS_DEFENSE[CLASSES[build.playerClass].weapon] || 1);
  const damageTaken = classMultiplier * treeDefence;
  const hprRaw = statValue(stats, "hprRaw");
  const hprPct = statValue(stats, "hprPct") / 100;
  Object.assign(result, {
    defPct,
    agiPct,
    classMultiplier,
    treeDefence,
    damageTaken,
    ehp: hp / (AGILITY_DAMAGE_TAKEN * agiPct + (1 - agiPct) * (1 - defPct)) / damageTaken,
    // "Effective Health" z menu Combat Information w grze: HP ÷ (1 − Defence%) ÷ (1 − Agility%) z surowej krzywej
    // Skill Pointów, bez mnożnika klasy (sprawdzone na zrzucie z gry: 2,825 HP → 2,882).
    ehpGame: hp / ((1 - skillPercent(statValue(stats, "def"))) * (1 - skillPercent(statValue(stats, "agi")))),
    ehpNoAgi: hp / ((1 - defPct) * damageTaken),
    hpr: hprRaw < 0 ? Math.min(0, hprRaw - hprRaw * hprPct) : hprRaw + hprRaw * hprPct,
    lifeSteal: statValue(stats, "ls"),
    manaRegen: statValue(stats, "mr"),
    manaSteal: statValue(stats, "ms"),
    walkSpeed: statValue(stats, "spd"),
    maxMana: statValue(stats, "maxMana"),
    intPct: skillPercent(statValue(stats, "int")),
    meleeRange: {
      base: (scaled.edited.get(MELEE_ABILITY_ID) || { props: {} }).props.range || 0,
      pct: statValue(stats, "mainAttackRange"),
    },
    treeAdded: scaled.added,
  });
  return result;
}

function SummaryRow({ label, value, hint, color }) {
  return (
    <li className="flex items-baseline justify-between gap-3" title={hint}>
      <span className="text-zinc-300">{label}</span>
      <span className="tabular-nums font-semibold" style={ts({ color: color || "#F4F4F5" })}>
        {value}
      </span>
    </li>
  );
}

function formatAmount(value) {
  if (!Number.isFinite(value)) return "—";
  return formatNumber(Math.round(value));
}

function spellPartsHint(spell) {
  return spell.parts
    .filter((part) => part.display && part.type)
    .map((part) => `${part.name}: ${formatAmount(part.amount)}${part.type === "heal" ? " HP" : ""}`)
    .join("\n");
}

// ROZPISKI JAK W WYNNBUILDERZE: każda część czaru z mnożnikami per żywioł, średnią, zakresem bez crita i z critem.
const ELEMENT_BY_PREFIX = { n: "neutral", e: "earth", t: "thunder", w: "water", f: "fire", a: "air" };

function ElementAmount({ index, min, max }) {
  const style = ELEMENT_STYLE[ELEMENT_BY_PREFIX[DAMAGE_PREFIXES[index]]];
  // Raw jest rozdzielany proporcjonalnie do udziału żywiołu w minimum i w maksimum osobno, więc "min" żywiołu bywa
  // większe od jego "max" (tak samo w Wynnbuilderze); pokazujemy od mniejszej do większej.
  const [low, high] = min <= max ? [min, max] : [max, min];
  return (
    <span className="tabular-nums" style={ts({ color: style.color })}>
      {style.symbol} {formatNumber(Math.round(low))} – {formatNumber(Math.round(high))}
    </span>
  );
}

function MultiplierLine({ part }) {
  const total = part.multipliers.reduce((sum, value) => sum + value, 0);
  return (
    <span className="flex flex-wrap items-baseline gap-x-2 text-xs">
      {part.multipliers.map((value, index) =>
        value > 0 ? (
          <span key={index} style={ts({ color: ELEMENT_STYLE[ELEMENT_BY_PREFIX[DAMAGE_PREFIXES[index]]].color })}>
            {ELEMENT_STYLE[ELEMENT_BY_PREFIX[DAMAGE_PREFIXES[index]]].symbol} {Math.round(value * 10) / 10}%
          </span>
        ) : null
      )}
      <span className="text-zinc-500">({Math.round(total * 10) / 10}%)</span>
      <span className="text-zinc-400">{part.useSpell === false ? "Melee" : "Spell"}</span>
    </span>
  );
}

function PartBreakdown({ part, critChance }) {
  if (part.type === "heal") {
    return (
      <li className="flex flex-col gap-0.5">
        <span className="text-zinc-200">{part.name}</span>
        <span className="tabular-nums" style={ts({ color: "#55FF55" })}>
          Heal: {formatNumber(Math.round(part.amount))} HP
        </span>
      </li>
    );
  }
  const ranges = (min, max) => part.normalMax.map((_, index) => (max[index] > 0 ? <ElementAmount key={index} index={index} min={min[index]} max={max[index]} /> : null));
  return (
    <li className="flex flex-col gap-0.5">
      <span className="text-zinc-200">{part.name}</span>
      <MultiplierLine part={part} />
      <span className="tabular-nums text-zinc-300">
        Average: <span className="text-white">{formatNumber(Math.round(part.amount))}</span>
        <span className="text-xs text-zinc-500"> ({Math.round(critChance * 100)}% crit)</span>
      </span>
      <span className="tabular-nums text-zinc-400">Non-crit: {formatNumber(Math.round(part.normal))}</span>
      <span className="flex flex-wrap gap-x-3 pl-3 text-xs">{ranges(part.normalMin, part.normalMax)}</span>
      <span className="tabular-nums text-zinc-400">Crit: {formatNumber(Math.round(part.crit))}</span>
      <span className="flex flex-wrap gap-x-3 pl-3 text-xs">{ranges(part.critMin, part.critMax)}</span>
    </li>
  );
}

// Karta czaru / main attacku: nagłówek z wynikiem, po rozwinięciu wszystkie części.
function SpellCard({ spell, critChance, mainAttack, open, onToggle }) {
  const main = spell.main;
  const heal = main && main.type === "heal";
  const parts = spell.parts.filter((part) => part.display && part.type && (part.type === "heal" || part.amount !== 0 || part.multipliers.some((value) => value !== 0)));
  return (
    <li className="mc-slot flex flex-col gap-1 px-3 py-2">
      <button type="button" onClick={onToggle} aria-expanded={open} className="flex w-full items-baseline justify-between gap-3 text-left">
        <span className="min-w-0 text-zinc-100">
          {spell.name}
          {spell.cost !== null && (
            <span className="ml-2 text-xs" style={ts({ color: "#55FFFF" })}>
              ({spell.cost.toFixed(1)} mana)
            </span>
          )}
          {spell.manaGained > 0 && (
            <span className="ml-2 text-xs" style={ts({ color: "#55FFFF" })}>
              +{formatNumber(spell.manaGained)} mana back
            </span>
          )}
        </span>
        <span className="shrink-0 tabular-nums" style={ts({ color: heal ? "#55FF55" : "#FFAA00" })}>
          {mainAttack
            ? `${formatNumber(Math.round(mainAttack.dps))} DPS`
            : main
              ? `${formatNumber(Math.round(main.amount))}${heal ? " HP" : ""}`
              : "utility"}
          <span className="ml-2 text-xs text-zinc-500">{open ? "▴" : "▾"}</span>
        </span>
      </button>
      {mainAttack && (
        <span className="text-xs text-zinc-400">
          Attack speed <span className="text-zinc-200">{ATTACK_SPEED_LABELS[mainAttack.speed]}</span> ({mainAttack.hps}/s) · per attack{" "}
          <span className="text-zinc-200">{formatNumber(Math.round(mainAttack.hit))}</span>
        </span>
      )}
      {!mainAttack && main && main.type === "damage" && (
        <span className="text-xs text-zinc-400">
          {main.name}: non-crit {formatNumber(Math.round(main.normal))} · crit {formatNumber(Math.round(main.crit))}
          {spell.dps && (
            <>
              {" "}
              · <span style={ts({ color: "#55FFFF" })}>Spell DPS {formatNumber(Math.round(spell.dps.sustained))}</span>
              <span className="text-zinc-500">
                {" "}
                sustained ({spell.dps.castsPerSecond.toFixed(2)} casts/s) · spam {formatNumber(Math.round(spell.dps.spam))}
              </span>
            </>
          )}
        </span>
      )}
      {open && (
        <ul className="mc-hr mt-1 flex flex-col gap-3 pt-2 text-sm">
          {parts.length === 0 ? <li className="text-xs text-zinc-500">No damage or healing parts.</li> : parts.map((part) => <PartBreakdown key={part.name} part={part} critChance={critChance} />)}
        </ul>
      )}
    </li>
  );
}

// Kalkulator cyklu czarów: np. "1213" albo "4MMM" przy 9 kliknięciach/s (czar = 3 kliknięcia, M = main attack, nie
// szybciej niż pozwala broń). Mana Steal tylko z trafień M - ten sam model co generator (cycleTiming, stealPerSecond).
// CZASY CZARÓW (feedback: "Multihit says total damage but it's dealt over a duration"). Z danych drzewka (props węzła,
// który daje czar - wartości bazowe, przed ulepszeniami): ile trwa zadawanie obrażeń. Przerywanie przy ponownym rzucie
// znamy tylko z relacji graczy, bez czasów - dlatego generator liczy obrażenia rzutu, a cel "Whole cycle" sumuje cały
// cykl na sekundę (kompromis zaproponowany przez graczy).
const RECAST_NOTES = {
  Multihit: "players report that recasting before the last hit cuts it short for Acrobat (not for Trickster)",
  Uppercut: "players report that with Fireworks, recasting Uppercut early cuts the fireworks short",
};
function spellTimings(playerClass, active) {
  const tree = TREE_INDEX[playerClass];
  const out = new Map();
  if (!tree || !active) return out;
  tree.nodes.forEach((node) => {
    if (!active.has(node.id)) return;
    (node.effects || []).forEach((effect) => {
      if (effect.type !== "replace_spell" || effect.base_spell === undefined) return;
      const props = node.props || {};
      let timing = null;
      if (props.arrows_per_stream && props.attack_frequency) timing = { over: props.arrows_per_stream / props.attack_frequency, text: `${props.arrows_per_stream} arrows over ${(props.arrows_per_stream / props.attack_frequency).toFixed(1)} s` };
      else if (props.ray_duration) timing = { over: props.ray_duration, text: `beam for ${props.ray_duration} s` };
      else if (props.duration && (props.rate || props.ticksPerSecond || props.hitsPerSecond || props.attack_frequency)) {
        const perSecond = props.ticksPerSecond || props.hitsPerSecond || props.attack_frequency || 1 / props.rate;
        timing = { over: props.duration, text: `${props.duration} s, ${perSecond.toFixed(1)} hits/s` };
      } else if (props.hit_count) timing = { over: null, text: `${props.hit_count} quick hits` };
      else if (props.duration) timing = { over: null, text: `effect lasts ${props.duration} s` };
      out.set(effect.base_spell, { ...(timing || { over: 0, text: "instant" }), note: RECAST_NOTES[node.name] || RECAST_NOTES[effect.name] || null, node: node.name });
    });
  });
  return out;
}

function SpellTimingTable({ stats, playerClass }) {
  const timings = spellTimings(playerClass, stats.tree && stats.tree.active);
  const rows = stats.spells.filter((spell) => spell.main && (spell.main.type === "damage" || spell.main.type === "heal"));
  if (rows.length === 0) return null;
  return (
    <details className="text-xs">
      <summary className="mc-link cursor-pointer">Spell timing</summary>
      <p className="mt-1 text-zinc-500">Damage per cast is the total of all its hits; spells below deal it over time. Base values from the ability tree data (before upgrades).</p>
      <div className="mt-1 grid gap-x-2 gap-y-0.5" style={{ gridTemplateColumns: "minmax(0,1fr) auto auto" }}>
        <span className="text-zinc-500">spell</span>
        <span className="text-right text-zinc-500">per cast</span>
        <span className="text-right text-zinc-500">dealt over</span>
        {rows.map((spell) => {
          const timing = timings.get(spell.id) || null;
          return (
            <React.Fragment key={spell.id}>
              <span className="truncate text-zinc-200" title={timing && timing.note ? `${spell.name}: ${timing.note}` : spell.name}>
                {spell.name}
                {timing && timing.note ? " *" : ""}
              </span>
              <span className="text-right tabular-nums">{formatAmount(spell.main.amount)}</span>
              <span className="text-right text-zinc-400">{timing ? timing.text : "instant"}</span>
            </React.Fragment>
          );
        })}
      </div>
      {rows.some((spell) => (timings.get(spell.id) || {}).note) && <p className="mt-1 text-zinc-500">* {rows.map((spell) => (timings.get(spell.id) || {}).note && `${spell.name}: ${timings.get(spell.id).note}`).filter(Boolean).join("; ")}.</p>}
    </details>
  );
}

function SpellCyclePanel({ stats, build = null }) {
  const initialCycle = build && build.metrics && build.metrics.cycle && build.metrics.cycle.ids ? cycleText(build.metrics.cycle.ids) : "";
  const [cycle, setCycle] = useState(initialCycle);
  const [clicks, setClicks] = useState(build && build.metrics && build.metrics.cycle && initialCycle ? String(build.metrics.cycle.cps) : "9");
  const [withSteal, setWithSteal] = useState(true);
  const [withGain, setWithGain] = useState(true);
  const ids = parseCycle(cycle);
  const spellIds = ids.filter((id) => id !== 0);
  const spells = spellIds.map((id) => stats.spells.find((spell) => spell.id === id)).filter((spell) => spell && spell.cost !== null);
  const valid = ids.length > 0 && spells.length === spellIds.length;
  const cps = Math.max(0.1, Number(clicks) || 9);
  const hps = stats.mainAttack ? stats.mainAttack.hps : HITS_PER_SECOND.NORMAL;
  const timing = cycleTiming(ids, cps, hps);
  const seconds = Math.max(0.01, timing.seconds);
  const used = valid ? spells.reduce((sum, spell) => sum + spell.cost, 0) / seconds : null;
  const steal = withSteal ? stealPerSecond(stats.manaSteal, timing, hps) : 0;
  const fromStats = (stats.manaRegen + 25) / 5 + steal;
  const fromAbilities = valid && withGain ? spells.reduce((sum, spell) => sum + (spell.manaGained || 0), 0) / seconds : 0;
  const net = used === null ? null : fromStats + fromAbilities - used;
  const meleeDamage = timing.melee * (stats.mainAttack ? stats.mainAttack.hit : 0);
  const cycleDamage = valid ? spells.reduce((sum, spell) => sum + (spell.main && spell.main.type === "damage" ? spell.main.amount : 0), 0) + meleeDamage : 0;
  const cycleDps = valid ? cycleDamage / seconds : null;
  const sustainedDps = cycleDps === null ? null : used > 0 ? cycleDps * Math.min(1, (fromStats + fromAbilities) / used) : cycleDps;
  const format = (value) => (value === null ? "–" : `${value >= 0 ? "" : "−"}${Math.abs(value).toFixed(1)}`);
  return (
    <div className="mc-slot flex flex-col gap-2 p-3">
      <span className="mc-title text-xs uppercase">Spell cycle</span>
      <div className="grid grid-cols-2 gap-2">
        <label className="flex flex-col gap-1 text-xs text-zinc-300">
          Cycle (1-4 = spells, M = main attack)
          <input value={cycle} onChange={(event) => setCycle(event.target.value.toUpperCase().replace(/[^1-4M]/g, "").slice(0, 16))} placeholder="e.g. 1213 or 4MMM" className="mc-input w-full" />
        </label>
        <label className="flex flex-col gap-1 text-xs text-zinc-300">
          Clicks per second
          <input value={clicks} onChange={(event) => setClicks(event.target.value)} type="number" min={1} max={20} step={0.5} className="mc-input w-full" />
        </label>
      </div>
      <label className="flex items-center gap-2 text-xs text-zinc-200" title="Mana Steal works on main attack hits: Mana per hit = Mana Steal ÷ 3 ÷ hits per second">
        <input type="checkbox" className="mc-check" checked={withSteal} onChange={() => setWithSteal(!withSteal)} /> Include Mana Steal ({formatNumber(stats.manaSteal)}/3s, {(stats.manaSteal / 3 / hps).toFixed(1)} per hit)
      </label>
      <label className="flex items-center gap-2 text-xs text-zinc-200">
        <input type="checkbox" className="mc-check" checked={withGain} onChange={() => setWithGain(!withGain)} /> Include ability mana gain
      </label>
      <ul className="flex flex-col gap-0.5 text-sm">
        <SummaryRow label="Mana used/s" value={format(used)} color="#FF5555" hint={valid ? `${spells.map((spell) => `${spell.name} ${spell.cost.toFixed(1)}`).join(" + ")} over ${seconds.toFixed(2)} s` : "Type a cycle of spells you have in the ability tree"} />
        <SummaryRow label="Mana/s from stats" value={format(fromStats)} color="#55FFFF" hint={`(Mana Regen + 25 base) ÷ 5 s${withSteal ? `, plus Mana Steal ${steal.toFixed(1)}/s from ${timing.melee} main attack hit${timing.melee === 1 ? "" : "s"} per cycle` : ""}`} />
        <SummaryRow label="Mana/s from abilities" value={format(fromAbilities)} color="#55FFFF" />
        <SummaryRow label="Net mana/s" value={format(net)} color={net === null ? "#F4F4F5" : net >= 0 ? "#55FF55" : "#FF5555"} hint={net !== null && net < 0 ? `A 100-mana pool lasts about ${Math.round(100 / -net)} s` : undefined} />
        <SummaryRow label="Cycle damage" value={valid ? formatNumber(Math.round(cycleDamage)) : "–"} hint="Sum of every spell's damage (and main attack hits) in one cycle" />
        <SummaryRow label="Cycle DPS" value={cycleDps === null ? "–" : formatNumber(Math.round(cycleDps))} color="#55FFFF" hint={valid ? `${formatNumber(Math.round(cycleDamage))} damage over ${seconds.toFixed(2)} s` : ""} />
        <SummaryRow label="➜ Sustained by mana" value={sustainedDps === null ? "–" : formatNumber(Math.round(sustainedDps))} color="#55FFFF" hint="Cycle DPS scaled down when mana income can't keep up with mana used" />
      </ul>
      {ids.length > 0 && !valid && <p className="text-xs text-amber-300">Every spell in the cycle needs a cost: pick its abilities in the Ability tree tab.</p>}
      {ids.length > 0 && timing.melee === 0 && withSteal && stats.manaSteal > 0 && <p className="text-xs text-zinc-500">No M in the cycle, so Mana Steal adds nothing.</p>}
      {build && <SpellTimingTable stats={stats} playerClass={build.playerClass} />}
    </div>
  );
}

function PowderSpecialRow({ special }) {
  const color = ELEMENT_STYLE[special.element].color;
  const label = `${special.name} ${special.level % 1 ? special.level.toFixed(1) : special.level}`;
  let value = "";
  if (special.damage) value = formatAmount(special.damage);
  else if (special.nextHit) value = `+${special.nextHit}% next hit`;
  else if (special.boost) value = `+${special.boost}% taken`;
  const parts = [
    special.damage ? `${special.percent}% of your weapon's damage as ${ELEMENT_STYLE[special.element].label} (main attack scaling, crits included): ${formatAmount(special.damage)} per enemy hit` : null,
    special.extra ? `${special.extra.name} ${special.extra.value}${special.extra.unit}` : null,
    special.boost && special.element === "fire" ? `+${special.boost}% damage for you and allies for ${special.duration} s` : null,
    special.boost && special.element === "water" ? `enemies take ${special.boost}% more damage for ${special.duration} s` : null,
    special.nextHit ? `holds enemies for ${special.duration} s; the next hit deals ${special.nextHit}% more` : null,
  ].filter(Boolean);
  return (
    <SummaryRow
      label={`Powder special: ${label}`}
      value={value}
      color={color}
      hint={`${parts.join("; ")}. Two tier IV+ ${ELEMENT_STYLE[special.element].label} powders unlock it (the first powder decides; level = their average tier). Charged by main attacks (about 5 s of hitting), used with Shift + click. Shown for reference - the generator does not count it.`}
    />
  );
}

function DamagePanel({ build, stats, onOpenTree }) {
  const { mainAttack, tree } = stats;
  const treeNodes = tree.activeCount;
  const [open, setOpen] = useState({});
  const [cycleOpen, setCycleOpen] = useState(false);
  const toggle = (id) => setOpen((current) => ({ ...current, [id]: !current[id] }));
  const hps = mainAttack ? mainAttack.hps : HITS_PER_SECOND.NORMAL;
  const totalMana = 100 + stats.maxMana + Math.floor(stats.intPct * 100);
  return (
    <section className="mc-panel flex flex-col gap-3 p-4">
      <div className="flex items-center justify-between gap-2">
        <h3 className="mc-title text-sm uppercase">Damage</h3>
        <span className="text-xs text-zinc-500">expected, with crits</span>
      </div>
      {mainAttack ? (
        <>
          <ul className="flex flex-col gap-1 font-mono text-sm">
            <SummaryRow label="Main attack DPS" value={formatAmount(mainAttack.dps)} color="#FFAA00" hint={`${mainAttack.name}: ${formatAmount(mainAttack.hit)} per attack × ${mainAttack.hps} attacks/s`} />
            {stats.spellDps ? (
              <>
                <SummaryRow
                  label="Spell DPS"
                  value={formatAmount(stats.spellDps.sustained)}
                  color="#55FFFF"
                  hint={`${stats.spellDps.name} cast ${stats.spellDps.castsPerSecond.toFixed(2)}× per second, as much as your mana sustains ((Mana Regen + 25)/5 per second plus the spell's own mana gain)`}
                />
                <SummaryRow
                  label="➜ Spell DPS (spam)"
                  value={formatAmount(stats.spellDps.spam)}
                  hint={`${stats.spellDps.name} cast 3× per second (${SPELL_CLICKS_PER_SECOND} clicks/s), ignoring mana`}
                />
              </>
            ) : (
              <SummaryRow label="Spell DPS" value="–" color="#55FFFF" hint="Pick abilities in the Ability tree tab: spell damage and costs come from the tree" />
            )}
            {stats.poison && stats.poison.dps > 0 && (
              <SummaryRow
                label="Poison DPS"
                value={formatAmount(stats.poison.dps)}
                color="#AA00AA"
                hint={`Poison ${formatNumber(stats.poison.total)} per 3 s = one tick of ${formatNumber(stats.poison.dps)} every second after you hit (floor(poison ÷ 3), as in Wynnbuilder). Not affected by Strength, crits or damage bonuses. Counted in the damage goal only with "Count poison in the goal" (added to main attack DPS, or spread over casts for a spell).`}
              />
            )}
            {stats.powderSpecial && <PowderSpecialRow special={stats.powderSpecial} />}
          </ul>
          {stats.hundred && (
            <div className="grid grid-cols-1 gap-2">
              {[
                ["spell", "[100%] Spell Damage", "#FF55FF"],
                ["melee", "[100%] Main Attack Damage", "#FFAA00"],
              ].map(([kind, label, color]) => (
                <div key={kind} className="mc-slot flex flex-col gap-0.5 px-3 py-2 text-xs">
                  <span style={ts({ color })}>{label}</span>
                  {stats.hundred[kind].ranges.map(([min, max], index) =>
                    max > 0 ? (
                      <span key={index} className="flex justify-between gap-2">
                        <span style={ts({ color: ELEMENT_STYLE[ELEMENT_BY_PREFIX[DAMAGE_PREFIXES[index]]].color })}>
                          {ELEMENT_STYLE[ELEMENT_BY_PREFIX[DAMAGE_PREFIXES[index]]].symbol} {ELEMENT_STYLE[ELEMENT_BY_PREFIX[DAMAGE_PREFIXES[index]]].label} Damage
                        </span>
                        <span className="tabular-nums text-zinc-100">
                          {formatNumber(Math.round(Math.min(min, max)))}–{formatNumber(Math.round(Math.max(min, max)))}
                        </span>
                      </span>
                    ) : null
                  )}
                  <span className="text-zinc-500">({(stats.hundred[kind].buff * 100).toFixed(2)}% overall buff from loadout)</span>
                </div>
              ))}
            </div>
          )}
          <ul className="flex flex-col gap-2 text-sm">
            {stats.melee && <SpellCard spell={stats.melee} critChance={stats.critChance} mainAttack={mainAttack} open={Boolean(open.melee)} onToggle={() => toggle("melee")} />}
            {stats.spells.map((spell) => (
              <SpellCard key={spell.id} spell={spell} critChance={stats.critChance} open={Boolean(open[spell.id])} onToggle={() => toggle(spell.id)} />
            ))}
          </ul>
          <ul className="flex flex-col gap-1 font-mono text-sm">
            <SummaryRow
              label={stats.weapon.powders ? `Weapon DPS (${powderLabel(stats.weapon.powders)})` : "Weapon base DPS"}
              value={formatNumber(stats.weapon.dps || 0)}
              hint={
                stats.weapon.powders
                  ? `The weapon's tooltip DPS with its powders: average damage × hits per second, before any bonuses. Without powders: ${formatNumber(stats.weapon.baseWeapon.dps || 0)}.`
                  : "The number on the weapon's tooltip: average base damage × hits per second, before any bonuses."
              }
            />
            {stats.spells.length === 0 && (
              <SummaryRow
                label="Spell hit (100% spell)"
                value={formatAmount(stats.spellHit)}
                hint="A spell part with a 100% multiplier. Pick abilities in the Ability tree tab to see your real spells."
              />
            )}
            <SummaryRow label="Crit chance (Dexterity)" value={`${Math.round(stats.critChance * 100)}%`} />
            <SummaryRow label="Strength damage bonus" value={`+${Math.round((stats.strBoost - 1) * 100)}%`} />
          </ul>
          <ul className="mc-hr flex flex-col gap-1 pt-2 font-mono text-sm">
            <SummaryRow label="Mana Regen" value={`${formatNumber(stats.manaRegen)}/5s`} color={stats.manaRegen >= 0 ? "#55FFFF" : "#FF5555"} />
            <SummaryRow label="➜ Total with base" value={`${formatNumber(stats.manaRegen + 25)}/5s`} hint="Every class regenerates 25 mana per 5 s on top of the identification" />
            <SummaryRow label="Mana Steal" value={`${formatNumber(stats.manaSteal)}/3s`} color={stats.manaSteal >= 0 ? "#55FFFF" : "#FF5555"} />
            <SummaryRow label="➜ Mana per hit" value={(stats.manaSteal / 3 / hps).toFixed(1)} hint={`Mana Steal ÷ 3 s ÷ ${hps} attacks per second`} />
            <SummaryRow label="Max Mana" value={`${stats.maxMana >= 0 ? "+" : ""}${formatNumber(stats.maxMana)}`} color={stats.maxMana >= 0 ? "#55FFFF" : "#FF5555"} />
            <SummaryRow label="➜ Total Mana" value={formatNumber(totalMana)} hint={`100 base + ${formatNumber(stats.maxMana)} from items + ${Math.floor(stats.intPct * 100)} from Intelligence`} />
          </ul>
          <button type="button" onClick={() => setCycleOpen(!cycleOpen)} className="mc-link self-start text-xs" aria-expanded={cycleOpen}>
            {cycleOpen ? "▾" : "▸"} Spell cycle calculator
          </button>
          {cycleOpen && (
            <div className="wbr-drop">
              <SpellCyclePanel stats={stats} build={build} />
            </div>
          )}
        </>
      ) : (
        <p className="text-sm text-zinc-500">No weapon in this build.</p>
      )}
      <p
        className="text-xs text-zinc-500"
        title={`Item stats, current skill points${build.skillPoints.remaining > 0 ? ` (${build.skillPoints.remaining} free points not assigned)` : ""} and ${treeNodes > 0 ? `${treeNodes} ability tree node${treeNodes === 1 ? "" : "s"} (${tree.points} AP)` : "no ability tree nodes"}. ${stats.weapon && stats.weapon.powders ? `Weapon powders: ${powderLabel(stats.weapon.powders)}; no armour powders or tomes.` : "No powders or tomes."}`}
      >
        {treeNodes > 0 ? (
          `With ${treeNodes} tree node${treeNodes === 1 ? "" : "s"}.`
        ) : (
          <>
            No tree nodes
            {onOpenTree && (
              <>
                {" "}
                (
                <button type="button" onClick={onOpenTree} className="mc-link">
                  pick
                </button>
                )
              </>
            )}
            .
          </>
        )}
      </p>
    </section>
  );
}

function SurvivabilityPanel({ build, stats }) {
  const defences = elementalDefences(build);
  const treeReduction = stats.treeDefence < 1 ? ` · tree ×${stats.treeDefence.toFixed(2)}` : "";
  return (
    <section className="mc-panel flex flex-col gap-3 p-4">
      <div className="flex items-center justify-between gap-2">
        <h3 className="mc-title text-sm uppercase">Survivability</h3>
        <span className="text-xs text-zinc-500" title={`Class ×${stats.classMultiplier.toFixed(1)}${treeReduction}`}>
          takes ×{stats.damageTaken.toFixed(2)} damage
        </span>
      </div>
      <ul className="flex flex-col gap-1 font-mono text-sm">
        <SummaryRow
          label="Effective Health (game)"
          value={formatAmount(stats.ehpGame)}
          color="#55FF55"
          hint="As on the in-game Combat Information screen: Health ÷ (1 − Defence %) ÷ (1 − Agility %), no class multiplier"
        />
        <SummaryRow
          label="Effective HP (Wynnbuilder)"
          value={formatAmount(stats.ehp)}
          hint="HP after Defence, Agility (90% less damage on a dodge), the class damage multiplier and ability tree damage reductions"
        />
        <SummaryRow label="➜ without Agility" value={formatAmount(stats.ehpNoAgi)} />
        <SummaryRow label="Health" value={formatNumber(stats.hp)} hint={`${5 * build.level + 5} from level ${build.level} + items + ability tree`} />
        <SummaryRow label="Defence reduction" value={`${Math.round(stats.defPct * 100)}%`} hint="From Defence skill points" />
        <SummaryRow label="Agility dodge" value={`${Math.round(stats.agiPct * 100)}%`} hint="Chance to take only 10% damage, from Agility skill points" />
        {stats.treeDefence < 1 && (
          <SummaryRow label="Ability tree resistance" value={`${Math.round((1 - stats.treeDefence) * 100)}%`} hint={Object.keys(stats.stats.defMult).join(", ")} />
        )}
        <SummaryRow label="Health Regen (final)" value={`${formatAmount(stats.hpr)}/4s`} color={stats.hpr >= 0 ? "#F4F4F5" : "#FF5555"} hint="Raw regen × (1 + Health Regen %)" />
        <SummaryRow label="Life Steal" value={`${formatNumber(stats.lifeSteal)}/3s`} color={stats.lifeSteal >= 0 ? "#F4F4F5" : "#FF5555"} />
        <SummaryRow label="➜ Effective LS" value={`${formatNumber(Math.round((stats.ehp / stats.hp) * stats.lifeSteal))}/3s`} hint="Life Steal scaled by Effective HP ÷ Health" />
        <SummaryRow label="➜ Life per hit" value={formatNumber(Math.round(stats.lifeSteal / 3 / (stats.mainAttack ? stats.mainAttack.hps : HITS_PER_SECOND.NORMAL)))} hint="Life Steal ÷ 3 s ÷ attacks per second" />
        {(() => {
          // Efektywny przyrost zdrowia na sekundę: (Health Regen ÷ 4 s + Life Steal z trafień) × EHP ÷ HP. Life Steal
          // jak Mana Steal: z cyklem tylko z jego M, bez cyklu przy ciągłym biciu main attackiem.
          const hps = stats.mainAttack ? stats.mainAttack.hps : HITS_PER_SECOND.NORMAL;
          const cycle = build.metrics && build.metrics.cycle && build.metrics.cycle.ids && build.metrics.cycle.ids.length > 0 ? build.metrics.cycle : null;
          const timing = cycle ? cycleTiming(cycle.ids, cycle.cps, hps) : null;
          const steal = timing ? stealPerSecond(stats.lifeSteal, timing, hps) : stats.lifeSteal / 3;
          const raw = stats.hpr / 4 + steal;
          const effective = (raw * stats.ehp) / Math.max(1, stats.hp);
          return (
            <SummaryRow
              label="Effective health gain"
              value={`${effective >= 0 ? "+" : "−"}${formatNumber(Math.round(Math.abs(effective)))}/s`}
              color={effective > 0 ? "#55FF55" : effective < 0 ? "#FF5555" : "#F4F4F5"}
              hint={`(Health Regen ${formatAmount(stats.hpr)} ÷ 4 s + Life Steal ${steal.toFixed(1)}/s${cycle ? ` from the ${timing.melee} main attack${timing.melee === 1 ? "" : "s"} of cycle ${cycleText(cycle.ids)}` : " at constant main attacks"}) × EHP ÷ Health (${(stats.ehp / Math.max(1, stats.hp)).toFixed(2)}) = ${raw.toFixed(1)} HP/s worth ${effective.toFixed(1)} effective HP/s`}
            />
          );
        })()}
        <SummaryRow label="Walk Speed" value={`${stats.walkSpeed >= 0 ? "+" : ""}${formatNumber(stats.walkSpeed)}%`} color={stats.walkSpeed >= 0 ? "#F4F4F5" : "#FF5555"} />
        {stats.meleeRange.base > 0 && (
          <>
            <SummaryRow label="Main Attack Range" value={`${stats.meleeRange.pct >= 0 ? "+" : ""}${formatNumber(stats.meleeRange.pct)}%`} />
            <SummaryRow label="➜ Total range" value={`${Math.round(stats.meleeRange.base * (1 + stats.meleeRange.pct / 100) * 10) / 10} blocks`} hint={`${stats.meleeRange.base} blocks base for ${build.playerClass} × (1 + range %)`} />
          </>
        )}
      </ul>
      <div className="mc-hr flex flex-col gap-1 pt-3">
        <h4 className="mc-title text-xs uppercase">Elemental defences</h4>
        <ul className="flex flex-col gap-1 font-mono text-sm">
          {defences.map(({ element, raw, pct, effective }) => (
            <li
              key={element}
              className="flex items-baseline justify-between gap-3"
              title={`${formatNumber(raw)} from items${pct ? `, ${pct > 0 ? "+" : ""}${pct}% from identifications` : ""}`}
            >
              <span style={ts({ color: ELEMENT_STYLE[element].color })}>
                {ELEMENT_STYLE[element].symbol} {ELEMENT_STYLE[element].label}
              </span>
              <span className="flex items-baseline gap-2">
                {pct !== 0 && (
                  <span className="text-xs tabular-nums text-zinc-500">
                    {pct > 0 ? "+" : ""}
                    {pct}%
                  </span>
                )}
                <span className="tabular-nums font-semibold" style={ts({ color: effective >= 0 ? "#55FF55" : "#FF5555" })}>
                  {effective > 0 ? "+" : ""}
                  {formatNumber(effective)}
                </span>
              </span>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}

// Stałe bonusy drzewka do wyświetlenia (np. "+20% Earth Damage", "Heavy Impact +10% damage").
const TREE_STAT_LABELS = {
  spd: ["Walk Speed", "%"],
  mr: ["Mana Regen", "/5s"],
  jh: ["Jump Height", ""],
  hpBonus: ["Health", ""],
  sdPct: ["Spell Damage", "%"],
  damRaw: ["Damage", ""],
  poison: ["Poison", "/3s"],
  mainAttackRange: ["Main Attack Range", "%"],
};
function treePassiveBonuses(merged) {
  const totals = {};
  merged.forEach((ability) => {
    ability.effects.forEach((effect) => {
      if (effect.type !== "raw_stat" || effect.toggle) return;
      (effect.bonuses || []).forEach((bonus) => {
        if (bonus.type === "stat" && typeof bonus.value === "number") mergeStat(totals, bonus.name, bonus.value);
      });
    });
  });
  const lines = [];
  ELEMENTS.forEach((element) => {
    const prefix = element.charAt(0);
    const pct = totals[`${prefix}DamPct`] || 0;
    const min = totals[`${prefix}DamAddMin`] || 0;
    const max = totals[`${prefix}DamAddMax`] || 0;
    if (pct || min || max) {
      lines.push({
        key: element,
        color: ELEMENT_STYLE[element].color,
        text: `${ELEMENT_STYLE[element].label}${pct ? ` +${pct}%` : ""}${min || max ? ` +${min}-${max} dmg` : ""}`,
      });
    }
  });
  Object.entries(TREE_STAT_LABELS).forEach(([key, [label, unit]]) => {
    if (totals[key]) lines.push({ key, text: `${label} ${totals[key] > 0 ? "+" : ""}${formatNumber(totals[key])}${unit}` });
  });
  MULTIPLIER_MAPS.forEach((map) => {
    Object.entries(totals[map] || {}).forEach(([name, value]) => {
      const what = { damMult: "damage", defMult: "resistance", healMult: "healing", manaMult: "mana" }[map];
      const [label] = name.split(/[:;]/);
      const part = name.includes(":") ? name.split(":")[1].split(".").slice(1).join(".") : "";
      const element = name.includes(";") ? name.split(";")[1] : "";
      const scope = part || (element === "m" ? "main attack" : ELEMENT_ID_PREFIXES[element] || "");
      lines.push({ key: `${map}.${name}`, text: `${label} ${value > 0 ? "+" : ""}${formatNumber(value)}% ${what}${scope ? ` (${scope})` : ""}` });
    });
  });
  return lines;
}

// Przełączniki i suwaki aktywnych zdolności (np. Corrupted, Mask of the Lunatic) + stałe bonusy drzewka.
function TreeEffectsPanel({ playerClass, state, settings, onChange, onOpenTree }) {
  const toggles = [...state.interactives.toggles.values()];
  const sliders = [...state.interactives.sliders.values()];
  const passive = useMemo(() => treePassiveBonuses(state.merged), [state.merged]);
  const current = settings || { toggles: {}, sliders: {} };
  const changed = Object.keys(current.toggles || {}).length > 0 || Object.keys(current.sliders || {}).length > 0;
  // Aktualizacje funkcyjne: kilka kliknięć pod rząd nie nadpisuje się nawzajem.
  const setToggle = (name) =>
    onChange((previous = {}) => ({ ...previous, toggles: { ...(previous.toggles || {}), [name]: !(previous.toggles || {})[name] } }));
  const setSlider = (name, value) => onChange((previous = {}) => ({ ...previous, sliders: { ...(previous.sliders || {}), [name]: value } }));
  return (
    <section className="mc-panel flex flex-col gap-3 p-4">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <h3 className="mc-title text-sm uppercase">Ability tree effects</h3>
        <span className="flex items-center gap-3 text-xs text-zinc-500">
          {state.active.size > 0 ? `${state.active.size} abilities · ${state.points} AP` : `no ${playerClass} abilities picked`}
          {changed && (
            <button type="button" onClick={() => onChange({ toggles: {}, sliders: {} })} className="mc-link">
              Reset
            </button>
          )}
          {onOpenTree && (
            <button type="button" onClick={onOpenTree} className="mc-link">
              Edit tree
            </button>
          )}
        </span>
      </div>
      {state.active.size === 0 ? (
        <p className="text-sm text-zinc-400">
          Pick nodes in the Ability tree tab: their stat bonuses, damage multipliers, resistances and spells go straight into Damage and
          Survivability above.
        </p>
      ) : (
        <>
          {passive.length > 0 && (
            <div className="flex flex-col gap-1">
              <span className="text-xs text-zinc-400">Always on</span>
              <div className="flex flex-wrap gap-x-3 gap-y-1 font-mono text-xs">
                {passive.map((line) => (
                  <span key={line.key} style={ts({ color: line.color || "#D4D4D8" })}>
                    {line.text}
                  </span>
                ))}
              </div>
            </div>
          )}
          {toggles.length > 0 && (
            <div className="flex flex-col gap-2">
              <span className="text-xs text-zinc-400">Toggles (buffs you can have active)</span>
              <div className="flex flex-wrap gap-2">
                {toggles.map((toggle) => (
                  <ToggleChip key={toggle.name} pressed={Boolean((current.toggles || {})[toggle.name])} onClick={() => setToggle(toggle.name)}>
                    <span title={toggle.ability}>{toggle.name}</span>
                  </ToggleChip>
                ))}
              </div>
            </div>
          )}
          {sliders.length > 0 && (
            <div className="flex flex-col gap-2">
              <span className="text-xs text-zinc-400">Sliders (stacks, hits, percentages)</span>
              {sliders.map((slider) => {
                const value = sliderValue(slider, current);
                const id = `tree-slider-${slider.name.replace(/\W+/g, "-")}`;
                return (
                  <div key={slider.name} className="flex flex-col gap-1">
                    <div className="flex items-baseline justify-between gap-2 text-xs">
                      <label htmlFor={id} className="text-zinc-200">
                        {slider.name} <span className="text-zinc-500">({slider.ability})</span>
                      </label>
                      <span className="tabular-nums text-zinc-200">
                        {value} / {slider.max}
                      </span>
                    </div>
                    <McRange
                      id={id}
                      min={0}
                      max={slider.max}
                      step={slider.step}
                      value={value}
                      onChange={(event) => setSlider(slider.name, Number(event.target.value))}
                      className="w-full"
                      accent="#FFAA00"
                    />
                  </div>
                );
              })}
            </div>
          )}
          {toggles.length === 0 && sliders.length === 0 && <p className="text-xs text-zinc-500">These abilities have no toggles or sliders.</p>}
        </>
      )}
    </section>
  );
}

function BuildTotals({ build }) {
  const weapon = build.slots.find((slot) => slot.id === "weapon").item;
  const rows = Object.entries(build.profile.weights)
    .filter(([key]) => key !== "hp" && build.totals[key])
    .sort((a, b) => Math.abs(b[1]) - Math.abs(a[1]))
    .slice(0, 7)
    .map(([key]) => ({ key, value: build.totals[key] }));
  return (
    <section className="mc-panel flex flex-col gap-3 p-4">
      <div className="flex items-center justify-between gap-2">
        <h3 className="mc-title text-sm uppercase">Build totals</h3>
        <span className="text-xs text-zinc-500">stats {build.archetype} cares about</span>
      </div>
      <ul className="flex flex-col gap-1 font-mono text-sm">
        {weapon && (
          <li className="flex items-baseline justify-between gap-3">
            <span className="text-zinc-300">Weapon DPS</span>
            <span className="tabular-nums font-semibold text-amber-400">{formatNumber(weapon.dps || 0)}</span>
          </li>
        )}
        <li className="flex items-baseline justify-between gap-3">
          <span className="text-zinc-300">Health from items</span>
          <span className="tabular-nums font-semibold text-zinc-100">{formatNumber(build.totals.hp || 0)}</span>
        </li>
        {rows.map((row) => (
          <StatLine key={row.key} statKey={row.key} value={row.value} />
        ))}
      </ul>
      <SetBonusList items={build.slots.filter((slot) => slot.item).map((slot) => slot.item)} playerClass={build.playerClass} />
    </section>
  );
}

// Aktywne bonusy setów (jak "Set Bonus" w grze): liczba założonych przedmiotów zestawu i identyfikacje bonusu.
function SetBonusList({ items, playerClass }) {
  const sets = activeSets(items);
  if (sets.length === 0) return null;
  return (
    <div className="mc-hr flex flex-col gap-2 pt-3">
      {sets.map((set) => {
        const lines = ID_DISPLAY.filter((display) => typeof set.bonus[display.key] === "number" && set.bonus[display.key] !== 0);
        const majors = Array.isArray(set.bonus.majorIds) ? set.bonus.majorIds : [];
        return (
          <div key={set.name} className="flex flex-col gap-1 text-sm">
            <span style={ts({ color: TOOLTIP.good })}>
              {set.name} set bonus ({set.count}/{set.size})
            </span>
            {set.illegal ? (
              <span className="text-xs" style={ts({ color: TOOLTIP.bad })}>
                These items can't be worn together in game.
              </span>
            ) : lines.length === 0 && majors.length === 0 ? (
              <span className="text-xs text-zinc-500">No bonus yet at {set.count} piece{set.count === 1 ? "" : "s"}.</span>
            ) : (
              <ul className="flex flex-col gap-0.5 font-mono text-xs">
                {lines.map((display) => {
                  const value = set.bonus[display.key];
                  const good = display.invert ? value < 0 : value > 0;
                  return (
                    <li key={display.key} className="flex items-baseline justify-between gap-3">
                      <span className="text-zinc-300">{idLabel(display, playerClass)}</span>
                      <span className="tabular-nums" style={ts({ color: good ? TOOLTIP.good : TOOLTIP.bad })}>
                        {formatIdValue(display, value)}
                      </span>
                    </li>
                  );
                })}
                {majors.map((major) => (
                  <li key={major} className="text-zinc-300">
                    Major ID: {major}
                  </li>
                ))}
              </ul>
            )}
          </div>
        );
      })}
    </div>
  );
}

function WeightChips({ profile }) {
  const customized = profile.customElements || profile.options.boosts.length > 0;
  const chips = Object.entries(profile.weights)
    .filter(([key, weight]) => weight !== 0 && !profile.derivedKeys.has(key) && (key !== "rDamPct" || (ARCHETYPES[profile.name].weights || {}).rDamPct !== undefined))
    .sort((a, b) => Math.abs(b[1]) - Math.abs(a[1]))
    .slice(0, customized ? 10 : 8);
  return (
    <ul className="flex flex-wrap gap-2" aria-label="Archetype stat weights">
      <li className="mc-slot mc-gold px-2 py-0.5 text-xs">Weapon DPS ×{profile.weaponWeight.toFixed(1)}</li>
      {chips.map(([key, weight]) => (
        <li key={key} className="mc-slot px-2 py-0.5 text-xs text-zinc-300">
          {STAT_META[key].label}
          {STAT_META[key].unit === "%" ? " %" : ""}
          {weight < 0 ? " ↓" : ""} ×{Math.abs(weight).toFixed(1)}
        </li>
      ))}
    </ul>
  );
}

function describeOptions(rawOptions) {
  const options = normalizeOptions(rawOptions);
  const parts = [];
  if (options.elements.length > 0) parts.push(`${options.elements.map((element) => ELEMENT_STYLE[element].label).join(" + ")} damage`);
  if (options.attackSpeeds.length > 0) {
    parts.push(`${options.attackSpeeds.map((speed) => ATTACK_SPEED_LABELS[speed]).join(" / ")} weapons`);
  }
  if (options.boosts.length > 0) {
    parts.push(`extra ${options.boosts.map((id) => STAT_BOOSTS.find((boost) => boost.id === id).label).join(", ")}`);
  }
  FOCUS_GROUPS.forEach((group) => {
    if (options.focus[group.id] !== undefined) parts.push(`${group.label} ${options.focus[group.id]}%`);
  });
  if (options.levelWindow !== "prefer10") parts.push(LEVEL_WINDOWS.find((entry) => entry.id === options.levelWindow).label.toLowerCase());
  if (options.excludedTiers.length > 0) parts.push(`no ${options.excludedTiers.join("/")} items`);
  if (options.onlyListed && hasLiveData()) parts.push("only items on the market");
  const overrides = Object.keys(options.scoring.weights).length + Object.keys(options.scoring.tuning).length;
  if (overrides > 0) parts.push(`${overrides} custom score weight${overrides === 1 ? "" : "s"}`);
  if (options.preferGuideItems) parts.push("guide items preferred");
  if (options.defences.length > 0) parts.push(`${options.defences.map((element) => ELEMENT_STYLE[element].label).join(" + ")} defence`);
  if (options.avoidNegativeDefences) parts.push("no negative defences");
  const pinnedCount = Object.keys(options.locked).length;
  if (pinnedCount > 0) parts.push(`${pinnedCount} pinned item${pinnedCount === 1 ? "" : "s"}`);
  if (options.excluded.length > 0) parts.push(`${options.excluded.length} excluded item${options.excluded.length === 1 ? "" : "s"}`);
  return parts.join(" · ");
}

function sameOptions(a, b) {
  return JSON.stringify(normalizeOptions(a)) === JSON.stringify(normalizeOptions(b));
}

function toggleValue(list, value) {
  return list.includes(value) ? list.filter((entry) => entry !== value) : [...list, value];
}

function ToggleChip({ pressed, onClick, color, children, title = undefined, className = "", style = undefined }) {
  return (
    <button
      type="button"
      aria-pressed={pressed}
      title={title}
      onClick={onClick}
      className={`mc-btn mc-btn-sm ${pressed ? "mc-btn-on" : ""} ${className}`}
      style={{ ...(style || {}), ...ts(color ? { color } : pressed ? { color: "#FFAA00" } : undefined) }}
    >
      {children}
    </button>
  );
}

// Suwak w stylu gry: wypełnienie od zera do uchwytu w kolorze accent (jak XP bar), szary klocek jako uchwyt.
function McRange({ value, min = 0, max = 100, accent = "#FFAA00", className = "", style, ...props }) {
  const low = Number(min);
  const span = Number(max) - low;
  const fill = span > 0 ? Math.min(100, Math.max(0, ((Number(value) - low) / span) * 100)) : 0;
  return (
    <input
      type="range"
      min={min}
      max={max}
      value={value}
      className={`mc-range ${className}`}
      style={ts({ ...style, "--mc-accent": accent, "--mc-fill": `${fill}%` })}
      {...props}
    />
  );
}

// Suwak zakresu z dwoma uchwytami (minimum i maksimum). Skrajne pozycje (krok przed lo i krok za hi) = "Any", czyli
// bez granicy z tej strony. value: { min, max } z null = Any; onChange dostaje nową parę.
function McRangePair({ id, lo, hi, step, value, onChange, accent = "#FFAA00", disabled = false, labels = ["Minimum", "Maximum"], format = (v) => String(v) }) {
  const anyLo = lo - step;
  const anyHi = hi + step;
  const current = value || { min: null, max: null };
  const a = current.min === null || current.min === undefined ? anyLo : Math.max(lo, Math.min(hi, current.min));
  const b = current.max === null || current.max === undefined ? anyHi : Math.max(lo, Math.min(hi, current.max));
  const span = anyHi - anyLo;
  const pa = (a - anyLo) / span;
  const pb = (b - anyLo) / span;
  const snap = (v) => Number((Math.round(v / step) * step).toFixed(3));
  const setMin = (raw) => {
    const v = Number(raw);
    if (v <= anyLo + step / 2) return onChange({ min: null, max: current.max ?? null });
    const cap = b >= anyHi - step / 2 ? hi : b;
    onChange({ min: snap(Math.min(v, cap)), max: current.max ?? null });
  };
  const setMax = (raw) => {
    const v = Number(raw);
    if (v >= anyHi - step / 2) return onChange({ min: current.min ?? null, max: null });
    const floor = a <= anyLo + step / 2 ? lo : a;
    onChange({ min: current.min ?? null, max: snap(Math.max(v, floor)) });
  };
  return (
    <div className="mc-range2" style={ts({ "--mc-accent": accent, opacity: disabled ? 0.45 : undefined })}>
      <div className="mc-range2-track" aria-hidden="true">
        <div className="mc-range2-fill" style={{ left: `calc(4px + (100% - 12px) * ${pa})`, width: `calc((100% - 12px) * ${Math.max(0, pb - pa)})` }} />
      </div>
      <input
        id={id}
        type="range"
        min={anyLo}
        max={anyHi}
        step={step}
        value={a}
        disabled={disabled}
        onChange={(event) => setMin(event.target.value)}
        aria-label={labels[0]}
        aria-valuetext={a <= anyLo ? "any" : format(a)}
        style={{ zIndex: pa > 0.5 ? 3 : 2 }}
      />
      <input
        id={id ? `${id}-max` : undefined}
        type="range"
        min={anyLo}
        max={anyHi}
        step={step}
        value={b}
        disabled={disabled}
        onChange={(event) => setMax(event.target.value)}
        aria-label={labels[1]}
        aria-valuetext={b >= anyHi ? "any" : format(b)}
        style={{ zIndex: pa > 0.5 ? 2 : 3 }}
      />
    </div>
  );
}

// Trzy suwaki zakresu (Generate i Optimize): skala, jednostka, kolor i presety (przyciski nad suwakiem).
function rangeUi(kind, level) {
  if (kind === "mana")
    return {
      label: "Mana balance",
      unit: " mana/s",
      lo: -20,
      hi: 10,
      step: 0.5,
      digits: 1,
      signed: true,
      accent: "#55FFFF",
      presets: [
        ["Full sustain", { min: 0, max: 1 }, "The cycle pays for itself and wastes at most 1 mana/s"],
        ["Raid buffs", { min: -3, max: 1 }, "May lose up to 3 mana/s - raid buffs or a support cover it"],
        ["Burst", { min: -8, max: null }, "May lose up to 8 mana/s: the pool runs out in about 25 s"],
        ["Any", { min: null, max: null }, "No mana condition"],
      ],
    };
  if (kind === "life") {
    const top = lifeRecoveryMax(level);
    const light = Math.max(5, Math.round((top * 0.1) / 5) * 5);
    const strong = Math.max(10, Math.round((top * 0.4) / 5) * 5);
    return {
      label: "Life recovery",
      unit: " HP/s",
      lo: 0,
      hi: top,
      step: 5,
      digits: 0,
      signed: false,
      accent: "#FF5555",
      presets: [
        ["Any", { min: null, max: null }, "No life condition"],
        ["Light", { min: light, max: null }, `At least ${light} HP/s`],
        ["Strong sustain", { min: strong, max: null }, `At least ${strong} HP/s`],
      ],
    };
  }
  return {
    label: "Walk Speed",
    unit: "%",
    lo: -100,
    hi: 150,
    step: 5,
    digits: 0,
    signed: true,
    accent: "#FFFF55",
    presets: [
      ["Any", { min: null, max: null }, "No walk speed condition (like 0.35)"],
      ["Default", { ...DEFAULT_SPD_RANGE }, "At least −20% walk speed"],
      ["No slowdown", { min: 0, max: null }, "At least 0%"],
      ["Mobile", { min: 20, max: null }, "At least +20%"],
      ["Fast", { min: 40, max: null }, "At least +40%"],
    ],
  };
}
function rangeValueText(range, ui) {
  const r = normalizeRange(range);
  if (!r) return "any";
  const text = (value) => `${ui.signed && value > 0 ? "+" : value < 0 ? "−" : ""}${ui.digits > 0 ? Math.abs(value).toFixed(ui.digits) : formatNumber(Math.abs(Math.round(value)))}`;
  if (r.min !== null && r.max !== null) return `${text(r.min)} to ${text(r.max)}${ui.unit}`;
  if (r.min !== null) return `≥ ${text(r.min)}${ui.unit}`;
  return `≤ ${text(r.max)}${ui.unit}`;
}
// Zakres EHP buildu jako tekst: "≥ 12,340", "12,340 to 30,000", "≤ 30,000"; "" gdy bez warunku.
function ehpRangeText(metrics) {
  const min = metrics && metrics.minEhp > 0 ? metrics.minEhp : null;
  const max = metrics && Number(metrics.maxEhp) > 0 ? metrics.maxEhp : null;
  if (min !== null && max !== null) return `${formatNumber(Math.round(min))} to ${formatNumber(Math.round(max))}`;
  if (min !== null) return `≥ ${formatNumber(Math.round(min))}`;
  if (max !== null) return `≤ ${formatNumber(Math.round(max))}`;
  return "";
}
function sameRange(a, b) {
  const x = normalizeRange(a);
  const y = normalizeRange(b);
  if (!x || !y) return !x && !y;
  return x.min === y.min && x.max === y.max;
}
// Suwak zakresu z etykietą, wartością, presetami i podpowiedzią (hint - tekst albo null).
// ui: własna skala zamiast rangeUi (Effective HP), valueText: własny tekst wartości, heading: etykieta jako nagłówek
// sekcji (kreator: większa, wielkie litery).
function RangeControl({ id, kind, level, value, onChange, hint = null, disabled = false, disabledHint = null, title = undefined, compact = false, ui: uiProp = null, valueText = null, heading = false }) {
  const ui = uiProp || rangeUi(kind, level);
  return (
    <div className="flex flex-col gap-1" title={title}>
      <div className={heading ? "flex items-baseline justify-between gap-2" : SLIDER_HEAD}>
        <label htmlFor={id} className={heading ? SECTION_HEAD : SUB_HEAD}>
          {ui.label}
        </label>
        <span className={`tabular-nums text-zinc-100 ${heading ? "text-sm" : ""}`}>{disabled ? "off" : valueText !== null ? valueText : rangeValueText(value, ui)}</span>
      </div>
      <div className={`flex flex-wrap gap-1 ${compact ? "" : "mb-0.5"}`} role="group" aria-label={`${ui.label} presets`}>
        {ui.presets.map(([name, range, tip]) => (
          <button key={name} type="button" disabled={disabled} className={`mc-btn mc-btn-sm ${!disabled && sameRange(value, range) ? "mc-btn-on" : ""}`} title={tip} onClick={() => onChange({ ...range })}>
            {name}
          </button>
        ))}
      </div>
      <McRangePair
        id={id}
        lo={ui.lo}
        hi={ui.hi}
        step={ui.step}
        value={value}
        onChange={onChange}
        accent={ui.accent}
        disabled={disabled}
        labels={[`${ui.label} minimum`, `${ui.label} maximum`]}
        format={(v) => rangeValueText({ min: v, max: v }, ui).replace(/ to .*/, ui.unit)}
      />
      {(disabled ? disabledHint : hint) && <p className="text-xs text-zinc-500">{disabled ? disabledHint : hint}</p>}
    </div>
  );
}
// Podpowiedzi przy suwakach zakresu (liczone z buildu na ekranie, gdy jest).
function manaRangeHint(range) {
  const r = normalizeRange(range);
  if (!r) return "Any: no mana condition (the cycle still counts for Mana Steal and the goal).";
  const parts = [];
  if (r.min !== null && r.min < 0) parts.push(`${r.min} mana/s = the full pool (200) lasts ${Math.round(200 / -r.min)} s of fighting`);
  else if (r.min !== null) parts.push(r.min === 0 ? "the cycle pays for itself" : `at least +${r.min} mana/s to spare`);
  if (r.max !== null) parts.push(`at most ${r.max > 0 ? "+" : ""}${r.max} mana/s wasted - stats beyond that go to damage or EHP`);
  return `${parts.join("; ")}.`;
}
function lifeRangeHint(range, hp) {
  const r = normalizeRange(range);
  if (!r) return "Any: no life condition. Health Regen ÷ 4 s + Life Steal from the cycle's main attacks (M).";
  const value = r.min !== null ? r.min : r.max;
  return hp > 0 && value > 0 ? `${formatNumber(value)} HP/s = ${Math.round((value / hp) * 100)}% of your build's health per second.` : "Health Regen ÷ 4 s + Life Steal from the cycle's main attacks (M).";
}
function speedRangeHint(build) {
  if (!build || !build.slots) return "The walk speed of the whole build: items, set bonuses and ability tree (the number in the summary).";
  const slowest = build.slots
    .filter((slot) => slot.item && (slot.item.ids.spd || 0) < 0)
    .sort((a, b) => (a.item.ids.spd || 0) - (b.item.ids.spd || 0))
    .slice(0, 2)
    .map((slot) => `${slot.item.name} ${slot.item.ids.spd}%`);
  const value = build.metrics && Number.isFinite(build.metrics.walkSpeed) ? build.metrics.walkSpeed : null;
  return `${value !== null ? `This build: ${value > 0 ? "+" : ""}${Math.round(value)}%.` : ""}${slowest.length > 0 ? ` Slowed most by ${slowest.join(", ")}.` : ""}`.trim() || "The walk speed of the whole build (the number in the summary).";
}

// Suwaki "Build focus": wartość 0-100% dla main attacku, czarów i EHP. Kreska na suwaku i "meta" to domyślna
// pozycja archetypu (z wag skalibrowanych na poradniku); nieruszony suwak jej używa.
function FocusSliders({ options, onChange, archetype }) {
  const focus = options.focus || {};
  const info = useMemo(() => getArchetypeProfile(archetype, { ...options, focus: {} }).focusSliders, [archetype, options]);
  const custom = FOCUS_GROUPS.some((group) => focus[group.id] !== undefined);
  function setFocus(id, value) {
    const next = { ...focus };
    if (value === null) delete next[id];
    else next[id] = value;
    onChange({ ...options, focus: next });
  }
  return (
    <fieldset className="flex flex-col gap-3">
      <div className="flex items-center justify-between">
        <legend className="text-xs text-zinc-300">Build focus</legend>
        {custom && (
          <button
            type="button"
            onClick={() => onChange({ ...options, focus: {} })}
            className="mc-link text-xs"
          >
            Archetype meta
          </button>
        )}
      </div>
      {FOCUS_GROUPS.map((group) => {
        const meta = info.defaults[group.id];
        const touched = focus[group.id] !== undefined;
        const value = touched ? focus[group.id] : meta;
        return (
          <div key={group.id} className="flex flex-col gap-1">
            <div className="flex items-baseline justify-between gap-2 text-xs">
              <label htmlFor={`focus-${group.id}`} className="font-semibold" style={ts({ color: group.color })}>
                {group.label}
              </label>
              <span className="tabular-nums text-zinc-200">
                {value}%
                {touched && value !== meta ? (
                  <button
                    type="button"
                    onClick={() => setFocus(group.id, null)}
                    className="mc-link ml-2 text-zinc-500"
                    title="Back to the archetype's meta value"
                  >
                    meta {meta}%
                  </button>
                ) : (
                  <span className="ml-2 text-zinc-500">{touched ? "= meta" : "meta"}</span>
                )}
              </span>
            </div>
            <div className="relative">
              <McRange
                id={`focus-${group.id}`}
                min={0}
                max={100}
                step={1}
                value={value}
                onChange={(event) => setFocus(group.id, Number(event.target.value))}
                className="w-full"
                accent={group.color}
                aria-describedby={`focus-${group.id}-hint`}
              />
              <span className="mc-tick" style={ts({ left: `calc(6px + (100% - 12px) * ${meta / 100})` })} title={`Archetype meta: ${meta}%`} aria-hidden="true" />
            </div>
            <p id={`focus-${group.id}-hint`} className="sr-only">
              {group.hint}
            </p>
          </div>
        );
      })}
      <p
        className="text-xs text-zinc-500"
        title={`X% = X% of the group's full priority: 0% ignores it, 100% is all-in, 50% is half of that. The marker only shows where this archetype's guide builds sit; it is not a target and adds nothing to the score. Above the marker, Main attack DPS switches to the build's real DPS (attack speed tiers, raw × hits/s, Strength).`}
      >
        Marker = where the guide builds sit (for reference only).
      </p>
    </fieldset>
  );
}

// Wykluczenie przedmiotu: na listę wykluczonych i zdjęty z przypiętych (lustro przypinania).
function excludeItem(options, name) {
  const locked = Object.fromEntries(Object.entries(options.locked || {}).filter(([, lockedName]) => lockedName !== name));
  return { ...options, locked, excluded: [...new Set([...(options.excluded || []), name])] };
}

// "Pin or exclude an item": wyszukiwarka nazw (broń klasy, pancerz, akcesoria do poziomu gracza). Pin przypina przedmiot
// do jego slotu (pierścień: wolny palec) - build wokół konkretnej broni; Exclude wyklucza go z każdego buildu (bez
// potrzeby dostania go najpierw w buildzie). Zmiany nie uruchamiają generatora - build dostaje znacznik nieaktualnego.
function PinItemSearch({ options, onChange, weaponType, level, onBrowse = null }) {
  const [query, setQuery] = useState("");
  const needle = query.trim().toLowerCase();
  const matches =
    needle.length < 2
      ? []
      : ITEM_DB.filter((item) => item.level <= level && (item.category !== "weapon" || !weaponType || item.type === weaponType) && item.name.toLowerCase().includes(needle))
          .sort((a, b) => (a.name.toLowerCase().startsWith(needle) === b.name.toLowerCase().startsWith(needle) ? b.level - a.level : a.name.toLowerCase().startsWith(needle) ? -1 : 1))
          .slice(0, 8);
  const pin = (item) => {
    const locked = { ...(options.locked || {}) };
    let slotId = item.category === "weapon" ? "weapon" : item.type;
    if (item.type === "ring") slotId = !locked.ring1 || locked.ring1 === item.name ? "ring1" : "ring2";
    locked[slotId] = item.name;
    onChange({ ...options, locked, excluded: (options.excluded || []).filter((name) => name !== item.name) });
    setQuery("");
  };
  const excluded = new Set(options.excluded || []);
  const exclude = (item) => onChange(excludeItem(options, item.name));
  return (
    <div className="flex flex-col gap-2">
      <label htmlFor="pin-search" className="text-xs text-zinc-300">
        Pin or exclude an item
      </label>
      <div className="flex flex-wrap gap-2">
        <input
          id="pin-search"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder={`Item name, e.g. a ${weaponType || "weapon"}`}
          className="mc-input w-full min-w-0 flex-1 basis-40"
          autoComplete="off"
          spellCheck={false}
        />
        {onBrowse && (
          <button type="button" onClick={onBrowse} className="mc-btn mc-btn-sm whitespace-nowrap" title="Browse every item with filters: type, element, rarity, level, attack speed, DPS">
            Browse items…
          </button>
        )}
      </div>
      {needle.length >= 2 && (
        <ul className="mc-well flex max-h-64 flex-col overflow-y-auto">
          {matches.length === 0 ? (
            <li className="px-2 py-1 text-xs text-zinc-500">No {weaponType || "weapon"}, armour or accessory up to level {level} matches.</li>
          ) : (
            matches.map((item) => (
              <li key={item.name} className="flex items-center justify-between gap-2 px-2 py-1 text-sm">
                <span className="flex min-w-0 flex-col">
                  <span className="truncate" style={ts({ color: RARITY_COLORS[item.tier] || RARITY_COLORS.Normal })}>
                    {item.name}
                  </span>
                  <span className="text-xs text-zinc-500">
                    {item.tier} {item.type} · Lv. {item.level}
                    {item.category === "weapon" ? ` · ${formatNumber(item.dps || 0)} DPS` : ""}
                    {hasLiveData() && marketStatus(item).state === "listed" ? " · " : ""}
                    {hasLiveData() && marketStatus(item).state === "listed" ? <MarketDot item={item} /> : null}
                  </span>
                </span>
                <span className="flex shrink-0 gap-1">
                  <button type="button" onClick={() => pin(item)} className="mc-btn mc-btn-sm" aria-label={`Pin ${item.name}`}>
                    Pin
                  </button>
                  {excluded.has(item.name) ? (
                    <button type="button" disabled className="mc-btn mc-btn-sm" style={ts({ opacity: 0.55 })}>
                      Excluded
                    </button>
                  ) : (
                    <button type="button" onClick={() => exclude(item)} className="mc-btn mc-btn-sm" aria-label={`Exclude ${item.name}`}>
                      Exclude
                    </button>
                  )}
                </span>
              </li>
            ))
          )}
        </ul>
      )}
      <p className="text-xs text-zinc-500" title="Type a name, or open Browse items… to filter by type, element, rarity, level, attack speed, DPS and identifications. Pinned and excluded items show below; they apply on Generate Build.">
        Pinned items always stay. Excluded items are never used.
      </p>
    </div>
  );
}

// Budżet w emeraldach (E / EB / LE / STX) pod "Allowed rarities"; ceny z Trade Marketu (WynnVentory).
function BudgetInput({ options, onChange }) {
  const normalized = normalizeOptions(options);
  const unit = EMERALD_UNITS.find((entry) => entry.id === normalized.budgetUnit) || EMERALD_UNITS[2];
  const [text, setText] = useState(normalized.budget ? String(Math.round((normalized.budget / unit.value) * 100) / 100) : "");
  const prices = hasPriceData();
  const apply = (value, unitId) => {
    const nextUnit = EMERALD_UNITS.find((entry) => entry.id === unitId) || unit;
    const amount = Number(String(value).replace(",", "."));
    onChange({ ...options, budget: value === "" || !(amount > 0) ? null : Math.round(amount * nextUnit.value), budgetUnit: nextUnit.id });
  };
  const info = prices
    ? `Trade Market prices from WynnVentory (average of the middle 80% of listings, ${PRICE_DATA.days || 7} days${PRICE_DATA.fetchedAt ? `, updated ${String(PRICE_DATA.fetchedAt).slice(0, 10)}` : ""}). Pinned items don't count (you have them); untradable items cost nothing; Fabled/Mythic items without listings are skipped. 1 EB = 64 E, 1 LE = 64 EB, 1 STX = 64 LE.`
    : "No Trade Market prices in this copy of the site. The GitHub Pages version fetches them from WynnVentory when the repository has a WYNNVENTORY_KEY secret (see the README).";
  return (
    <div className="flex flex-col gap-2">
      <label htmlFor="budget" className="text-xs text-zinc-300">
        Budget
      </label>
      <div className="flex gap-2">
        <input
          id="budget"
          type="text"
          inputMode="decimal"
          value={text}
          disabled={!prices}
          placeholder={prices ? "No limit" : "No price data"}
          onChange={(event) => {
            setText(event.target.value);
            apply(event.target.value, unit.id);
          }}
          className="mc-input min-w-0 flex-1 tabular-nums"
          style={ts(prices ? undefined : { opacity: 0.5 })}
        />
        <select
          aria-label="Budget unit"
          value={unit.id}
          disabled={!prices}
          onChange={(event) => apply(text, event.target.value)}
          className="mc-input w-20"
          style={ts(prices ? undefined : { opacity: 0.5 })}
        >
          {EMERALD_UNITS.map((entry) => (
            <option key={entry.id} value={entry.id}>
              {entry.label}
            </option>
          ))}
        </select>
      </div>
      <p className="text-xs text-zinc-500" title={info}>
        {!prices ? "No price data yet." : normalized.budget ? `Max ${formatEmeralds(normalized.budget)}.` : "Trade Market prices."}
      </p>
      <OnlyListedCheckbox options={options} onChange={onChange} />
    </div>
  );
}

// Checkbox pod budżetem: build tylko z przedmiotów wystawionych dziś na Trade Markecie.
function OnlyListedCheckbox({ options, onChange }) {
  const live = hasLiveData();
  const checked = live && normalizeOptions(options).onlyListed;
  const count = live ? Object.values(LIVE_ITEMS).filter((entry) => entry && entry.n > 0).length : 0;
  const info = live
    ? `Only items listed on the Trade Market today (${count.toLocaleString("en-US")} items, WynnVentory snapshot ${formatClock(PRICE_DATA.liveAt)}). Pinned items stay (you have them); untradable and quest items are skipped; a slot with nothing listed stays empty. Listings can sell in the meantime.`
    : "No Trade Market listings in this copy of the site. The GitHub Pages version fetches them from WynnVentory when the repository has a WYNNVENTORY_KEY secret (see the README).";
  return (
    <div className="flex flex-col gap-1">
      <label htmlFor="only-listed" className="flex items-center gap-2 text-xs text-zinc-200" title={info} style={ts(live ? undefined : { opacity: 0.5 })}>
        <input
          id="only-listed"
          type="checkbox"
          checked={checked}
          disabled={!live}
          onChange={() => onChange({ ...options, onlyListed: !checked })}
          className="mc-check"
        />
        Only items on the market
      </label>
      <p className="text-xs text-zinc-500" title={info}>
        {!live ? "No market data yet." : checked ? "Listed today only." : "Any item."}
      </p>
    </div>
  );
}

// Lista celów optymalizacji z drzewka: main attack (DPS) i każdy czar zadający obrażenia (trafienie).
// Liczona na najmocniejszej broni klasy bez ekwipunku - służy tylko do nazw, kosztów many i domyślnego wyboru.
// Broń "reprezentatywna" dla podglądu czarów i kolejności celów: spośród najmocniejszych (DPS) ta, która daje
// największy pojedynczy czar. Sam najwyższy DPS bywał mylący - np. Gert Relik ma -300% Spell Damage i wszystkie
// czary liczyły się na 0.
function representativeWeapon(playerClass, level, treeSettings, items = ITEM_DB) {
  const classConfig = CLASSES[playerClass];
  if (!classConfig) return null;
  const top = items
    .filter((item) => item.category === "weapon" && item.type === classConfig.weapon && item.level <= level)
    .sort((a, b) => (b.dps || 0) - (a.dps || 0))
    .slice(0, 12);
  if (top.length === 0) return null;
  const ctx = damageGoalContext(playerClass, level, treeSettings);
  let best = null;
  top.forEach((weapon) => {
    const sp = computeSkillPoints([weapon]);
    const { stats, scaled } = goalStats(ctx, [weapon], weapon, sp.totals);
    const hp = Math.max(5, statValue(stats, "hp") + statValue(stats, "hpBonus"));
    let score = 0;
    collectTreeSpells(scaled.edited, scaled.translate).forEach((spell, id) => {
      if (id === 0) return;
      const evaluated = evaluateSpell(spell, stats, weapon, hp);
      if (evaluated.main && evaluated.main.type === "damage") score = Math.max(score, evaluated.main.amount);
    });
    if (!best || score > best.score) best = { weapon, score };
  });
  return best.score > 0 ? best.weapon : top[0];
}

function damageGoalOptions(playerClass, level, treeSettings, items = ITEM_DB, cycle = null) {
  const classConfig = CLASSES[playerClass];
  if (!classConfig) return [];
  const weapon = representativeWeapon(playerClass, level, treeSettings, items);
  if (!weapon) return [];
  const ctx = damageGoalContext(playerClass, level, treeSettings);
  const sp = computeSkillPoints([weapon]);
  const { stats, scaled } = goalStats(ctx, [weapon], weapon, sp.totals);
  const hp = Math.max(5, statValue(stats, "hp") + statValue(stats, "hpBonus"));
  const spells = collectTreeSpells(scaled.edited, scaled.translate);
  const options = [];
  spells.forEach((spell, id) => {
    if (id === 0) return;
    const evaluated = evaluateSpell(spell, stats, weapon, hp);
    if (!evaluated.main || evaluated.main.type !== "damage") return;
    options.push({ id, name: evaluated.name, damage: evaluated.main.amount, cost: evaluated.cost, kind: "spell" });
  });
  options.sort((a, b) => b.damage - a.damage);
  const melee = spells.has(0) ? evaluateSpell(spells.get(0), stats, weapon, hp) : null;
  const weaponHps = HITS_PER_SECOND[attackSpeedAfterTier(weapon, statValue(stats, "atkTier"))];
  options.push({
    id: DAMAGE_GOAL_MAIN,
    name: melee ? melee.name : "Main attack",
    damage: melee && melee.main ? melee.main.amount * weaponHps : 0,
    cost: null,
    kind: "melee",
  });
  // cały cykl (gdy formularz ma cykl z czarami, które drzewko zna)
  const cycleIds = cycle && cycle.ids ? cycle.ids : [];
  if (cycleIds.some((id) => id !== 0) && cycleIds.every((id) => id === 0 || spells.has(id))) {
    const timing = cycleTiming(cycleIds, cycle.cps, weaponHps);
    const perCast = (id) => {
      const spell = spells.get(id);
      const evaluated = spell ? evaluateSpell(spell, stats, weapon, hp) : null;
      return evaluated && evaluated.main && evaluated.main.type === "damage" ? evaluated.main.amount : 0;
    };
    const total = cycleIds.reduce((sum, id) => sum + perCast(id), 0);
    if (total > 0 && timing.seconds > 0) options.push({ id: DAMAGE_GOAL_CYCLE, name: `Whole cycle ${cycleText(cycleIds)}`, damage: total / timing.seconds, cost: null, kind: "cycle" });
  }
  return options;
}

// Ile EHP da się osiągnąć na danym poziomie (policzone skryptem scripts/update-ehp-range.mjs, bez drzewka).
function reachableEhp(playerClass, level) {
  const table = (EHP_RANGE.levels || {})[playerClass];
  if (!table) return 100000;
  return table[Math.min(table.length - 1, Math.max(0, Math.round(level) - 1))] || 1000;
}

// Cel z formularza: jedno id (czar / main attack) albo tablica kilku id - wtedy maksymalizujemy sumę obrażeń
// jednego rzutu każdego z nich (w kolejności listy celów).
function resolveGoal(goals, formGoal) {
  if (Array.isArray(formGoal)) {
    const chosen = goals.filter((entry) => formGoal.some((id) => String(id) === String(entry.id)));
    if (chosen.length >= 2)
      return { id: chosen.map((entry) => entry.id), name: chosen.map((entry) => entry.name).join(" + "), damage: chosen.reduce((sum, entry) => sum + entry.damage, 0), cost: null, kind: "multi", parts: chosen };
    if (chosen.length === 1) return chosen[0];
    return goals[0] || null;
  }
  return goals.find((entry) => String(entry.id) === String(formGoal)) || goals[0] || null;
}
function goalKey(goal) {
  return Array.isArray(goal) ? goal.join("+") : String(goal);
}

// poison: poison w celu obrażeń (domyślnie nie); rolls: "max" (100%, jak Wynnbuilder) albo "avg" (50%);
// raidMana: mana/s z buffów w raidzie (Advanced, 0 = wyłączone).
// Suwaki zakresu (0.37), { min, max } z null = Any: drain = bilans many cyklu w mana/s (ujemny = dren, dodatni =
// nadwyżka; domyślnie od 0 do +1 = pełny sustain bez marnowania), lr = odnawianie życia w HP/s (domyślnie Any),
// spd = Walk Speed w % (domyślnie co najmniej -20%). Przełącznik "Life sustain > 0" zastąpiło minimum 1 HP/s.
const DEFAULT_MANA_RANGE = { min: 0, max: 1 };
const DEFAULT_LIFE_RANGE = { min: null, max: null };
const DEFAULT_SPD_RANGE = { min: -20, max: null };
const DEFAULT_DAMAGE_FORM = { preset: "", goal: null, minEhp: null, maxEhp: null, cycle: "", cps: 3, steal: true, gain: true, noEvents: true, tradeable: false, freeSp: true, poison: false, rolls: "max", drain: DEFAULT_MANA_RANGE, lr: DEFAULT_LIFE_RANGE, spd: DEFAULT_SPD_RANGE, raidMana: 0 };
// Para { min, max } z formularza; stare wartości liczbowe (0.35-0.36) przez fromNumber.
function rangePair(value, fromNumber) {
  if (value && typeof value === "object") {
    const range = normalizeRange(value);
    return range || { min: null, max: null };
  }
  if (value === null || value === undefined || value === "") return fromNumber(0);
  return fromNumber(Number(value) || 0);
}
const formManaPair = (form) => rangePair(form.drain, (drain) => rangeFromDrain(drain));
const formLifePair = (form) => {
  const pair = rangePair(form.lr, (lr) => rangeFromMinimum(lr) || { min: null, max: null });
  // stary przełącznik "Life sustain > 0" = minimum 1 HP/s
  return form.sustain && (pair.min === null || pair.min < 1) ? { ...pair, min: 1 } : pair;
};
const formSpdPair = (form) => (form.spd === undefined ? { min: null, max: null } : rangePair(form.spd, () => ({ min: null, max: null })));
// Zakresy do generatora (null = bez warunku).
const formManaRange = (form) => normalizeRange(formManaPair(form));
const formLifeRange = (form) => normalizeRange(formLifePair(form));
const formSpdRange = (form) => normalizeRange(formSpdPair(form));
// Dopuszczalny dren (do podpowiedzi o manie z przedmiotów): -min, 999 = bez dolnej granicy.
function drainOfRange(range) {
  return !range || range.min === null ? 999 : -range.min;
}
// Stary stan formularza (liczbowe drain / lr, sustain; bez spd) -> zakresy o tym samym działaniu co w 0.35.
function migrateDamageForm(form) {
  const out = { ...DEFAULT_DAMAGE_FORM, ...(form || {}) };
  out.drain = form && form.drain !== undefined ? formManaPair(out) : { min: 0, max: null };
  out.lr = form && (form.lr !== undefined || form.sustain) ? formLifePair(out) : { min: null, max: null };
  out.spd = form && form.spd !== undefined ? formSpdPair(out) : { min: null, max: null };
  delete out.sustain;
  return out;
}
function formCycleOf(form) {
  return { ids: parseCycle(form.cycle), cps: form.cps, steal: form.steal, gain: form.gain, poison: Boolean(form.poison), mana: formManaRange(form), buff: Math.max(0, Number(form.raidMana) || 0) };
}

// Suwak EHP chodzi co 5% tego, co da się osiągnąć na danym poziomie; domyślnie 25%.
function ehpStep(ehpMax) {
  return Math.max(1, Math.round(ehpMax / 20));
}
function defaultMinEhp(ehpMax) {
  return ehpStep(ehpMax) * 5;
}
// Suwak Effective HP (0.38): zakres w % tego, co da się osiągnąć na poziomie, co 2%; lewy koniec = bez minimum,
// prawy = bez maksimum. Formularz trzyma liczby EHP (minEhp, maxEhp) - tak jak link buildu i lista buildów.
function ehpUi(ehpMax) {
  const at = (pct) => formatNumber(Math.round((pct / 100) * ehpMax));
  return {
    label: "Effective HP",
    unit: "%",
    lo: 2,
    hi: 100,
    step: 2,
    digits: 0,
    signed: false,
    accent: "#55FF55",
    presets: [
      ["Any", { min: null, max: null }, "No effective HP condition - pure damage"],
      ["Light", { min: 20, max: null }, `At least 20% of the most EHP your level can reach (${at(20)})`],
      ["Balanced", { min: 25, max: null }, `At least 25% (${at(25)}) - the default`],
      ["Sturdy", { min: 35, max: null }, `At least 35% (${at(35)})`],
      ["Tank", { min: 50, max: null }, `At least 50% (${at(50)})`],
    ],
  };
}
function formMinEhp(form, ehpMax) {
  return form.minEhp === null || form.minEhp === undefined ? defaultMinEhp(ehpMax) : Math.min(Math.max(0, Number(form.minEhp) || 0), ehpMax);
}
function formMaxEhp(form, ehpMax) {
  const max = Number(form.maxEhp);
  return max > 0 ? Math.max(max, formMinEhp(form, ehpMax)) : null;
}
// { min, max } w % (dla suwaka)
function ehpPctPair(form, ehpMax) {
  const pct = (value) => Math.round((value / Math.max(1, ehpMax)) * 100);
  const min = formMinEhp(form, ehpMax);
  const max = formMaxEhp(form, ehpMax);
  return { min: min > 0 ? Math.max(1, pct(min)) : null, max: max !== null ? Math.min(100, pct(max)) : null };
}
// % z suwaka -> liczby EHP w formularzu
function ehpFormPatch(range, ehpMax) {
  const r = range || {};
  const abs = (pct) => Math.round((pct / 100) * ehpMax);
  const min = r.min === null || r.min === undefined ? 0 : abs(r.min);
  const max = r.max === null || r.max === undefined ? null : Math.max(abs(r.max), min);
  return { minEhp: min, maxEhp: max };
}
// compact: sam procent (lewy panel - liczby EHP są w podpowiedzi pod suwakiem)
function ehpValueText(form, ehpMax, compact = false) {
  const min = formMinEhp(form, ehpMax);
  const max = formMaxEhp(form, ehpMax);
  const pct = (value) => Math.round((value / Math.max(1, ehpMax)) * 100);
  if (compact) {
    if (min > 0 && max !== null) return `${pct(min)}-${pct(max)}%`;
    if (min > 0) return `≥ ${pct(min)}%`;
    if (max !== null) return `≤ ${pct(max)}%`;
    return "any";
  }
  if (min > 0 && max !== null) return `${formatNumber(min)} to ${formatNumber(max)} · ${pct(min)}-${pct(max)}%`;
  if (min > 0) return `≥ ${formatNumber(min)} · ${pct(min)}%`;
  if (max !== null) return `≤ ${formatNumber(max)} · ${pct(max)}%`;
  return "any";
}
// liczby EHP zakresu dla podpowiedzi pod suwakiem w lewym panelu
function ehpNumbersText(form, ehpMax) {
  const min = formMinEhp(form, ehpMax);
  const max = formMaxEhp(form, ehpMax);
  if (min > 0 && max !== null) return `${formatNumber(min)} to ${formatNumber(max)} EHP`;
  if (min > 0) return `At least ${formatNumber(min)} EHP`;
  if (max !== null) return `At most ${formatNumber(max)} EHP`;
  return "No EHP condition";
}

// Formularz zakładki "New": klasa → ranga → poziom → drzewko → cel → próg EHP → cykl czarów (twardy filtr many).
// Wiersz z polem wyboru w lewym panelu: pole przy pierwszej linii, opis i podpowiedź jako jeden tekst, który się
// zawija - bez osobnych kolumn, żeby wszystkie wiersze wyglądały tak samo.
function CheckRow({ id = undefined, checked, onChange, label, hint = null, title = undefined, disabled = false, style = undefined }) {
  return (
    <label className="grid grid-cols-[auto_minmax(0,1fr)] items-start gap-x-2 text-xs text-zinc-200" title={title} style={style}>
      <input id={id} type="checkbox" className="mc-check mt-px" checked={checked} disabled={disabled} onChange={onChange} />
      <span className="min-w-0">
        {label}
        {hint ? <span className="text-zinc-500"> · {hint}</span> : null}
      </span>
    </label>
  );
}
// Suwaki w lewym panelu wyglądają jak suwak Effective HP: etykieta i wartość w jednej linii, pod nimi pełna szerokość.
const SLIDER_HEAD = "flex items-baseline justify-between gap-2 text-xs";
// Nagłówki (0.38): podsekcja (np. Weapon attack speed w Items) - żółta jak "ITEMS"; sekcja kreatora (Filters,
// Walk speed...) - żółta, wielkie litery, większa. Sekcje oddziela ciemniejszy pasek (wbr-sep).
const SUB_HEAD = "wbr-sub text-xs";
const SECTION_HEAD = "mc-title text-base uppercase";
function SectionBar({ wide = false }) {
  return <div className={`wbr-sep ${wide ? "wbr-sep-wide" : ""}`} aria-hidden="true" />;
}

function DamageForm({
  restrictions,
  playerClass,
  onClassChange,
  rank,
  rankConfirmed,
  onRank,
  levelInput,
  onLevelInput,
  level,
  treeIds,
  treePoints,
  apCap,
  onPreset,
  onGuideTree = null,
  onEditTree,
  form,
  onForm,
  goals,
  ehpMax,
  onGenerate,
  running,
  progress,
  onStop = null,
  result,
  outdated,
  options,
  onOptions,
  onBrowse,
  sweep = null,
  sweepOpen = false,
  onSweepToggle = null,
  onSweepPick = null,
  shownBuild = null,
  tradeoff = null,
  onTradeoff = null,
  onTradeoffUse = null,
  onTradeoffPick = null,
}) {
  const classConfig = playerClass ? CLASSES[playerClass] : null;
  const set = (patch) => onForm({ ...form, ...patch });
  const goal = resolveGoal(goals, form.goal);
  const goalIds = goal ? (Array.isArray(goal.id) ? goal.id : [goal.id]) : [];
  const cycleIds = parseCycle(form.cycle);
  const cycleCasts = cycleIds.filter((id) => id !== 0).length;
  const cycleMelee = cycleIds.length - cycleCasts;
  const ready = Boolean(playerClass && level && treeIds.length > 0 && goal);
  const label = "mc-title text-xs uppercase";
  const hint = "text-xs text-zinc-500";
  // pole "cps" trzyma tekst, żeby dało się je wyczyścić i wpisać nową liczbę (wartość przyjmujemy, gdy ma sens)
  const [cpsText, setCpsText] = useState(String(form.cps));
  useEffect(() => {
    setCpsText((text) => (Number(String(text).replace(",", ".")) === form.cps ? text : String(form.cps)));
  }, [form.cps]);
  useEffect(() => {
    setCpsText((text) => (Number(text.replace(",", ".")) === form.cps ? text : String(form.cps)));
  }, [form.cps]);
  return (
    <div className="flex flex-col gap-3.5">
      <div className="flex items-end gap-2.5">
        {playerClass && CLASS_PORTRAITS[playerClass] && <img src={CLASS_PORTRAITS[playerClass]} alt="" width={30} height={42} className="wbr-fade flex-shrink-0" />}
        <div className="flex min-w-0 flex-1 flex-col gap-1.5">
          <label htmlFor="new-class" className={label}>
            Class
          </label>
          <select id="new-class" value={playerClass} onChange={onClassChange} className="mc-input w-full">
            <option value="">Choose a class</option>
            {Object.entries(CLASSES).map(([name, config]) => (
              <option key={name} value={name}>
                {name} ({capitalize(config.weapon)})
              </option>
            ))}
          </select>
        </div>
      </div>

      {playerClass && (
        <div className="wbr-fade grid grid-cols-[minmax(0,1fr)_5.5rem] gap-2">
          <div className="flex min-w-0 flex-col gap-1.5">
            <label htmlFor="new-rank" className={label}>
              Rank
            </label>
            <select id="new-rank" value={rankConfirmed ? rank : ""} onChange={onRank} className="mc-input w-full" title="Higher ranks unlock ability points earlier">
              <option value="">Choose</option>
              {RANKS.map((entry) => (
                <option key={entry.id} value={entry.id}>
                  {entry.label}
                  {entry.loan > 0 ? ` (+${entry.loan} AP)` : ""}
                </option>
              ))}
            </select>
          </div>
          {rankConfirmed && (
            <div className="wbr-fade flex min-w-0 flex-col gap-1.5">
              <label htmlFor="new-level" className={label}>
                Level
              </label>
              <input id="new-level" value={levelInput} onChange={onLevelInput} type="number" min={1} max={120} placeholder="1-120" className="mc-input w-full tabular-nums" />
            </div>
          )}
        </div>
      )}
      {playerClass && rankConfirmed && level && (
        <p className={`${hint} -mt-2`}>
          {availableSkillPoints(level)} skill points · {apCap} ability points
        </p>
      )}

      {playerClass && level && <SectionBar />}
      {playerClass && level && (
        <fieldset className="wbr-fade flex flex-col gap-1.5">
          <legend className={`${label} mb-1.5`}>Ability tree</legend>
          <div className="grid grid-cols-3 gap-1.5">
            {classConfig.archetypes.map((arch) => (
              <button key={arch} type="button" onClick={() => onPreset(arch)} className={`mc-btn mc-btn-sm flex w-full items-center justify-center px-1 leading-tight ${form.preset === arch ? "mc-btn-on" : ""}`} title={`Load the suggested ${arch} tree for level ${level}`}>
                {arch}
              </button>
            ))}
          </div>
          <p className={hint}>
            {treeIds.length > 0 ? (
              <>
                {treeIds.length} abilities · {treePoints}/{apCap} AP{form.preset ? "" : " · your own tree"}{" "}
                <button type="button" className="mc-link" onClick={onEditTree}>
                  Edit
                </button>
              </>
            ) : (
              "Pick a preset; spells and their costs come from the tree."
            )}
          </p>
          {onGuideTree && treePresetsFor(playerClass).length > 0 && (
            <details className="text-xs" open={Boolean(form.treePreset)}>
              <summary className="mc-link cursor-pointer">Guide trees ({treePresetsFor(playerClass, form.preset || null).length || treePresetsFor(playerClass).length})</summary>
              <div className="mt-1.5">
                <GuideTreePresets playerClass={playerClass} archetype={form.preset || null} apCap={apCap} selected={form.treePreset || null} onPick={onGuideTree} compact />
              </div>
            </details>
          )}
        </fieldset>
      )}

      {treeIds.length > 0 && goals.length > 0 && <SectionBar />}
      {treeIds.length > 0 && goals.length > 0 && (
        <div className="wbr-fade flex flex-col gap-1.5">
          <label htmlFor="new-goal" className={label}>
            Maximise
          </label>
          <select id="new-goal" value={goal ? (goal.kind === "multi" ? "multi" : String(goal.id)) : ""} onChange={(event) => event.target.value !== "multi" && set({ goal: event.target.value === DAMAGE_GOAL_MAIN || event.target.value === DAMAGE_GOAL_CYCLE ? event.target.value : Number(event.target.value) })} className="mc-input w-full">
            {goal && goal.kind === "multi" && <option value="multi">{goal.name} (sum)</option>}
            {goals.map((entry) => (
              <option key={entry.id} value={String(entry.id)}>
                {entry.name}
                {entry.kind === "melee" ? " (main attack DPS)" : entry.kind === "cycle" ? " (damage per second of the cycle)" : entry.cost !== null && entry.cost !== undefined ? ` · ${entry.cost.toFixed(0)} mana` : ""}
              </option>
            ))}
          </select>
          <div className="flex flex-wrap gap-1" role="group" aria-label="Spells to maximise together">
            {goals.filter((entry) => entry.kind !== "cycle").map((entry) => {
              const on = goalIds.some((id) => String(id) === String(entry.id));
              return (
                <ToggleChip
                  key={String(entry.id)}
                  pressed={on}
                  title={on ? (goalIds.length > 1 ? `Take ${entry.name} out of the sum` : "At least one has to stay") : `Add ${entry.name} to the sum`}
                  onClick={() => {
                    // zaznacz / odznacz; kilka zaznaczonych = maksymalizujemy sumę (jedno rzucenie każdego)
                    const ids = on ? goalIds.filter((id) => String(id) !== String(entry.id)) : [...goalIds, entry.id];
                    if (ids.length === 0) return;
                    set({ goal: ids.length === 1 ? ids[0] : ids });
                  }}
                >
                  {entry.name}
                </ToggleChip>
              );
            })}
          </div>
          <p className={hint} title="Every build is compared by this number, computed with your tree, powders and skill points.">
            {goal ? (goal.kind === "melee" ? "Main attack damage per second." : goal.kind === "cycle" ? "Every spell of the cycle once per cast plus every main attack hit (M), per second of the cycle - within the mana balance range you set." : goal.kind === "multi" ? `Sum of one cast of ${goal.name}.` : `One hit of ${goal.name}.`) : ""} Tap several to maximise their sum.
          </p>
        </div>
      )}

      {treeIds.length > 0 && <SectionBar />}
      {treeIds.length > 0 && (
        <fieldset className="wbr-fade flex flex-col gap-2.5">
          <legend className={`${label} mb-1`}>Must have</legend>
          <div className="flex flex-col gap-1">
            <RangeControl
              id="new-ehp"
              kind="ehp"
              ui={ehpUi(ehpMax)}
              value={ehpPctPair(form, ehpMax)}
              valueText={ehpValueText(form, ehpMax, true)}
              onChange={(range) => set(ehpFormPatch(range, ehpMax))}
              hint={`${ehpNumbersText(form, ehpMax)} (100% = ${formatNumber(ehpMax)}, the most level ${level || "?"} reaches with items).`}
              title="Effective HP range in 2% steps of the most your level can reach. The generator keeps only builds inside it; a maximum stops it from spending stats on more EHP than you want. Left end = no minimum, right end = no maximum."
            />
            {sweep && <p className="text-xs text-zinc-500">Builds for every EHP step: List of builds, at the bottom of this panel.</p>}
          </div>
          <RangeControl
            id="new-lr"
            kind="life"
            level={level}
            value={formLifePair(form)}
            onChange={(range) => set({ lr: range, sustain: undefined })}
            hint={lifeRangeHint(formLifePair(form), shownBuild && shownBuild.metrics ? shownBuild.metrics.hp : 0)}
            title="Life recovery per second: Health Regen ÷ 4 s + Life Steal from the cycle's main attacks (M; without a cycle, constant main attacks). The maximum stops the search from wasting stats on more life than you need."
          />
          <RangeControl
            id="new-spd"
            kind="spd"
            level={level}
            value={formSpdPair(form)}
            onChange={(range) => set({ spd: range })}
            hint={speedRangeHint(shownBuild)}
            title="Walk Speed of the whole build (items, sets, ability tree) - the number in the summary. The default minimum (−20%) keeps the search from slow builds; Any = no condition."
          />
        </fieldset>
      )}

      {treeIds.length > 0 && <SectionBar />}
      {treeIds.length > 0 && (
        <fieldset className="wbr-fade flex flex-col gap-1.5">
          <legend className={`${label} mb-1`}>Mana: spell cycle</legend>
          <div className="flex items-center gap-1.5">
            <input
              id="new-cycle"
              value={form.cycle}
              onChange={(event) => set({ cycle: event.target.value.toUpperCase().replace(/[^1-4M]/g, "").slice(0, 16) })}
              placeholder="e.g. 2343 or 4MMM"
              aria-label="Spell cycle: spell numbers 1-4, M = main attack"
              className="mc-input w-0 min-w-0 flex-1 tabular-nums"
            />
            <label htmlFor="new-cps" className="flex items-center gap-1 text-xs text-zinc-400" title="Clicks per second. A spell is 3 clicks, so the cycle takes 3 × spells ÷ clicks per second.">
              <input
                id="new-cps"
                type="number"
                min={0.5}
                max={12}
                step={0.5}
                value={cpsText}
                onChange={(event) => {
                  const text = event.target.value;
                  setCpsText(text);
                  const value = Number(text.replace(",", "."));
                  if (text.trim() !== "" && Number.isFinite(value) && value >= 0.5 && value <= 12) set({ cps: value });
                }}
                onBlur={() => setCpsText(String(form.cps))}
                className="mc-input w-14 px-1 text-center tabular-nums"
              />
              cps
            </label>
            {form.cycle && (
              <button type="button" className="mc-btn mc-btn-sm" onClick={() => set({ cycle: "" })} title="No mana filter" aria-label="Clear the spell cycle">
                ×
              </button>
            )}
          </div>
          <CheckRow checked={form.steal} onChange={() => set({ steal: !form.steal })} label="Mana Steal" hint="from M hits" title="Mana Steal works on main attack hits: add M to the cycle for every main attack between the spells. Mana per hit = Mana Steal ÷ 3 ÷ hits per second of the weapon (like Wynnbuilder)." />
          <CheckRow checked={form.gain} onChange={() => set({ gain: !form.gain })} label="Mana from abilities" title="Mana that abilities give back (e.g. from their hits) counts as income" />
          <RangeControl
            id="new-drain"
            kind="mana"
            level={level}
            value={formManaPair(form)}
            onChange={(range) => set({ drain: range })}
            disabled={cycleCasts === 0}
            disabledHint="Type a spell cycle above: without one there is no mana condition."
            hint={manaRangeHint(formManaPair(form))}
            title="The cycle's mana balance per second: negative = drain you accept (e.g. for a burst), positive = surplus. The maximum keeps the search from wasting stats on mana you never use. Raid buffs: Advanced, at the bottom of this panel."
          />
          {onTradeoff && <TradeoffSuggest tradeoff={tradeoff} hasCycle={cycleCasts > 0} running={running} form={form} onRun={onTradeoff} onUse={onTradeoffUse} onPick={onTradeoffPick} shownBuild={shownBuild} />}
          {cycleIds.length > 0 && <CycleSteps cycle={cycleText(cycleIds)} playerClass={playerClass} spells={goals.filter((entry) => entry.kind === "spell" && typeof entry.id === "number" && entry.id <= 4)} compact />}
          <p className={hint}>
            {cycleIds.length > 0
              ? `${cycleCasts} spell${cycleCasts === 1 ? "" : "s"}${cycleMelee > 0 ? ` + ${cycleMelee} main attack${cycleMelee === 1 ? "" : "s"}` : ""} every ≈${((3 * cycleCasts) / Math.max(0.5, form.cps) + cycleMelee / Math.max(0.5, form.cps)).toFixed(1)} s, mana balance ${rangeValueText(formManaPair(form), rangeUi("mana", level))}.${cycleMelee === 0 && form.steal ? " No M = no Mana Steal." : ""}${Number(form.raidMana) > 0 ? ` Raid buff +${Number(form.raidMana)} mana/s counted (Advanced).` : ""}`
              : "Empty = no mana filter. 1-4 = spells, M = main attack (Mana Steal only works on hits)."}
          </p>
        </fieldset>
      )}

      {treeIds.length > 0 && <SectionBar />}
      {treeIds.length > 0 && (
        <fieldset className="wbr-fade flex flex-col gap-1">
          <legend className={`${label} mb-1`}>Items</legend>
          <span className={SUB_HEAD}>Filters</span>
          <div className="flex flex-col gap-1.5">
            <CheckRow id="new-no-events" checked={form.noEvents !== false} onChange={() => set({ noEvents: form.noEvents === false })} label="No limited-time event items" title={`Skips the ${EVENT_ITEM_NAMES.size} items you can only get during a festival (Blizzard, Bonfire, Heroes, Spirits). Pinned items stay.`} />
            <CheckRow id="new-tradeable" checked={Boolean(form.tradeable)} onChange={() => set({ tradeable: !form.tradeable })} label="Tradeable only" hint="Trade Market" title="Only items that can be bought and sold on the Trade Market: no untradable or quest items. Pinned items stay." />
            <ItemFilterChecks options={options} onChange={onOptions} />
          </div>
          <span className={`${SUB_HEAD} mt-2`}>How builds are counted</span>
          <div className="flex flex-col gap-1.5">
            <CheckRow id="new-free-sp" checked={form.freeSp !== false} onChange={() => set({ freeSp: form.freeSp === false })} label="Spend free skill points" hint="shown as (+X)" title="When the set needs fewer skill points than your level gives, spend the rest where they raise the goal most (or first where they get the build over the filters). Off: the rest stays unspent, like a fresh build in Wynnbuilder." />
            <CheckRow id="new-rolls" checked={form.rolls === "avg"} onChange={() => set({ rolls: form.rolls === "avg" ? "max" : "avg" })} label="Realistic rolls (50%)" hint="off = max, like Wynnbuilder" title="Off (default): identifications at their maximum roll, like Wynnbuilder. On: every rolled ID at 50% - then items with fixed IDs (mostly quest rewards) get an edge, because they always count at 100%." />
            <CheckRow id="new-poison" checked={Boolean(form.poison)} onChange={() => set({ poison: !form.poison })} label="Count poison in the goal" title="Adds Poison per second to the goal (spread over the casts for a spell). Off by default: how poison stacks and works on bosses isn't known, and counting it made the search pick poison-only items. The Poison DPS row in the Damage panel is always shown." />
          </div>
          <div className="mt-2">
            <ItemFilters options={options} onChange={onOptions} weaponType={classConfig ? classConfig.weapon : null} level={level || 120} onBrowse={onBrowse} />
          </div>
          <div className="mt-2">
            <WeaponPowdersControl options={options} onChange={onOptions} />
          </div>
        </fieldset>
      )}
      <SectionBar />

      <div className="flex flex-col gap-1.5">
        <button
          type="button"
          onClick={onGenerate}
          disabled={running || !ready}
          className="mc-btn mc-btn-primary w-full py-2.5 text-lg"
          style={ts(ready ? undefined : { opacity: 0.55 })}
          title={ready ? undefined : "Choose a class, rank, level and ability tree first"}
        >
          {running ? "Searching…" : "Generate Build"}
        </button>
        {running ? (
          <div className="flex flex-col gap-1" role="status" aria-live="polite">
            <div className="h-1.5 w-full" style={ts({ background: "#2b2b2b" })}>
              <div className="h-full transition-all" style={ts({ width: `${Math.round(((progress && progress.fraction) || 0) * 100)}%`, background: "#55FF55" })} />
            </div>
            <div className="flex items-center gap-2">
              <p className={`${hint} min-w-0 flex-1 truncate`}>
                {progress ? progress.label : "Searching"}…{progress && progress.threads > 1 ? ` · ${progress.threads} threads` : ""}
              </p>
              {onStop && (
                <button type="button" className="mc-btn mc-btn-sm" onClick={onStop} title="Stop the search and keep the previous build">
                  Stop
                </button>
              )}
            </div>
          </div>
        ) : outdated ? (
          <p className="text-xs text-amber-400">Settings changed: regenerate.</p>
        ) : result ? (
          <p className={hint} title={`Generated at ${result.at.toLocaleTimeString("en-GB")}`}>
            Build #{result.run} · <span className="tabular-nums">{(result.ms / 1000).toFixed(1)}</span> s
            {result.build.stats && result.build.stats.threads > 1 ? ` · ${result.build.stats.threads} threads` : ""}
          </p>
        ) : (
          <p className={hint}>{ready ? "Damage first: the filters above are pass/fail." : !playerClass ? "Start with a class." : !rankConfirmed ? "Next: your rank." : !level ? "Next: your level." : "Next: an ability tree preset."}</p>
        )}
      </div>
      {sweep && (
        <div className="flex flex-col gap-1">
          <button type="button" className="mc-link self-start text-xs" aria-expanded={sweepOpen} onClick={onSweepToggle}>
            {sweepOpen ? "▾ List of builds for every EHP step" : "▸ List of builds for every EHP step (compare)"}
          </button>
          {sweepOpen && <EhpSweepList sweep={sweep} shownBuild={shownBuild} onPick={onSweepPick} />}
        </div>
      )}
      {treeIds.length > 0 && (
        <details className="text-xs" open={Number(form.raidMana) > 0}>
          <summary className="mc-link cursor-pointer">
            Advanced{Number(form.raidMana) > 0 ? ` · raid buff +${Number(form.raidMana)} mana/s` : ""}
          </summary>
          <div className="mt-2 flex flex-col gap-1.5">
            <label className="grid grid-cols-[minmax(0,1fr)_4.5rem_3.5rem] items-center gap-2 text-zinc-300" title="Extra mana per second from buffs in a raid (a support's mana aura, raid blessings), added to the cycle's mana income. 0 = off.">
              <span>Raid mana buff</span>
              <input
                id="new-raid-mana"
                type="number"
                min={0}
                max={30}
                step={0.5}
                value={Number(form.raidMana) || 0}
                onChange={(event) => {
                  const value = Number(String(event.target.value).replace(",", "."));
                  set({ raidMana: Number.isFinite(value) ? Math.min(30, Math.max(0, value)) : 0 });
                }}
                className="mc-input w-full px-1 text-center tabular-nums"
              />
              <span className="text-zinc-500">mana/s</span>
            </label>
            <p className="text-zinc-500">
              Optional. In raids your team's buffs give extra mana: type how much per second and the mana filter, the drain suggestion and the list of
              builds count it as income. There is no single value for every raid and team, so it is off by default.
            </p>
          </div>
        </details>
      )}
    </div>
  );
}

// Cykl czarów narysowany krok po kroku: numer czaru, nazwa (pogrubiona), kombinacja kliknięć i mana, połączone
// strzałkami - tak, żeby od razu było widać, co i w jakiej kolejności rzucać. M = atak podstawowy, F = ultimate.
function CycleSteps({ cycle, playerClass, spells = [], names = null, compact = false }) {
  const clicks = SPELL_CLICKS[playerClass] || SPELL_CLICKS.default;
  const spellNames = names || CLASS_SPELL_NAMES[playerClass] || [];
  const steps = [...String(cycle || "")].filter((char) => "1234MF".includes(char));
  if (steps.length === 0) return null;
  return (
    <ol className="flex flex-wrap items-center gap-x-1 gap-y-1.5" aria-label="Spell cycle, in order">
      {steps.map((char, index) => {
        const id = Number(char);
        const spell = id ? spells.find((entry) => entry.id === id) : null;
        const main = char === "M";
        const ult = char === "F";
        const color = main ? "#FFAA00" : ult ? "#FF55FF" : "#55FFFF";
        const name = main ? "Main attack" : ult ? "Ultimate" : spell ? spell.name : spellNames[id - 1] || `Spell ${id}`;
        const combo = main ? (playerClass === "Archer" ? "R" : "L") : ult ? "F" : clicks[id - 1];
        const cost = spell && spell.cost !== null && spell.cost !== undefined ? spell.cost : null;
        return (
          <li key={index} className="flex items-center gap-1">
            {index > 0 && (
              <span className="text-base font-bold" style={ts({ color: "#FFAA00" })} aria-hidden="true">
                ➜
              </span>
            )}
            <span className="wbr-step mc-slot flex items-center gap-1.5 px-1.5 py-0.5" title={cost !== null ? `${name}: ${combo}, ${cost.toFixed(1)} mana` : `${name}: ${combo}`}>
              <span className="flex h-5 min-w-[1.25rem] items-center justify-center px-1 text-xs font-bold" style={{ ...ts({ background: color }), color: THEME === "light" ? "#FFFFFF" : "#101228", textShadow: "none" }}>
                {main ? "M" : ult ? "F" : id}
              </span>
              <span className={`${compact ? "text-xs" : "text-sm"} font-bold`} style={ts({ color })}>
                {name}
              </span>
              {!compact && <span className="text-xs text-zinc-500">{combo}</span>}
              {!compact && cost !== null && <span className="text-xs tabular-nums text-zinc-400">{cost.toFixed(0)}</span>}
            </span>
          </li>
        );
      })}
    </ol>
  );
}

// Ekran startowy: pięć klas z portretami - klik wybiera klasę (to samo co lista w formularzu).
// ============================ KREATOR PIERWSZEGO BUILDU ============================
// Po wyborze klasy główny panel prowadzi krok po kroku, tak jak wybór klasy: każda opcja to kafelek do kliknięcia
// (ranga, poziom, drzewko, cel, próg EHP, cykl many, dodatki), a na końcu podsumowanie i Generate. Formularz po
// lewej pokazuje te same ustawienia, więc można przełączać się między nimi w dowolnym momencie.
const WIZARD_LEVELS = [20, 30, 40, 50, 60, 70, 80, 90, 100, 105, 110, 120];
const WIZARD_EHP = [
  { pct: 0, label: "Glass cannon", hint: "No minimum - pure damage" },
  { pct: 10, label: "Fragile", hint: "A little safety" },
  { pct: 20, label: "Light", hint: "Some survivability" },
  { pct: 25, label: "Balanced", hint: "The default" },
  { pct: 35, label: "Sturdy", hint: "Noticeably tankier" },
  { pct: 50, label: "Tank", hint: "Half of the most EHP you can reach" },
  { pct: 70, label: "Wall", hint: "Survival first" },
];
const WIZARD_STEPS = [
  { id: "class", label: "Class" },
  { id: "rank", label: "Rank" },
  { id: "level", label: "Level" },
  { id: "tree", label: "Ability tree" },
  { id: "goal", label: "Maximise" },
  { id: "ehp", label: "Effective HP" },
  { id: "mana", label: "Mana" },
  { id: "extras", label: "Extras" },
  { id: "generate", label: "Generate" },
];

const WIZARD_CPS = [2, 3, 4, 5, 6, 8];
// dopuszczalny dren many: pełny sustain, lekki (długie walki), mocny, "burst" (pula znika w kilkanaście sekund)
const WIZARD_DRAIN = [
  [0, "Full sustain"],
  [1, "Slight"],
  [3, "Heavy"],
  [8, "Burst"],
];

function WizardTile({ selected = false, onClick, children, className = "", title = undefined, disabled = false }) {
  return (
    <button type="button" onClick={onClick} disabled={disabled} title={title} aria-pressed={selected} className={`wbr-tile mc-slot flex flex-col items-center gap-1 p-3 text-center ${selected ? "wbr-tile-on" : ""} ${className}`}>
      {children}
    </button>
  );
}

// Podpowiedź pod wynikiem: zamiana Mastery na żywioł broni (np. bolt hybrid: Divzer -> Thunder, Epoch -> Air).
function MasterySwapHint({ build, apCap, onApply, disabled = false }) {
  const swap = useMemo(() => {
    try {
      return masterySwapSuggestion(build, apCap);
    } catch (error) {
      return null;
    }
  }, [build, apCap]);
  if (!swap) return null;
  const weapon = (build.slots.find((slot) => slot.id === "weapon") || {}).item;
  return (
    <p className="text-sm text-zinc-300" title="Same items and skill points, only the tree changes. Regenerating can pick items that fit the new Mastery even better.">
      <span className="font-semibold" style={{ color: "#55FFFF" }}>Tree tip:</span> swap <b>{swap.from}</b> for <b>{swap.to}</b>
      {swap.weaponElement && weapon ? ` (${weapon.name} deals ${swap.to.replace(" Mastery", "")} damage)` : ""}: <b className="text-green-400">+{(swap.gain * 100).toFixed(1)}%</b> {goalLabelOf(build)} with this build.{" "}
      <button type="button" className="mc-btn mc-btn-sm" disabled={disabled} onClick={() => onApply(swap)}>
        Swap &amp; regenerate
      </button>
    </p>
  );
}

// Presety drzewek z poradnika: kafelki (kreator) albo zwarta lista (panel), z wyszukiwaniem po nazwach graczy.
function GuideTreePresets({ playerClass, archetype, apCap, selected, onPick, compact = false }) {
  const [query, setQuery] = useState("");
  const all = treePresetsFor(playerClass);
  if (all.length === 0) return null;
  const shown = query.trim() ? all.filter((preset) => presetMatches(preset, query)) : all.filter((preset) => !archetype || preset.archetype === archetype);
  const others = !query.trim() && archetype ? all.length - shown.length : 0;
  const missing = archetype && !all.some((preset) => preset.archetype === archetype);
  return (
    <div className="flex min-w-0 flex-col gap-2">
      <div className={compact ? "flex min-w-0 flex-col gap-1" : "flex flex-wrap items-center gap-2"}>
        <span className={compact ? "text-xs text-zinc-300" : "text-sm text-zinc-300"}>Guide trees{archetype && !query.trim() ? ` · ${archetype}` : ""}</span>
        <input
          type="search"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder="generalist, bolt hybrid, divzer…"
          aria-label="Search guide trees by build name, variant or weapon"
          className={compact ? "mc-input w-full min-w-0 text-xs" : "mc-input min-w-0 flex-1 text-xs"}
          style={{ maxWidth: compact ? undefined : "18rem" }}
        />
      </div>
      {missing && !query.trim() && <p className="text-xs text-zinc-500">No current guide tree for {archetype} (the guide's trees are from an older game version) - the suggested tree is used. Search to see other archetypes.</p>}
      {shown.length === 0 && query.trim() && <p className="text-xs text-zinc-500">No guide tree matches "{query}".</p>}
      <div className={compact ? "flex flex-col gap-1" : "grid grid-cols-1 gap-2 sm:grid-cols-2 xl:grid-cols-3"}>
        {shown.map((preset) => {
          const on = selected === preset.id;
          const trimmed = preset.points > apCap;
          const title = `${preset.builds.join(", ")}. ${preset.points} AP${trimmed ? `; your ${apCap} AP keep the most useful part of it (the full tree comes back when you level up)` : ""}.${preset.cycle ? ` Guide cycle: ${preset.cycle.name} (${preset.cycle.cycle}).` : ""}`;
          return compact ? (
            <button key={preset.id} type="button" onClick={() => onPick(preset)} title={title} className={`mc-btn mc-btn-sm w-full min-w-0 justify-start overflow-hidden text-left ${on ? "mc-btn-on" : ""}`}>
              <span className="min-w-0 truncate">
                {preset.name}
                <span className="text-zinc-500"> · {preset.weapons.slice(0, 2).join(", ")}{preset.weapons.length > 2 ? "…" : ""}{trimmed ? ` · trimmed to ${apCap} AP` : ""}</span>
              </span>
            </button>
          ) : (
            <WizardTile key={preset.id} selected={on} onClick={() => onPick(preset)} className="items-start text-left" title={title}>
              <span className="text-base font-bold text-zinc-100">
                {preset.name}
                {(query.trim() || !archetype) && <span className="ml-1.5 text-xs font-normal text-zinc-500">{preset.archetype}</span>}
              </span>
              {preset.aliases.length > 0 && <span className="text-xs text-zinc-400">also: {preset.aliases.join(", ")}</span>}
              <span className="text-xs text-zinc-400">
                with {preset.weapons.slice(0, 4).join(", ")}
                {preset.weapons.length > 4 ? ` +${preset.weapons.length - 4}` : ""}
              </span>
              <span className="text-xs text-zinc-500">
                {preset.masteries.length > 0 ? `${preset.masteries.join(" / ")} Mastery · ` : ""}
                {trimmed ? `${preset.points} AP → your ${apCap} AP` : `${preset.points} AP`}
                {preset.cycle ? ` · cycle ${preset.cycle.cycle}` : ""}
              </span>
            </WizardTile>
          );
        })}
      </div>
      {others > 0 && <p className="text-xs text-zinc-500">{others} more for other {playerClass} archetypes - search to see them.</p>}
    </div>
  );
}

function SetupWizard({ playerClass, onClassReset, rank, rankConfirmed, onRank, level, levelInput, onLevelInput, treeIds, apCap, preset, onPreset, onGuideTree = null, treePreset = null, onEditTree, renderTree = null, goals, goal, form, onForm, ehpMax, options, onOptions, onGenerate, running, progress, onStop = null, treeSettings }) {
  const ts = useTs();
  const classConfig = CLASSES[playerClass];
  const firstOpen = !rankConfirmed ? "rank" : !level ? "level" : treeIds.length === 0 ? "tree" : null;
  const [view, setView] = useState(null);
  const active = view || firstOpen || "goal";
  const order = WIZARD_STEPS.map((entry) => entry.id);
  const next = (from) => setView(order[Math.min(order.length - 1, order.indexOf(from) + 1)]);
  const previous = (from) => {
    const index = order.indexOf(from);
    if (index <= 1) onClassReset();
    else setView(order[index - 1]);
  };
  const [treeShown, setTreeShown] = useState(true);
  // kliknięcia/s wpisywane ręcznie (pole trzyma tekst, żeby dało się je wyczyścić i wpisać nową liczbę)
  const [cpsText, setCpsText] = useState(String(form.cps));
  useEffect(() => {
    setCpsText(String(form.cps));
  }, [form.cps]);
  const treeResolved = useMemo(() => (treeIds.length > 0 && TREE_INDEX[playerClass] ? resolveTree(TREE_INDEX[playerClass], treeIds) : null), [playerClass, treeIds]);
  const set = (patch) => onForm((current) => ({ ...current, ...patch }));
  const step = ehpStep(ehpMax);
  const minEhp = form.minEhp === null || form.minEhp === undefined ? defaultMinEhp(ehpMax) : Math.min(form.minEhp, ehpMax);
  const cycleDigits = [...cycleText(parseCycle(form.cycle))];
  const preview = useMemo(() => (level && treeIds.length > 0 ? classPreview(playerClass, level, treeSettings) : null), [playerClass, level, treeIds, treeSettings]);
  const spells = preview ? preview.stats.spells : [];
  const combos = preset && ARCHETYPE_COMBOS[preset] ? ARCHETYPE_COMBOS[preset].combos : [];
  const [customCycle, setCustomCycle] = useState(() => cycleText(parseCycle(form.cycle)));
  const cycleOf = (text) => cycleText(parseCycle(text));
  const cyclePresets = (() => {
    const list = combos.filter((entry) => /[1-4]/.test(entry.cycle)).map((entry) => ({ ...entry, source: null }));
    const seen = new Set(list.map((entry) => cycleOf(entry.cycle)));
    spells
      .filter((spell) => spell.id >= 1 && spell.id <= 4 && spell.cost !== null && spell.cost !== undefined && spell.main && spell.main.type === "damage")
      .forEach((spell) => {
        const cycle = String(spell.id).repeat(3);
        if (seen.has(cycle) || seen.has(String(spell.id))) return;
        seen.add(cycle);
        list.push({ name: `${spell.name} spam`, cycle, note: `Only ${spell.name}, cast again and again.`, source: null });
      });
    return list;
  })();
  const otherCyclePresets = classConfig.archetypes
    .filter((arch) => arch !== preset && ARCHETYPE_COMBOS[arch])
    .flatMap((arch) => ARCHETYPE_COMBOS[arch].combos.filter((entry) => /[1-4]/.test(entry.cycle)).map((entry) => ({ ...entry, source: arch })));
  const customMana = customCycle ? cycleMana(spells, parseCycle(customCycle), form.cps, form.gain, drainOfRange(formManaRange(form))) : null;
  const customSelected = cycleDigits.length > 0 && cycleDigits.join("") === customCycle && ![...cyclePresets, ...otherCyclePresets].some((entry) => cycleOf(entry.cycle) === customCycle);
  const renderCyclePreset = (entry) => {
    const digits = parseCycle(entry.cycle);
    const mana = cycleMana(spells, digits, form.cps, form.gain, drainOfRange(formManaRange(form)));
    return (
      <WizardTile
        key={`${entry.source || ""}:${entry.name}`}
        selected={cycleDigits.join("") === cycleText(digits)}
        onClick={() => {
          set({ cycle: cycleText(digits) });
          setCustomCycle(cycleText(digits));
          next("mana");
        }}
        className="items-start text-left"
        title={entry.note}
      >
        <span className="text-base font-bold text-zinc-100">
          {entry.name}
          {entry.source && <span className="ml-1.5 text-xs font-normal text-zinc-500">{entry.source}</span>}
        </span>
        <CycleSteps cycle={entry.cycle} playerClass={playerClass} spells={spells} compact />
        <span className="text-xs text-zinc-500">
          {mana ? cycleManaText(mana, form.cps) : "Some of these spells aren't in your tree yet."}
        </span>
      </WizardTile>
    );
  };
  const selectedGoals = goal ? (Array.isArray(goal.id) ? goal.id : [goal.id]) : [];
  const normalized = normalizeOptions(options);
  const reachable = (index) => {
    const id = order[index];
    if (id === "class" || id === "rank") return true;
    if (id === "level") return rankConfirmed;
    if (id === "tree") return rankConfirmed && Boolean(level);
    return rankConfirmed && Boolean(level) && treeIds.length > 0;
  };
  const summary = {
    class: playerClass,
    rank: rankConfirmed ? (RANKS.find((entry) => entry.id === rank) || RANKS[0]).label : null,
    level: level ? `Lv ${level}` : null,
    tree: treeIds.length > 0 ? preset || "own tree" : null,
    goal: goal ? goal.name : null,
    ehp: treeIds.length > 0 ? rangeValueText(ehpPctPair(form, ehpMax), ehpUi(ehpMax)) : null,
    mana: treeIds.length > 0 ? `${cycleDigits.length ? `${cycleDigits.join("")} · ${form.cps} cps · ${rangeValueText(formManaPair(form), rangeUi("mana", level))}` : "off"}${formLifeRange(form) ? ` · life ${rangeValueText(formLifePair(form), rangeUi("life", level))}` : ""}` : null,
    extras: treeIds.length > 0 ? [formSpdRange(form) ? `walk ${rangeValueText(formSpdPair(form), rangeUi("spd", level))}` : "any walk speed", form.noEvents !== false ? "no events" : null, form.tradeable ? "tradeable" : null, normalized.avoidNegativeDefences ? "no -def" : null, form.rolls === "avg" ? "50% rolls" : null, form.poison ? "poison" : null].filter(Boolean).join(", ") || "none" : null,
    generate: null,
  };
  const heading = {
    rank: ["Your rank", "Higher ranks lend ability points earlier (VIP+ 2 AP, HERO and above 4 AP)."],
    level: ["Your level", "Items above it are left out; skill points and ability points come from it."],
    tree: ["Ability tree", `Pick an archetype - its suggested tree for ${apCap} AP is shown below, where you can compare archetypes and click abilities to change it. "Use this tree" or Next goes on.`],
    goal: ["What to maximise", "One spell (one cast, crits included), the main attack (damage per second) - or click several to maximise their sum. Numbers: with the best weapon for your level alone."],
    ehp: ["How tanky", `Effective HP range in 2% steps of the most your level can reach (${formatNumber(ehpMax)}). Builds outside it are thrown away; the maximum is optional.`],
    mana: ["Mana: spell cycle", "The spells (1-4) and main attacks (M) you do in a loop must pay for themselves (Mana Regen, Mana Steal from M hits, ability mana), within the mana balance range: the minimum is the drain you accept, the maximum stops the search from wasting stats on mana. Type your own cycle or pick a preset."],
    extras: ["Extras", "Optional filters - click to toggle."],
    generate: ["Ready", "The search runs until a pass finds nothing better: usually 5-30 s, up to ~1.5 min at level 100+ with a high EHP threshold and a mana cycle. You can change anything later in the panel on the left."],
  }[active] || ["", ""];

  return (
    <section className="mc-panel wbr-fade flex flex-col gap-4 p-5">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <button type="button" className="mc-btn min-w-[6.5rem] justify-center" onClick={() => previous(active)} title={active === "rank" ? "Back to the class choice" : `Back to: ${(WIZARD_STEPS[order.indexOf(active) - 1] || {}).label || ""}`}>
          ‹ Previous
        </button>
        <span className="hidden text-xs text-zinc-500 sm:block">
          Step {order.indexOf(active) + 1} of {order.length}
        </span>
        <div className="flex flex-wrap items-center justify-end gap-2">
          {active !== "rank" && active !== "generate" && firstOpen === null && (
            <button type="button" className="mc-btn min-w-[6.5rem] justify-center" onClick={onGenerate} disabled={running} title="Everything after the tree has a sensible default - you can generate right away.">
              {running ? "Searching…" : "Generate now"}
            </button>
          )}
          {active !== "generate" && (
            <button type="button" className="mc-btn mc-btn-primary min-w-[6.5rem] justify-center" onClick={() => next(active)} disabled={!reachable(order.indexOf(active) + 1)}>
              Next ›
            </button>
          )}
        </div>
      </div>
      <ol className="flex flex-wrap gap-1.5" aria-label="Setup steps">
        {WIZARD_STEPS.map((entry, index) => {
          const done = Boolean(summary[entry.id]);
          const current = entry.id === active;
          const can = reachable(index);
          return (
            <li key={entry.id}>
              <button
                type="button"
                disabled={!can}
                onClick={() => (entry.id === "class" ? onClassReset() : setView(entry.id))}
                className={`wbr-step ${current ? "wbr-step-on" : done ? "wbr-step-done" : ""}`}
                title={summary[entry.id] ? `${entry.label}: ${summary[entry.id]}` : entry.label}
              >
                <span className="wbr-step-num">{done && !current ? "✓" : index + 1}</span>
                {entry.label}
                {summary[entry.id] && <span className="wbr-step-value">{summary[entry.id]}</span>}
              </button>
            </li>
          );
        })}
      </ol>

      <div className="flex flex-col gap-1">
        <h2 className="mc-title text-xl">{heading[0]}</h2>
        <p className="text-sm text-zinc-300">{heading[1]}</p>
      </div>

      {active === "rank" && (
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
          {RANKS.map((entry) => (
            <WizardTile
              key={entry.id}
              selected={rankConfirmed && rank === entry.id}
              onClick={() => {
                onRank({ target: { value: entry.id } });
                next("rank");
              }}
            >
              <span className="text-base font-bold text-zinc-100">{entry.label}</span>
              <span className="text-xs text-zinc-400">{entry.loan ? `+${entry.loan} ability points` : "no AP loan"}</span>
            </WizardTile>
          ))}
        </div>
      )}

      {active === "level" && (
        <div className="flex flex-col gap-3">
          <div className="grid grid-cols-3 gap-2 sm:grid-cols-4 xl:grid-cols-6">
            {WIZARD_LEVELS.map((value) => (
              <WizardTile
                key={value}
                selected={level === value}
                onClick={() => {
                  onLevelInput({ target: { value: String(value) } });
                  next("level");
                }}
              >
                <span className="text-base font-bold text-zinc-100">{value}</span>
                <span className="text-xs text-zinc-500">{availableSkillPoints(value)} SP</span>
              </WizardTile>
            ))}
          </div>
          <label className="flex items-center gap-2 text-sm text-zinc-300">
            Other level
            <input
              type="number"
              min={1}
              max={120}
              value={levelInput}
              onChange={(event) => {
                // Zostań na kroku poziomu podczas pisania: "7" to już poprawny poziom, więc bez tego kreator
                // przeskakiwał do drzewka po pierwszej cyfrze "76". Dalej tylko Enter albo "Next".
                setView("level");
                onLevelInput(event);
              }}
              onKeyDown={(event) => event.key === "Enter" && level && next("level")}
              placeholder="1-120"
              className="mc-input w-24 tabular-nums"
            />
            {level && !WIZARD_LEVELS.includes(level) && (
              <button type="button" className="mc-btn mc-btn-sm" onClick={() => next("level")}>
                Next ›
              </button>
            )}
          </label>
        </div>
      )}

      {active === "tree" && (
        <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">
          {classConfig.archetypes.map((arch) => (
            <WizardTile
              key={arch}
              selected={preset === arch && treeIds.length > 0}
              onClick={() => {
                // zostajemy na kroku drzewka: pod kafelkami widać wczytane drzewko, dalej przyciskiem Next
                setView("tree");
                onPreset(arch);
                setTreeShown(true);
              }}
              title={ARCHETYPES[arch] ? ARCHETYPES[arch].focus : undefined}
            >
              {CLASS_PORTRAITS[playerClass] && <img src={CLASS_PORTRAITS[playerClass]} alt="" width={34} height={48} />}
              <span className="text-base font-bold text-zinc-100">{arch}</span>
              <span className="text-xs text-zinc-400">{ARCHETYPE_TAGLINES[arch] || ""}</span>
              <span className="text-xs text-zinc-500">{ARCHETYPES[arch] ? ARCHETYPES[arch].focus : ""}</span>
            </WizardTile>
          ))}
          <WizardTile
            selected={treeIds.length > 0 && !preset}
            onClick={onEditTree}
            title="Pick the abilities yourself in the Ability tree tab (or paste a Wynnbuilder tree code there), then come back to this tab"
          >
            <span className="text-2xl" aria-hidden="true">
              ❋
            </span>
            <span className="text-base font-bold text-zinc-100">Your own tree</span>
            <span className="text-xs text-zinc-400">Custom - pick abilities yourself</span>
            <span className="text-xs text-zinc-500">{treeIds.length > 0 && !preset ? `${treeIds.length} abilities chosen` : "Opens the Ability tree tab; your tree is used as soon as you come back"}</span>
          </WizardTile>
          {onGuideTree && treePresetsFor(playerClass).length > 0 && (
            <div className="sm:col-span-2 xl:col-span-4">
              <GuideTreePresets
                playerClass={playerClass}
                archetype={preset || null}
                apCap={apCap}
                selected={treePreset}
                onPick={(entry) => {
                  setView("tree");
                  onGuideTree(entry);
                  setTreeShown(true);
                }}
              />
            </div>
          )}
          {treeIds.length > 0 && (
            <div className="flex flex-col gap-2 sm:col-span-2 xl:col-span-4">
              <div className="flex flex-wrap items-center justify-between gap-2">
                <span className="text-sm text-zinc-300">
                  <b className="mc-gold">{preset ? `${treePreset ? (allTreePresets().find((entry) => entry.id === treePreset) || { name: preset }).name : preset} tree` : "Your own tree"}</b> · {treeIds.length} abilities
                  {treeResolved ? ` · ${treeResolved.points} / ${apCap} AP` : ""}
                </span>
                <div className="flex flex-wrap gap-2">
                  {renderTree && (
                    <button type="button" className="mc-btn mc-btn-sm" onClick={() => setTreeShown(!treeShown)} aria-expanded={treeShown}>
                      {treeShown ? "▾ Hide the tree" : "▸ Show the tree"}
                    </button>
                  )}
                  <button type="button" className="mc-btn mc-btn-primary mc-btn-sm" onClick={() => next("tree")}>
                    Use this tree ›
                  </button>
                </div>
              </div>
              {renderTree && treeShown && (
                <div className="wbr-fade">
                  {renderTree()}
                  <p className="mt-1 text-xs text-zinc-500">Click abilities to change the tree - it becomes your own tree. Pick another archetype above to compare.</p>
                </div>
              )}
            </div>
          )}
        </div>
      )}

      {active === "goal" && (
        <div className="flex flex-col gap-3">
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 xl:grid-cols-4">
          {goals.map((entry, index) => (
            <WizardTile
              key={String(entry.id)}
              selected={selectedGoals.some((id) => String(id) === String(entry.id))}
              onClick={() => {
                // kliknięcie zaznacza / odznacza; kilka zaznaczonych = maksymalizujemy ich sumę
                const on = selectedGoals.some((id) => String(id) === String(entry.id));
                // cały cykl to inna jednostka (obrażenia na sekundę cyklu) - wybierany sam, nie w sumie
                if (entry.kind === "cycle" || selectedGoals.some((id) => isCycleGoal(id))) {
                  set({ goal: on ? null : entry.id });
                  return;
                }
                const ids = on ? selectedGoals.filter((id) => String(id) !== String(entry.id)) : [...selectedGoals, entry.id];
                if (ids.length === 0) return;
                set({ goal: ids.length === 1 ? ids[0] : ids });
              }}
            >
              <span className="text-base font-bold text-zinc-100">{entry.name}</span>
              <span className="text-sm tabular-nums" style={ts({ color: "#FFAA00" })}>
                ≈ {formatNumber(Math.round(entry.damage))}
                {entry.kind === "melee" ? " /s" : ""}
              </span>
              <span className="text-xs text-zinc-500">
                {entry.kind === "melee" ? "main attack DPS" : entry.cost !== null && entry.cost !== undefined ? `${entry.cost.toFixed(0)} mana` : "spell"}
                {index === 0 ? " · strongest" : ""}
              </span>
            </WizardTile>
          ))}
        </div>
          <div className="flex flex-wrap items-center justify-between gap-2">
            <span className="text-sm text-zinc-400">
              {selectedGoals.length > 1 ? (
                <>
                  Maximising the sum of <b className="mc-gold">{goal ? goal.name : ""}</b> (one cast of each).
                </>
              ) : (
                "Click more spells to maximise several at once (their sum)."
              )}
            </span>
          </div>
        </div>
      )}

      {active === "ehp" && (
        <div className="flex flex-col gap-4">
          <RangeControl
            id="wiz-ehp"
            kind="ehp"
            heading
            ui={ehpUi(ehpMax)}
            value={ehpPctPair(form, ehpMax)}
            valueText={ehpValueText(form, ehpMax)}
            onChange={(range) => set(ehpFormPatch(range, ehpMax))}
            hint="Drag the left handle for the minimum and the right one for a maximum (optional). The far ends = no limit on that side."
          />
          <SectionBar wide />
          <h3 className={SECTION_HEAD}>
            Quick picks <span className="text-sm normal-case text-zinc-400">(minimum; the maximum stays)</span>
          </h3>
          <div className="grid grid-cols-2 gap-2 sm:grid-cols-4 xl:grid-cols-7">
            {WIZARD_EHP.map((entry) => {
              const value = entry.pct === 25 ? defaultMinEhp(ehpMax) : Math.round((entry.pct / 100) * ehpMax);
              const currentMin = ehpPctPair(form, ehpMax).min;
              return (
                <WizardTile
                  key={entry.pct}
                  selected={(currentMin || 0) === entry.pct}
                  onClick={() => {
                    const max = formMaxEhp(form, ehpMax);
                    set({ minEhp: value, maxEhp: max !== null && max < value ? null : max });
                    next("ehp");
                  }}
                  title={entry.hint}
                  className="p-2"
                >
                  <span className="text-base font-bold text-zinc-100">{entry.label}</span>
                  <span className="text-sm tabular-nums" style={ts({ color: "#55FF55" })}>
                    {entry.pct === 0 ? "any" : `≥ ${formatNumber(value)}`}
                  </span>
                  <span className="text-xs text-zinc-500">{entry.pct}%</span>
                </WizardTile>
              );
            })}
          </div>
        </div>
      )}

      {active === "mana" && (
        <div className="flex flex-col gap-4">
          <div className="flex flex-col gap-2">
            <label htmlFor="wizard-cps" className={SECTION_HEAD}>
              Clicks per second
            </label>
            <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
              <span className="flex items-center gap-2">
                <input
                  id="wizard-cps"
                  type="number"
                  min={0.5}
                  max={12}
                  step={0.5}
                  value={cpsText}
                  onChange={(event) => {
                    const text = event.target.value;
                    setCpsText(text);
                    const value = Number(text.replace(",", "."));
                    if (text.trim() !== "" && Number.isFinite(value) && value >= 0.5 && value <= 12) set({ cps: value });
                  }}
                  onBlur={() => setCpsText(String(form.cps))}
                  className="mc-input w-20 text-center tabular-nums"
                  aria-label="Clicks per second"
                />
                <span className="text-xs text-zinc-500">a spell = 3 clicks · {(3 / Math.max(0.5, form.cps)).toFixed(2)} s</span>
              </span>
              <CheckRow checked={form.steal} onChange={() => set({ steal: !form.steal })} label="Mana Steal" hint="from M hits" title="Mana Steal only works on main attack hits - add M to the cycle" />
              <CheckRow checked={form.gain} onChange={() => set({ gain: !form.gain })} label="Mana from abilities" />
            </div>
          </div>
          <SectionBar wide />
          <RangeControl id="wiz-drain" kind="mana" level={level} heading value={formManaPair(form)} onChange={(range) => set({ drain: range })} hint={manaRangeHint(formManaPair(form))} title="The cycle's mana balance per second: negative = drain you accept, positive = surplus. The maximum keeps the search from wasting stats on mana." />
          <SectionBar wide />
          <RangeControl id="wiz-lr" kind="life" level={level} heading value={formLifePair(form)} onChange={(range) => set({ lr: range, sustain: undefined })} hint={lifeRangeHint(formLifePair(form), 0)} title="Health Regen ÷ 4 s + Life Steal from the cycle's main attacks (M). Any = no condition." />
          <SectionBar wide />
          <h3 className={SECTION_HEAD}>Spell cycle</h3>
          {goals.some((entry) => entry.kind === "cycle") && (
            <CheckRow
              checked={selectedGoals.some((id) => isCycleGoal(id))}
              onChange={() => set({ goal: selectedGoals.some((id) => isCycleGoal(id)) ? null : DAMAGE_GOAL_CYCLE })}
              label="Maximise the whole cycle"
              hint={`DPS of ${cycleDigits.join("")} instead of one spell`}
              title="Maximise the damage per second of the whole cycle (every spell once per cast + every main attack hit) instead of one spell - the players' compromise for spells that deal their damage over time."
            />
          )}
          <div className={`mc-slot flex flex-col gap-2 p-3 ${customSelected ? "wbr-tile-on" : ""}`}>
            <span className="text-base font-bold text-zinc-100">Your own cycle</span>
            <span className="text-xs text-zinc-500">Type the spell numbers in the order you cast them (e.g. 1213), or click the spells below.</span>
            <div className="flex items-center gap-1.5">
              <input
                id="wizard-cycle"
                value={customCycle}
                onChange={(event) => setCustomCycle(event.target.value.toUpperCase().replace(/[^1-4M]/g, "").slice(0, 16))}
                onKeyDown={(event) => {
                  if (event.key === "Enter" && customCycle) {
                    set({ cycle: customCycle });
                    next("mana");
                  }
                }}
                placeholder="e.g. 1213 or 4MMM"
                aria-label="Your own spell cycle: 1-4 = spells, M = main attack"
                className="mc-input w-0 min-w-0 flex-1 tabular-nums"
              />
              <button type="button" className="mc-btn mc-btn-sm" disabled={!customCycle} onClick={() => setCustomCycle(customCycle.slice(0, -1))} aria-label="Remove the last spell" title="Remove the last spell">
                ⌫
              </button>
              <button type="button" className="mc-btn mc-btn-sm" disabled={!customCycle} onClick={() => setCustomCycle("")} aria-label="Clear your cycle" title="Clear">
                ×
              </button>
            </div>
            <div className="grid grid-cols-2 gap-2 sm:grid-cols-5">
              <WizardTile disabled={customCycle.length >= 16} onClick={() => setCustomCycle(`${customCycle}M`)} className="p-2" title="A main attack between the spells: Mana Steal and Life Steal only work on hits">
                <span className="text-sm font-bold" style={ts({ color: "#FFAA00" })}>
                  + M · Main attack
                </span>
                <span className="text-xs text-zinc-500">steals mana</span>
              </WizardTile>
              {[1, 2, 3, 4].map((id) => {
                const spell = spells.find((entry) => entry.id === id);
                const known = Boolean(spell && spell.cost !== null && spell.cost !== undefined);
                const name = spell ? spell.name : (CLASS_SPELL_NAMES[playerClass] || [])[id - 1] || `Spell ${id}`;
                return (
                  <WizardTile key={id} disabled={!known || customCycle.length >= 16} onClick={() => setCustomCycle(`${customCycle}${id}`)} className="p-2" title={known ? `${name}: ${(SPELL_CLICKS[playerClass] || SPELL_CLICKS.default)[id - 1]}, ${spell.cost.toFixed(1)} mana` : `${name} isn't in your ability tree`}>
                    <span className="text-sm font-bold" style={ts({ color: known ? "#55FFFF" : "#8c8c8c" })}>
                      + {id} · {name}
                    </span>
                    <span className="text-xs text-zinc-500">{known ? `${spell.cost.toFixed(1)} mana` : "not in tree"}</span>
                  </WizardTile>
                );
              })}
            </div>
            {customCycle && <CycleSteps cycle={customCycle} playerClass={playerClass} spells={spells} compact />}
            {customCycle && (
              <span className="text-xs text-zinc-500">
                {customMana ? cycleManaText(customMana, form.cps) : "Some of these spells aren't in your tree yet."}
              </span>
            )}
            <button
              type="button"
              className="mc-btn self-end"
              disabled={!customCycle}
              onClick={() => {
                set({ cycle: customCycle });
                next("mana");
              }}
            >
              Use this cycle ›
            </button>
          </div>

          <div className="flex flex-col gap-2">
            <h3 className={SECTION_HEAD}>{preset && combos.length > 0 ? `Presets for ${preset}` : "Presets"}</h3>
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
              <WizardTile
                selected={cycleDigits.length === 0}
                onClick={() => {
                  set({ cycle: "" });
                  next("mana");
                }}
                className="items-start text-left"
              >
                <span className="text-base font-bold text-zinc-100">No mana filter</span>
                <span className="text-xs text-zinc-500">Any build, whether or not it can keep casting.</span>
              </WizardTile>
              {cyclePresets.map(renderCyclePreset)}
            </div>
          </div>

          {otherCyclePresets.length > 0 && (
            <details className="flex flex-col gap-1.5">
              <summary className="mc-link cursor-pointer text-sm">Presets from other {playerClass} archetypes ({otherCyclePresets.length})</summary>
              <div className="mt-2 grid grid-cols-1 gap-3 sm:grid-cols-2">{otherCyclePresets.map(renderCyclePreset)}</div>
            </details>
          )}

        </div>
      )}

      {active === "extras" && (
        <div className="flex flex-col gap-4">
          {[
            [
              "Filters",
              "grid grid-cols-1 gap-3 sm:grid-cols-3",
              [
                ["No event items", "Skip limited-time festival items", form.noEvents !== false, () => set({ noEvents: !(form.noEvents !== false) })],
                ["Tradeable only", "Only items you can buy on the Trade Market", Boolean(form.tradeable), () => set({ tradeable: !form.tradeable })],
                ["Avoid negative defences", "No item with a negative elemental defence", normalized.avoidNegativeDefences, () => onOptions({ ...options, avoidNegativeDefences: !normalized.avoidNegativeDefences })],
              ],
            ],
            [
              "How builds are counted",
              "grid grid-cols-1 gap-3 sm:grid-cols-3",
              [
                ["Spend free skill points", "Unneeded points go where they add most, shown as (+X)", form.freeSp !== false, () => set({ freeSp: form.freeSp === false })],
                ["Realistic rolls (50%)", "Off: max rolls, like Wynnbuilder. On: every rolled ID at 50%", form.rolls === "avg", () => set({ rolls: form.rolls === "avg" ? "max" : "avg" })],
                ["Count poison in the goal", "Adds Poison per second to the goal (off: it picked poison-only items)", Boolean(form.poison), () => set({ poison: !form.poison })],
              ],
            ],
          ].map(([group, grid, tiles], index) => (
            <React.Fragment key={group}>
            {index > 0 && <SectionBar wide />}
            <div className="flex flex-col gap-2">
              <h3 className={SECTION_HEAD}>{group}</h3>
              <div className={grid}>
                {tiles.map(([label, hint, on, toggle]) => (
                  <WizardTile key={label} selected={on} onClick={toggle} title={hint}>
                    <span className="text-base font-bold text-zinc-100">{label}</span>
                    <span className="text-xs" style={ts({ color: on ? "#55FF55" : "#8c8c8c" })}>
                      {on ? "✓ on" : "off"}
                    </span>
                    <span className="text-xs text-zinc-500">{hint}</span>
                  </WizardTile>
                ))}
              </div>
            </div>
            </React.Fragment>
          ))}
          <SectionBar wide />
          <RangeControl id="wiz-spd" kind="spd" level={level} heading value={formSpdPair(form)} onChange={(range) => set({ spd: range })} hint="Walk Speed of the whole build (items, sets, ability tree). The default minimum (−20%) keeps the search from slow builds; Any = no condition." />
          <SectionBar wide />
          <div className="flex flex-col gap-2">
            <h3 className={SECTION_HEAD}>
              Weapon attack speed <span className="text-sm normal-case text-zinc-400">(none = any)</span>
            </h3>
            <div className="flex flex-wrap justify-center gap-2">
              {ATTACK_SPEEDS.map((speed) => (
                <WizardTile key={speed} selected={normalized.attackSpeeds.includes(speed)} onClick={() => onOptions({ ...options, attackSpeeds: toggleValue(normalized.attackSpeeds, speed) })} className="shrink-0 grow-0 basis-[calc(25%-0.375rem)] p-2 sm:basis-[calc(14.2857%-0.4286rem)]">
                  <span className="text-sm font-bold text-zinc-100">{ATTACK_SPEED_LABELS[speed]}</span>
                </WizardTile>
              ))}
            </div>
          </div>
        </div>
      )}

      {active === "generate" && (
        <div className="flex flex-col gap-3">
          <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
            {WIZARD_STEPS.filter((entry) => entry.id !== "generate").map((entry) => (
              <button key={entry.id} type="button" className="wbr-tile mc-slot flex flex-col items-start gap-0.5 p-2 text-left" onClick={() => (entry.id === "class" ? onClassReset() : setView(entry.id))}>
                <span className="text-xs uppercase text-zinc-500">{entry.label}</span>
                <span className="text-sm font-bold text-zinc-100">{summary[entry.id] || "—"}</span>
              </button>
            ))}
          </div>
          <button type="button" className="mc-btn mc-btn-primary wbr-why-btn w-full" onClick={onGenerate} disabled={running}>
            {running ? `${progress ? progress.label : "Searching"}…` : "Generate Build"}
          </button>
          {running && (
            <div className="flex items-center gap-2">
              <div className="h-1.5 flex-1" style={ts({ background: "#2b2b2b" })}>
                <div className="h-full transition-all" style={ts({ width: `${Math.round(((progress && progress.fraction) || 0) * 100)}%`, background: "#55FF55" })} />
              </div>
              {progress && progress.threads > 1 && <span className="text-xs text-zinc-500">{progress.threads} threads</span>}
              {onStop && (
                <button type="button" className="mc-btn mc-btn-sm" onClick={onStop}>
                  Stop
                </button>
              )}
            </div>
          )}
        </div>
      )}

    </section>
  );
}

function ClassPicker({ onPick }) {
  return (
    <section className="mc-panel wbr-fade flex flex-col gap-4 p-5">
      <div className="flex flex-col gap-1">
        <h2 className="mc-title text-xl">Choose your class</h2>
        <p className="text-sm text-zinc-300">
          Then your rank, level and ability tree. The generator looks for the strongest hit of the spell (or main attack) you pick, among builds that
          survive your effective HP and pay for your spell cycle.
        </p>
      </div>
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 xl:grid-cols-5">
        {Object.entries(CLASSES).map(([name, config]) => (
          <button key={name} type="button" onClick={() => onPick(name)} className="wbr-class-tile wbr-tile mc-slot flex flex-col items-center gap-2 p-3 text-center">
            {CLASS_PORTRAITS[name] && <img src={CLASS_PORTRAITS[name]} alt="" width={57} height={80} />}
            <span className="text-lg font-bold text-zinc-100">{name}</span>
            <span className="text-xs text-zinc-400">{capitalize(config.weapon)}</span>
            <span className="text-xs text-zinc-500">{config.archetypes.join(" · ")}</span>
          </button>
        ))}
      </div>
    </section>
  );
}

// Czary klasy na danym poziomie z danym drzewkiem: najlepsza broń klasy na ten poziom, bez zbroi i bez Skill Pointów
// z przedmiotów. Koszty są więc "przed Intelligence i ID-kami kosztu" - górna granica tego, co zapłacisz.
function classPreview(playerClass, level, treeSettings, items = ITEM_DB) {
  if (!CLASSES[playerClass]) return null;
  const weapon = representativeWeapon(playerClass, level, treeSettings, items);
  if (!weapon) return null;
  const sp = computeSkillPoints([weapon]);
  const build = { playerClass, level, archetype: null, slots: SLOTS.map((slot) => ({ ...slot, item: slot.id === "weapon" ? weapon : null })), skillPoints: { totals: sp.totals } };
  return { weapon, stats: computeBuildStats(build, treeSettings) };
}

// Mana w cyklu jak w filtrze zakładki New: liczą się tylko czary 1-4 (M/F z kombinacji nie kosztują many),
// cykl trwa 3 kliknięcia na czar ÷ kliknięcia na sekundę.
// Mana cyklu przed wyborem broni (kreator, panel klasy): M liczymy przy normalnej szybkości ataku (2,05 trafienia/s).
function cycleMana(spells, digits, cps, withGain, drain = 0) {
  const spellIds = digits.filter((id) => id !== 0);
  const casts = spellIds.map((id) => spells.find((spell) => spell.id === id)).filter(Boolean);
  if (casts.length !== spellIds.length || digits.length === 0) return null;
  const hps = HITS_PER_SECOND.NORMAL;
  const timing = cycleTiming(digits, Math.max(0.5, cps), hps);
  const seconds = Math.max(0.01, timing.seconds);
  const used = casts.reduce((sum, spell) => sum + (spell.cost || 0), 0) / seconds;
  const gained = withGain ? casts.reduce((sum, spell) => sum + (spell.manaGained || 0), 0) / seconds : 0;
  // drain: dopuszczalny dren z dolnej granicy zakresu many (ujemny = wymagana nadwyżka, 999 = bez granicy)
  const fromItems = Math.max(0, used - gained - BASE_MANA_REGEN / 5 - (Number(drain) || 0));
  // Mana Steal potrzebny, żeby trafienia M w cyklu pokryły resztę: steal/s = trafienia/s × (MS ÷ 3 ÷ hps)
  const steal = timing.hitsPerSecond > 0 ? (fromItems * 3 * hps) / timing.hitsPerSecond : null;
  return { seconds, used, gained, fromItems, regen: fromItems * 5, steal, melee: timing.melee };
}
function cycleManaText(mana, cps) {
  const base = `${mana.used.toFixed(1)} mana/s at ${cps} clicks/s`;
  if (mana.fromItems <= 0) return `${base} · sustained without items`;
  return `${base} · items must give ${mana.fromItems.toFixed(1)}/s ≈ ${Math.ceil(mana.regen)} Mana Regen${mana.steal !== null ? ` or ${Math.ceil(mana.steal)} Mana Steal (normal attack speed)` : " (Mana Steal needs M hits in the cycle)"}`;
}

// Zakładka New bez wygenerowanego buildu: zaraz po wyborze klasy widać jej archetypy, czary z sugerowanego drzewka
// (koszty, kombinacje, obrażenia z samą bronią) i cykle czarów z tym, ile many na sekundę trzeba z przedmiotów.
function ClassOverview({ playerClass, level, levelKnown, apCap, preset, treeIds, treeSettings, form, onPreset, onUseCycle }) {
  const classConfig = CLASSES[playerClass];
  const [viewed, setViewed] = useState(preset || classConfig.archetypes[0]);
  useEffect(() => {
    if (preset) setViewed(preset);
  }, [preset]);
  const arch = classConfig.archetypes.includes(viewed) ? viewed : classConfig.archetypes[0];
  const own = arch === preset && treeIds.length > 0;
  const preview = useMemo(() => {
    const ids = own ? treeIds : suggestAbilityTree(playerClass, arch, apCap).ids;
    const settings = own ? treeSettings : { selected: ids, toggles: {}, sliders: {} };
    const result = classPreview(playerClass, level, settings);
    return result ? { ...result, ids } : null;
  }, [playerClass, arch, level, apCap, own, treeIds, treeSettings]);
  const combo = ARCHETYPE_COMBOS[arch];
  const clicks = SPELL_CLICKS[playerClass] || SPELL_CLICKS.default;
  const names = CLASS_SPELL_NAMES[playerClass];
  const spells = preview ? preview.stats.spells : [];
  const typed = parseCycle(form.cycle);
  const typedMana = typed.length > 0 ? cycleMana(spells, typed, form.cps, form.gain, drainOfRange(formManaRange(form))) : null;
  const need = (mana) =>
    mana.fromItems <= 0 ? (
      <span style={ts({ color: "#55FF55" })}>free: base regen covers it</span>
    ) : (
      <>
        needs <span className="tabular-nums text-zinc-100">{mana.fromItems.toFixed(1)}</span> mana/s from items ≈{" "}
        <span className="tabular-nums text-zinc-100">{Math.ceil(mana.regen)}</span> Mana Regen
        {form.steal && mana.steal !== null ? (
          <>
            {" "}
            or <span className="tabular-nums text-zinc-100">{Math.ceil(mana.steal)}</span> Mana Steal (M hits, normal attack speed)
          </>
        ) : null}
      </>
    );
  return (
    <section className="mc-panel wbr-fade flex flex-col gap-3 p-4">
      <div className="flex items-start gap-3">
        {CLASS_PORTRAITS[playerClass] && <img src={CLASS_PORTRAITS[playerClass]} alt="" width={46} height={64} className="flex-shrink-0" style={{ imageRendering: "auto" }} />}
        <div className="flex min-w-0 flex-1 flex-col gap-1">
          <h2 className="mc-title text-lg leading-tight">
            {playerClass} <span className="text-sm text-zinc-400">· {capitalize(classConfig.weapon)} · level {level}{levelKnown ? "" : " (type yours)"} · {apCap} AP</span>
          </h2>
          <div className="flex flex-wrap gap-1.5" role="tablist" aria-label="Archetype">
            {classConfig.archetypes.map((name) => (
              <button key={name} type="button" role="tab" aria-selected={name === arch} onClick={() => setViewed(name)} className={`mc-btn mc-btn-sm ${name === arch ? "mc-btn-on" : ""}`}>
                {name}
                {name === preset ? " ✓" : ""}
              </button>
            ))}
          </div>
        </div>
      </div>
      {combo && <p className="text-sm text-zinc-300">{combo.summary}</p>}

      <div className="grid gap-3 lg:grid-cols-2">
        <div className="mc-slot flex flex-col gap-1.5 p-3">
          <div className="flex items-baseline justify-between gap-2">
            <h3 className="mc-title text-xs uppercase">Spells · {own ? "your tree" : `suggested ${arch} tree`}</h3>
            {!own && (
              <button type="button" className="mc-link text-xs" onClick={() => onPreset(arch)}>
                Use this tree
              </button>
            )}
          </div>
          <ul className="flex flex-col gap-1 text-sm">
            {names.map((name, index) => {
              const spell = spells.find((entry) => entry.id === index + 1);
              return (
                <li key={name} className="flex flex-wrap items-baseline justify-between gap-x-3">
                  <span className="flex items-center gap-2">
                    <span className="mc-slot px-1.5 text-xs" style={ts({ color: "#FFAA00" })}>
                      {index + 1}
                    </span>
                    <span className="text-zinc-100">{spell ? spell.name : name}</span>
                    <span className="text-xs text-zinc-500">{clicks[index]}</span>
                  </span>
                  <span className="text-xs tabular-nums text-zinc-400">
                    {spell && spell.cost !== null ? `${spell.cost.toFixed(1)} mana` : "not in tree"}
                    {spell && spell.manaGained ? ` · +${formatNumber(spell.manaGained)} back` : ""}
                    {spell && spell.main && spell.main.type === "damage" && spell.main.amount > 0 ? ` · ${formatNumber(Math.round(spell.main.amount))} dmg` : ""}
                    {spell && spell.main && spell.main.type === "heal" ? ` · heals ${formatNumber(Math.round(spell.main.amount))}` : ""}
                  </span>
                </li>
              );
            })}
          </ul>
          <p className="text-xs text-zinc-500">
            {preview ? `Costs before Intelligence and item spell-cost IDs; damage with ${preview.weapon.name} alone, no armour.` : `No ${classConfig.weapon} up to level ${level}.`}
          </p>
        </div>

        <div className="mc-slot flex flex-col gap-2 p-3">
          <h3 className="mc-title text-xs uppercase">
            Spell cycles · {form.cps} clicks/s{form.gain ? " · ability mana counted" : ""}
          </h3>
          <ul className="flex flex-col gap-2">
            {(combo ? combo.combos : []).map((entry) => {
              const digits = parseCycle(entry.cycle);
              const hasSpell = digits.some((id) => id !== 0);
              const mana = hasSpell ? cycleMana(spells, digits, form.cps, form.gain, drainOfRange(formManaRange(form))) : null;
              const current = cycleText(typed) === cycleText(digits) && arch === preset;
              return (
                <li key={entry.name} className="flex flex-col gap-1">
                  <div className="flex flex-wrap items-baseline justify-between gap-x-2">
                    <span className="mc-gold text-sm font-bold">{entry.name}</span>
                    {hasSpell && (
                      <button type="button" className={`mc-btn mc-btn-sm ${current ? "mc-btn-on" : ""}`} onClick={() => onUseCycle(arch, cycleText(digits))} title="Use as the mana filter (and this archetype's tree)">
                        {current ? "In use" : "Use"}
                      </button>
                    )}
                  </div>
                  <CycleSteps cycle={entry.cycle} playerClass={playerClass} spells={spells} />
                  <span className="text-xs text-zinc-400">{entry.note}</span>
                  <span className="text-xs text-zinc-500">
                    {mana ? (
                      <>
                        {mana.used.toFixed(1)} mana/s{mana.gained > 0 ? ` − ${mana.gained.toFixed(1)} from abilities` : ""} → {need(mana)}
                      </>
                    ) : !hasSpell ? (
                      "Main attacks only: no mana filter."
                    ) : (
                      "A spell of this cycle isn't in the tree yet."
                    )}
                  </span>
                </li>
              );
            })}
          </ul>
          {typedMana && (
            <div className="mc-well flex flex-col gap-1.5 p-2">
              <span className="text-xs font-bold text-zinc-200">Your cycle</span>
              <CycleSteps cycle={typed.join("")} playerClass={playerClass} spells={spells} />
              <span className="text-xs text-zinc-300">
                {typedMana.used.toFixed(1)} mana/s → {need(typedMana)}
              </span>
            </div>
          )}
        </div>
      </div>
      {combo && combo.tips && combo.tips.length > 0 && (
        <ul className="flex flex-col gap-0.5 text-xs text-zinc-400">
          {combo.tips.map((tip) => (
            <li key={tip}>• {tip}</li>
          ))}
        </ul>
      )}
    </section>
  );
}

// Podsumowanie filtrów pod nagłówkiem buildu w trybie "New".
function DamageSummary({ build }) {
  const metrics = build.metrics;
  const cycle = metrics.cycle || { ids: [] };
  const chip = (label, value, ok, title) => (
    <span
      key={label}
      className="mc-slot inline-flex items-center gap-1.5 px-2 py-1 text-xs"
      style={ts({ color: ok === false ? "#FF5555" : ok === true ? "#55FF55" : undefined, borderColor: ok === false ? "#FF5555" : ok === true ? "#2F8F2F" : undefined })}
      title={title}
    >
      {ok !== null && (
        <span aria-hidden="true" className="font-bold">
          {ok ? "✓" : "✗"}
        </span>
      )}
      {label} <span className="font-bold tabular-nums">{value}</span>
    </span>
  );
  return (
    <div className="flex flex-wrap items-center gap-2">
      {chip(build.goalName || "Damage", formatNumber(Math.round(metrics.damage)), null, build.goal === DAMAGE_GOAL_MAIN ? "Main attack damage per second - the number this build maximises" : isCycleGoal(build.goal) ? "Damage per second of the whole spell cycle (every spell once per cast + main attack hits) - the number this build maximises" : "One hit of the chosen spell - the number this build maximises")}
      {chip(
        "EHP",
        `${formatNumber(Math.round(metrics.ehp))}${ehpRangeText(metrics) ? ` / ${ehpRangeText(metrics)}` : ""}`,
        ehpRangeText(metrics) ? (metrics.minEhp <= 0 || metrics.ehp >= metrics.minEhp) && !(Number(metrics.maxEhp) > 0 && metrics.ehp > metrics.maxEhp + 1e-9) : null,
        ehpRangeText(metrics) ? "Effective HP of this build and the range you asked for" : "Effective HP (no range set)"
      )}
      {cycle.ids.length > 0 &&
        chip(
          `Cycle ${cycleText(cycle.ids)} @ ${cycle.cps}/s${manaRangeOf(cycle) ? ` (${rangeValueText(manaRangeOf(cycle), rangeUi("mana", build.level))})` : ""}`,
          `${metrics.manaNet >= 0 ? "+" : ""}${metrics.manaNet.toFixed(1)} mana/s`,
          manaRangeOf(cycle) || !metrics.cycleOk ? manaOk(metrics, cycle) : null,
          `${metrics.manaUsed.toFixed(1)} mana/s used, ${(metrics.manaIncome + metrics.manaGain).toFixed(1)} from regen${cycle.steal && metrics.manaSteal ? " + steal from main attacks" : ""}${metrics.manaBuff ? ` + raid buff ${metrics.manaBuff}` : ""}${cycle.gain ? " + abilities" : ""}; the mana range asks for ${rangeValueText(manaRangeOf(cycle), rangeUi("mana", build.level))}`
        )}
      {metrics.sustain !== undefined &&
        chip(
          "Life",
          `${metrics.sustain >= 0 ? "+" : ""}${metrics.sustain.toFixed(1)} HP/s`,
          metrics.requireSustain || lifeRangeOf(metrics) ? sustainPasses(metrics) : null,
          `Life recovery: Health Regen ${formatNumber(Math.round(metrics.hpr))}/4s + Life Steal ${formatNumber(Math.round(metrics.lifeSteal))}${cycle.ids.length ? " from the cycle's main attacks" : "/3s"}${lifeRangeOf(metrics) ? ` - the range asks for ${rangeValueText(lifeRangeOf(metrics), rangeUi("life", build.level))}` : metrics.requireSustain ? " - the filter asks for more than 0" : ""}`
        )}
      {Number.isFinite(metrics.walkSpeed) &&
        chip(
          "Walk",
          `${metrics.walkSpeed > 0 ? "+" : ""}${Math.round(metrics.walkSpeed)}%`,
          metrics.spdRange ? speedPasses(metrics) : null,
          `Walk Speed of the build${metrics.spdRange ? ` - the range asks for ${rangeValueText(metrics.spdRange, rangeUi("spd", build.level))}` : " (no walk speed condition)"}`
        )}
      {chip(
        "Skill points",
        build.skillPoints.free && SKILLS.some((skill) => build.skillPoints.free[skill] > 0)
          ? `${build.skillPoints.minimum} (+${SKILLS.reduce((sum, skill) => sum + build.skillPoints.free[skill], 0)}) / ${build.skillPoints.available}`
          : `${build.skillPoints.required} / ${build.skillPoints.available}`,
        build.skillPoints.valid,
        build.skillPoints.free ? "Skill points the set needs (equip order checked) + (free points spent where they add most)" : "Skill points this set needs, checked in the game's equip order"
      )}
    </div>
  );
}

// Przypięte i wykluczone przedmioty (z kart: Pin/Exclude albo z wyszukiwarki) - z możliwością cofnięcia.
function PinnedList({ options, onChange }) {
  options = { ...options, excluded: options.excluded || [], locked: options.locked || {} };
  return (
    <>
      {(Object.keys(normalizeOptions(options).locked).length > 0 || options.excluded.length > 0) && (
        <div className="flex flex-col gap-2">
          <div className="flex items-center justify-between">
            <span className="text-xs text-zinc-300">Pinned and excluded items</span>
            <button
              type="button"
              onClick={() => onChange({ ...options, locked: {}, excluded: [] })}
              className="mc-link text-xs"
            >
              Clear
            </button>
          </div>
          <ul className="flex flex-wrap gap-2">
            {Object.entries(normalizeOptions(options).locked).map(([slotId, name]) => (
              <li key={slotId} className="mc-slot mc-gold flex items-center gap-1 px-2 py-0.5 text-xs">
                {SLOTS.find((slot) => slot.id === slotId).label}: {name}
                <button
                  type="button"
                  aria-label={`Unpin ${name}`}
                  onClick={() => {
                    const locked = { ...options.locked };
                    delete locked[slotId];
                    onChange({ ...options, locked });
                  }}
                  className="px-1 text-zinc-400 hover:text-white"
                >
                  ✕
                </button>
              </li>
            ))}
            {options.excluded.map((name) => (
              <li key={name} className="mc-slot flex items-center gap-1 px-2 py-0.5 text-xs text-zinc-400 line-through">
                {name}
                <button
                  type="button"
                  aria-label={`Allow ${name} again`}
                  onClick={() => onChange({ ...options, excluded: options.excluded.filter((entry) => entry !== name) })}
                  className="px-1 text-zinc-400 no-underline hover:text-white"
                >
                  ✕
                </button>
              </li>
            ))}
          </ul>
          <p className="text-xs text-zinc-500">Applies on Generate Build.</p>
        </div>
      )}
    </>
  );
}

// Klucz filtrów przedmiotów (do wykrywania, że wynik jest nieaktualny).
function itemFilterKey(normalized) {
  if (!normalized) return "";
  return JSON.stringify([normalized.excludedTiers, normalized.budget, normalized.onlyListed, normalized.locked, normalized.excluded, normalized.attackSpeeds, normalized.avoidNegativeDefences]);
}

// Pola "Avoid negative defences" i "Live on the Trade Market" (sekcja Items › Filters w lewym panelu).
function ItemFilterChecks({ options, onChange }) {
  const normalized = normalizeOptions(options);
  const live = hasLiveData();
  return (
    <>
      <CheckRow id="new-no-negdef" checked={normalized.avoidNegativeDefences} onChange={() => onChange({ ...options, avoidNegativeDefences: !normalized.avoidNegativeDefences })} label="Avoid negative defences" title="Skips armour, accessories and weapons with a negative elemental defence. Pinned items stay." />
      <CheckRow
        id="new-live"
        disabled={!live}
        checked={live && normalized.onlyListed}
        onChange={() => onChange({ ...options, onlyListed: !normalized.onlyListed })}
        label="Live on the Trade Market"
        hint={live ? formatClock(PRICE_DATA.liveAt) : "no data here"}
        style={ts(live ? undefined : { opacity: 0.55 })}
        title={live ? "Only items listed on the Trade Market right now (WynnVentory snapshot). Pinned items stay." : "Needs live Trade Market data: the GitHub Pages version fetches it from WynnVentory (WYNNVENTORY_KEY secret, see the README)."}
      />
    </>
  );
}
// Filtry przedmiotów zakładki głównej: przedmiot do zbudowania wokół, rzadkości, budżet i rynek.
function ItemFilters({ options, onChange, weaponType, level, onBrowse }) {
  const normalized = normalizeOptions(options);
  const excludedTiers = normalized.excludedTiers;
  const active = Object.keys(normalized.locked).length + normalized.excluded.length + excludedTiers.length + (normalized.budget ? 1 : 0) + (normalized.onlyListed ? 1 : 0);
  const [open, setOpen] = useState(active > 0);
  const market = hasPriceData() || hasLiveData();
  const live = hasLiveData();
  return (
    <div className="flex flex-col gap-2.5">
      <div className="flex flex-col gap-1.5">
        <span className={SUB_HEAD}>Weapon attack speed</span>
        {/* 3 + 3 + 1 przyciski równej szerokości, ostatni wyśrodkowany (siatka 6 kolumn, każdy przycisk na 2) */}
        <div className="grid grid-cols-6 gap-1">
          {ATTACK_SPEEDS.map((speed, index) => (
            <ToggleChip
              key={speed}
              pressed={normalized.attackSpeeds.includes(speed)}
              onClick={() => onChange({ ...options, attackSpeeds: toggleValue(normalized.attackSpeeds, speed) })}
              className={`col-span-2 w-full whitespace-nowrap px-0.5 text-center ${index === ATTACK_SPEEDS.length - 1 && ATTACK_SPEEDS.length % 3 === 1 ? "col-start-3" : ""}`}
              style={{ fontSize: "12px" }}
            >
              {ATTACK_SPEED_LABELS[speed]}
            </ToggleChip>
          ))}
        </div>
        <span className="text-xs text-zinc-500">{normalized.attackSpeeds.length > 0 ? "Only weapons with the checked speeds." : "None checked = any speed."}</span>
      </div>
      <button type="button" className="mc-link self-start text-xs" aria-expanded={open} onClick={() => setOpen(!open)}>
        {open ? "▾" : "▸"} Pin items · rarities{market ? " · budget" : ""}
        {active > 0 ? ` (${active} set)` : ""}
      </button>
      {open && (
    <div className="wbr-drop flex flex-col gap-3">
      <PinItemSearch options={options} onChange={onChange} weaponType={weaponType} level={level} onBrowse={onBrowse} />
      <PinnedList options={options} onChange={onChange} />
      <div className="flex flex-col gap-1.5">
        <span className="text-xs text-zinc-300">Allowed rarities</span>
        <div className="flex flex-wrap gap-1.5">
          {ITEM_TIERS.map((tier) => (
            <ToggleChip key={tier} pressed={!excludedTiers.includes(tier)} color={RARITY_COLORS[tier]} onClick={() => onChange({ ...options, excludedTiers: toggleValue(excludedTiers, tier) })}>
              {tier}
            </ToggleChip>
          ))}
        </div>
      </div>
      {hasPriceData() && <BudgetInput options={options} onChange={onChange} />}
    </div>
      )}
    </div>
  );
}

