const WB_ITEM_BY_ID = new Map(Object.entries((WB_IDS && WB_IDS.items) || {}).map(([name, id]) => [id, name]));
// Dekoder kodu Wynnbuildera (to, co stoi po "#" w linku buildera; binarny format 12, ENCODING.md) - odwrotność
